    function closeReqQuoteVendorPick() {
        unbindReqQuoteVendorPickReposition();
        document.querySelectorAll('.spare-req-quote-vendor-menu-portal').forEach(el => el.remove());
        document.querySelectorAll('.spare-req-quote-vendor-pick.is-open').forEach(el => el.classList.remove('is-open'));
    }

    let _reqQuoteVendorPickIgnoreClose = false;

    function buildReqQuoteVendorRegisteredRows(vendors, highlightName = '') {
        const hi = String(highlightName || '').trim().toLowerCase();
        return (vendors || []).map(v => {
            const vid = escAttr(v.id || '');
            const vname = escAttr(v.name || '');
            const isHi = hi && String(v.name || '').trim().toLowerCase() === hi;
            return `<div class="spare-req-quote-vendor-row${isHi ? ' is-new' : ''}">
                <button type="button" class="spare-req-quote-vendor-item"
                    data-vendor-id="${vid}" data-vendor-name="${vname}">${esc(v.name)}</button>
                <button type="button" class="spare-req-quote-vendor-act spare-req-quote-vendor-edit-btn"
                    data-vendor-id="${vid}" data-vendor-name="${vname}" title="Edit vendor" aria-label="Edit vendor">✎</button>
                <button type="button" class="spare-req-quote-vendor-act spare-req-quote-vendor-del-btn"
                    data-vendor-id="${vid}" title="Delete vendor" aria-label="Delete vendor">×</button>
            </div>`;
        }).join('');
    }

    function reqQuoteVendorPickIndexValue(menu) {
        return String(menu?.querySelector('.spare-req-quote-vendor-index-input')?.value || '').trim();
    }

    function reqQuoteVendorsFilteredByIndex(registered, indexFilter = '') {
        const filter = String(indexFilter || '').trim().toLowerCase();
        const list = registered || [];
        if (!filter) return list;
        return list.filter(v => String(v.name || '').toLowerCase().includes(filter));
    }

    function buildReqQuoteVendorPickHtml(slot, picker, highlightName = '', indexFilter = '') {
        const filter = String(indexFilter || '').trim();
        const registered = reqQuoteVendorsFilteredByIndex(picker.registered, filter);
        const registeredHtml = registered.length
            ? buildReqQuoteVendorRegisteredRows(registered, highlightName)
            : `<div class="spare-req-quote-vendor-empty muted">${filter ? 'No matching vendors.' : 'No registered vendors yet.'}</div>`;
        const showClear = filter.length > 0;
        return `<div class="spare-req-quote-vendor-head muted">Registered vendors</div>
            <div class="spare-req-quote-vendor-index-row">
                <div class="spare-req-quote-vendor-index-wrap">
                    <input type="text" class="spare-req-quote-vendor-index-input" placeholder="Search vendor" autocomplete="off"
                        value="${escAttr(filter)}" onclick="event.stopPropagation()" onmousedown="event.stopPropagation()">
                    <button type="button" class="spare-req-quote-vendor-index-clear spare-req-quote-vendor-act${showClear ? '' : ' is-hidden'}"
                        title="Clear index" aria-label="Clear index">×</button>
                </div>
            </div>
            <div class="spare-req-quote-vendor-registered">${registeredHtml}</div>
            <div class="spare-req-quote-vendor-add">
                <div class="spare-req-quote-vendor-head muted">Add new vendor</div>
                <div class="spare-req-quote-vendor-add-row">
                    <input type="text" class="spare-req-quote-vendor-add-input" placeholder="Company name" autocomplete="off"
                        onclick="event.stopPropagation()" onmousedown="event.stopPropagation()">
                    <button type="button" class="btn btn-sm spare-req-quote-vendor-add-btn">Add</button>
                </div>
            </div>`;
    }

    function refreshReqQuoteVendorRegisteredOnly(slot, highlightName = '') {
        const menu = document.querySelector(`.spare-req-quote-vendor-menu-portal[data-quote-vendor-slot="${slot}"]`);
        if (!menu) return;
        const indexFilter = reqQuoteVendorPickIndexValue(menu);
        const picker = reqQuoteVendorPickerData();
        if (window.TVC_Vendors?.listAll) picker.registered = TVC_Vendors.listAll();
        const registered = reqQuoteVendorsFilteredByIndex(picker.registered, indexFilter);
        const listEl = menu.querySelector('.spare-req-quote-vendor-registered');
        if (listEl) {
            listEl.innerHTML = registered.length
                ? buildReqQuoteVendorRegisteredRows(registered, highlightName)
                : `<div class="spare-req-quote-vendor-empty muted">${indexFilter ? 'No matching vendors.' : 'No registered vendors yet.'}</div>`;
        }
        const clearBtn = menu.querySelector('.spare-req-quote-vendor-index-clear');
        if (clearBtn) clearBtn.classList.toggle('is-hidden', !indexFilter);
    }

    function reqQuoteVendorPickerData() {
        return window.TVC_Vendors?.listForPicker?.() || { registered: [] };
    }

    function refreshReqQuoteVendorPickMenu(slot, highlightName = '') {
        const menu = document.querySelector(`.spare-req-quote-vendor-menu-portal[data-quote-vendor-slot="${slot}"]`);
        if (!menu) return;
        const indexFilter = reqQuoteVendorPickIndexValue(menu);
        const picker = reqQuoteVendorPickerData();
        if (window.TVC_Vendors?.listAll) picker.registered = TVC_Vendors.listAll();
        menu.innerHTML = buildReqQuoteVendorPickHtml(slot, picker, highlightName, indexFilter);
        bindReqQuoteVendorPickMenu(menu, slot);
        positionReqQuoteVendorPickMenu(slot);
        const indexInput = menu.querySelector('.spare-req-quote-vendor-index-input');
        if (indexInput) {
            indexInput.focus();
            indexInput.setSelectionRange(indexInput.value.length, indexInput.value.length);
        }
    }

    function bindReqQuoteVendorPickMenu(menu, slot) {
        if (!menu || menu.dataset.reqQuotePickBound === '1') return;
        menu.dataset.reqQuotePickBound = '1';
        menu.addEventListener('mousedown', (e) => e.stopPropagation());
        menu.addEventListener('input', (e) => {
            if (e.target.matches('.spare-req-quote-vendor-index-input')) {
                refreshReqQuoteVendorRegisteredOnly(slot);
            }
        });
        menu.addEventListener('click', (e) => {
            e.stopPropagation();
            if (e.target.closest('.spare-req-quote-vendor-index-clear')) {
                e.preventDefault();
                const input = menu.querySelector('.spare-req-quote-vendor-index-input');
                if (input) {
                    input.value = '';
                    input.focus();
                }
                refreshReqQuoteVendorRegisteredOnly(slot);
                return;
            }
            if (e.target.closest('.spare-req-quote-vendor-add-btn')) {
                e.preventDefault();
                submitReqQuoteVendorAdd(slot, e);
                return;
            }
            const editBtn = e.target.closest('.spare-req-quote-vendor-edit-btn');
            if (editBtn) {
                e.preventDefault();
                editReqQuoteVendor(slot, editBtn.dataset.vendorId, editBtn.dataset.vendorName);
                return;
            }
            const delBtn = e.target.closest('.spare-req-quote-vendor-del-btn');
            if (delBtn) {
                e.preventDefault();
                deleteReqQuoteVendor(slot, delBtn.dataset.vendorId);
                return;
            }
            const pickBtn = e.target.closest('.spare-req-quote-vendor-item');
            if (pickBtn) {
                e.preventDefault();
                pickReqQuoteVendor(slot, pickBtn.dataset.vendorId, pickBtn.dataset.vendorName);
            }
        });
        menu.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' && e.target.matches('.spare-req-quote-vendor-add-input')) {
                e.preventDefault();
                e.stopPropagation();
                submitReqQuoteVendorAdd(slot, e);
            }
        });
    }

    function applyReqQuoteVendorToSlot(slot, vendorId, vendorName) {
        const req = getReqWorkSession();
        if (!req) return;
        const name = String(vendorName || '').trim();
        if (!name) return;
        let id = String(vendorId || '').trim();
        if (!id && window.TVC_Vendors?.listAll) {
            id = window.TVC_Vendors.listAll().find(v => v.name.toLowerCase() === name.toLowerCase())?.id || '';
        }
        const q = ensureReqWorkQuoteState(req);
        const v = q.vendors[slot];
        if (!v) return;
        v.vendorId = id;
        v.vendorName = name;
        refreshReqWorkQuoteHeadDom();
        if (reqWorkHqQuoteViewActive()) refreshReqWorkListUi();
        touchReqWorkHqDraft();
    }

    function toggleReqQuoteVendorPick(ev, slot) {
        if (reqWorkHqEvalStageActive()) return;
        ev?.stopPropagation?.();
        const trigger = ev?.currentTarget;
        if (!trigger) return;
        const existing = document.querySelector(`.spare-req-quote-vendor-menu-portal[data-quote-vendor-slot="${slot}"]`);
        if (existing) {
            closeReqQuoteVendorPick();
            return;
        }
        closeReqQuoteVendorPick();
        closeReqQuoteCurrencyPick();
        const picker = reqQuoteVendorPickerData();
        const menu = document.createElement('div');
        menu.className = 'spare-req-quote-vendor-menu spare-req-quote-vendor-menu-portal';
        menu.setAttribute('data-quote-vendor-slot', String(slot));
        menu.innerHTML = buildReqQuoteVendorPickHtml(slot, picker);
        bindReqQuoteVendorPickMenu(menu, slot);
        document.body.appendChild(menu);
        positionReqQuoteVendorPickMenu(slot);
        bindReqQuoteVendorPickReposition(slot);
        const indexInput = menu.querySelector('.spare-req-quote-vendor-index-input');
        if (indexInput) {
            requestAnimationFrame(() => indexInput.focus());
        }
    }

    async function submitReqQuoteVendorAdd(slot, ev) {
        ev?.stopPropagation?.();
        ev?.preventDefault?.();
        const menu = document.querySelector(`.spare-req-quote-vendor-menu-portal[data-quote-vendor-slot="${slot}"]`);
        const input = menu?.querySelector('.spare-req-quote-vendor-add-input');
        const name = String(input?.value || '').trim();
        if (!name) {
            input?.focus();
            return;
        }
        if (!window.TVC_Vendors?.register) {
            await TVC_Dialog.alert('Vendor registry is not loaded. Please refresh the page.');
            showReqQuoteVendorAddStatus(slot, 'Vendor registry not loaded.', true);
            return;
        }
        const entry = TVC_Vendors.register(name);
        if (!entry) {
            showReqQuoteVendorAddStatus(slot, 'Enter a valid company name (letters required).', true);
            return;
        }
        applyReqQuoteVendorToSlot(slot, entry.id || '', entry.name || name);
        _reqQuoteVendorPickIgnoreClose = true;
        refreshReqQuoteVendorPickMenu(slot, entry.name || name);
        showReqQuoteVendorAddStatus(slot, `Registered: ${entry.name || name}`);
        setTimeout(() => { _reqQuoteVendorPickIgnoreClose = false; }, 0);
    }

    function showReqQuoteVendorAddStatus(slot, message, isError = false) {
        const menu = document.querySelector(`.spare-req-quote-vendor-menu-portal[data-quote-vendor-slot="${slot}"]`);
        if (!menu) return;
        let el = menu.querySelector('.spare-req-quote-vendor-add-status');
        if (!el) {
            el = document.createElement('div');
            el.className = 'spare-req-quote-vendor-add-status';
            menu.querySelector('.spare-req-quote-vendor-add')?.appendChild(el);
        }
        el.className = `spare-req-quote-vendor-add-status${isError ? ' is-error' : ' is-ok'}`;
        el.textContent = message;
    }

    function pickReqQuoteVendor(slot, vendorId, vendorName) {
        if (reqWorkHqEvalStageActive()) return;
        const name = String(vendorName || '').trim();
        if (!name) return;
        const id = String(vendorId || '').trim();
        applyReqQuoteVendorToSlot(slot, id, name);
        closeReqQuoteVendorPick();
    }

    function editReqQuoteVendor(slot, vendorId, currentName) {
        if (!window.TVC_Vendors?.rename) return;
        const next = prompt('Edit vendor name:', currentName || '');
        if (next == null) return;
        const updated = TVC_Vendors.rename(vendorId, next);
        if (!updated) {
            showReqQuoteVendorAddStatus(slot, 'Invalid vendor name.', true);
            return;
        }
        const req = getReqWorkSession();
        const q = req && ensureReqWorkQuoteState(req);
        if (q) {
            q.vendors.forEach(v => {
                if (v.vendorId === vendorId) {
                    v.vendorId = updated.id;
                    v.vendorName = updated.name;
                }
            });
        }
        refreshReqWorkQuoteHeadDom();
        refreshReqQuoteVendorPickMenu(slot, updated.name);
        if (reqWorkHqQuoteViewActive()) refreshReqWorkListUi();
        showReqQuoteVendorAddStatus(slot, `Updated: ${updated.name}`);
    }

    async function deleteReqQuoteVendor(slot, vendorId) {
        if (!window.TVC_Vendors?.remove) return;
        const v = TVC_Vendors.findById(vendorId);
        if (!v) return;
        if (!await TVC_Dialog.confirm({ message: `Remove vendor "${v.name}"?` })) return;
        TVC_Vendors.remove(vendorId);
        const req = getReqWorkSession();
        const q = req && ensureReqWorkQuoteState(req);
        if (q) {
            q.vendors.forEach(vendor => {
                if (vendor.vendorId === vendorId) {
                    vendor.vendorId = '';
                    vendor.vendorName = '';
                }
            });
        }
        refreshReqWorkQuoteHeadDom();
        refreshReqQuoteVendorPickMenu(slot);
        if (reqWorkHqQuoteViewActive()) refreshReqWorkListUi();
        showReqQuoteVendorAddStatus(slot, `Removed: ${v.name}`);
    }

    function reqWorkSetQuoteCurrency(slot, currency) {
        if (reqWorkHqEvalStageActive()) return;
        const req = getReqWorkSession();
        if (!req) return;
        const q = ensureReqWorkQuoteState(req);
        const v = q.vendors[slot];
        if (!v) return;
        v.currency = String(currency || 'USD').trim().toUpperCase() || 'USD';
        refreshReqWorkQuoteHeadDom();
        if (reqWorkHqQuoteViewActive()) refreshReqWorkListUi();
        touchReqWorkHqDraft();
    }

    function reqWorkToggleQuoteColCheck(slot, checked) {
        if (reqWorkHqEvalStageActive()) return;
        const req = getReqWorkSession();
        if (!req) return;
        const v = reqWorkQuoteVendors(req)[slot];
        if (!reqWorkQuoteSlotReady(v)) return;
        const q = ensureReqWorkQuoteState(req);
        (req.lines || []).forEach((line) => {
            const sid = reqWorkSpareIdKey(line.spare_part_id);
            if (!sid) return;
            const key = reqWorkQuoteVendorKey(slot, sid);
            if (checked) q.rowChecks[key] = true;
            else delete q.rowChecks[key];
        });
        refreshReqWorkQuoteHeadDom();
        if (reqWorkHqQuoteViewActive()) refreshReqWorkListUi();
        syncReqWorkQuoteTotalsDom();
        touchReqWorkHqDraft();
    }

    function reqWorkToggleQuoteRowCheck(slot, spareId, checked) {
        if (reqWorkHqEvalStageActive()) return;
        const req = getReqWorkSession();
        if (!req) return;
        const v = reqWorkQuoteVendors(req)[slot];
        if (!reqWorkQuoteSlotReady(v)) return;
        const q = ensureReqWorkQuoteState(req);
        const key = reqWorkQuoteVendorKey(slot, spareId);
        if (checked) q.rowChecks[key] = true;
        else delete q.rowChecks[key];
        refreshReqWorkQuoteHeadDom();
        syncReqWorkQuoteTotalsDom();
        touchReqWorkHqDraft();
    }

    function reqWorkSetQuotePrice(slot, spareId, raw, opts = {}) {
        if (reqWorkHqEvalStageActive()) return;
        const req = getReqWorkSession();
        if (!req) return;
        const q = ensureReqWorkQuoteState(req);
        const key = reqWorkQuoteVendorKey(slot, spareId);
        const val = parseQuoteAmountInput(raw);
        if (val == null) delete q.prices[key];
        else q.prices[key] = val;
        syncReqWorkQuoteTotalsDom();
        if (opts.syncOnly) syncReqWorkHqFlowBtns();
        else touchReqWorkHqDraft();
    }

    function reqWorkListHeadHtml() {
        const quote = reqWorkHqQuoteViewActive();
        const req = getReqWorkSession();
        const tableCls = `spare-data-table spare-data-head spare-data-table-req${quote ? ' is-quote-view' : ''}`;
        const thead = quote ? spareReqQuoteTableHeadHtml(req) : SPARE_REQ_TABLE_HEAD;
        return `<div id="reqWorkListHeadTrack" class="spare-head-track"><table class="${tableCls}">
            ${reqWorkActiveColgroup()}
            ${thead}
        </table></div>`;
    }

    function reqWorkReceivedQtyEditable() {
        const req = getReqWorkSession();
        if (!req) return false;
        const m = modState(getState());
        const st = getState();
        if (isRequisitionListWindow(m)) {
            if (isReqListHqUser(st)) {
                if (reqListWorkflowLabel(req) !== 'Received') return false;
                return !!m.reqWorkListEditing;
            }
            if (reqVesselReceivedExportComplete(req)) return false;
            if (m.reqWorkVesselFlowStage === 'received') return true;
            return false;
        }
        if (m.reqWorkEditMode && !m.reqWorkPreview) return true;
        if (reqVesselReceivedExportComplete(req)) return false;
        return reqListDisplayStatusLabel(req, st) === VESSEL_REQ_LIST_STATUS.RECEIVED;
    }

    function reqWorkReceivedCellHtml(s, sid) {
        const line = reqLineForSpareRow(s);
        const qty = line ? (Number(line.qty_received) || 0) : 0;
        if (!reqWorkReceivedQtyEditable()) return esc(String(qty));
        return `<input type="number" min="0" step="1" inputmode="numeric" pattern="[0-9]*" class="spare-req-qty-input spare-req-rcvd-qty-input" value="${qty}"
            onclick="event.stopPropagation()" onmousedown="event.stopPropagation()"
            onfocus="event.stopPropagation();this.select()"
            oninput="TVC_SpareMenu.reqWorkSetReceivedQty('${sid}', this.value, { syncOnly: true })"
            onchange="TVC_SpareMenu.reqWorkSetReceivedQty('${sid}', this.value)">`;
    }

    function consumeQtyCellHtml(s, sid) {
        const line = _consumeLineBySpareId?.get(consumeSpareIdKey(s.id));
        if (!line) return '0';
        const qty = Number(line.qty_consumed) || 0;
        const overCls = spareCosExceedsRob('consume', s) ? ' spare-cos-over-rob-input' : '';
        if (!consumeListEditable()) return esc(String(qty));
        return `<input type="number" min="0" step="1" inputmode="numeric" pattern="[0-9]*" class="spare-consume-qty-input${overCls}" value="${qty}"
            onclick="event.stopPropagation()" onmousedown="event.stopPropagation()"
            onfocus="event.stopPropagation();this.select()"
            onchange="TVC_SpareMenu.consumeSetQty('${sid}', this.value)">`;
    }

    function receiveSpareIdKey(id) {
        return id == null ? '' : String(id);
    }

    function receiveSameSpareId(a, b) {
        return receiveSpareIdKey(a) === receiveSpareIdKey(b);
    }

    function getReceiveSession() {
        return _receiveDraft;
    }

    function syncReceiveLineMap() {
        const map = new Map();
        (_receiveDraft?.lines || []).forEach(l => {
            const id = receiveSpareIdKey(l.spare_part_id);
            if (id) map.set(id, l);
        });
        _receiveLineBySpareId = map;
    }

    function receiveRowChecked(s) {
        return !!_receiveLineBySpareId?.get(receiveSpareIdKey(s.id));
    }

    function receiveCheckedSpareCount(st) {
        return (st.spares || []).reduce((n, s) => n + (receiveRowChecked(canon(s)) ? 1 : 0), 0);
    }

    function receiveSelectedBtnMeta(st) {
        const m = modState(st);
        const n = receiveCheckedSpareCount(st);
        const on = !!m.receiveShowSelectedOnly;
        return {
            label: on ? `Show All (${n})` : `Selected Items${n >= 1 ? ` (${n})` : ''}`,
            title: on ? 'Show full parts list' : (n >= 1 ? 'Show selected parts only' : 'Select parts using the checkbox'),
            disabled: !on && n < 1,
            active: on,
        };
    }

    function receiveSelectedCountLabel(st, visibleCount) {
        const allCanon = (st.spares || []).length;
        if (spareListSearchQuery(st)) return `${visibleCount} / ${allCanon}`;
        return `${receiveCheckedSpareCount(st)} selected`;
    }

    function receiveQtyCellHtml(s, sid) {
        const line = _receiveLineBySpareId?.get(receiveSpareIdKey(s.id));
        if (!line) return '0';
        const qty = Number(line.qty_received) || 0;
        return `<input type="number" min="0" step="1" inputmode="numeric" pattern="[0-9]*" class="spare-receive-qty-input" value="${qty}"
            onclick="event.stopPropagation()" onmousedown="event.stopPropagation()"
            onfocus="event.stopPropagation();this.select()"
            onchange="TVC_SpareMenu.receiveSetQty('${sid}', this.value)">`;
    }

    function wrSpareIdKey(id) {
        return id == null ? '' : String(id);
    }

    function wrSameSpareId(a, b) {
        return wrSpareIdKey(a) === wrSpareIdKey(b);
    }

    function syncWrLineMap() {
        const map = new Map();
        (getState()._wrUsedParts || []).forEach(l => {
            const id = wrSpareIdKey(l.spare_part_id);
            if (id) map.set(id, l);
        });
        _wrSpareLineBySpareId = map;
    }

    function wrSpareRowChecked(s) {
        return !!_wrSpareLineBySpareId?.get(wrSpareIdKey(s.id));
    }

    function wrSpareCheckedCount(st) {
        return (st.spares || []).reduce((n, s) => n + (wrSpareRowChecked(canon(s)) ? 1 : 0), 0);
    }

    function wrSpareSelectedBtnMeta(st) {
        const m = modState(st);
        const n = wrSpareCheckedCount(st);
        const on = !!m.wrSpareShowSelectedOnly;
        return {
            label: on ? `Show All (${n})` : `Selected Items${n >= 1 ? ` (${n})` : ''}`,
            title: on ? 'Show full parts list' : (n >= 1 ? 'Show selected parts only' : 'Select parts using the checkbox'),
            disabled: !on && n < 1,
            active: on,
        };
    }

    function wrSpareSelectedCountLabel(st, visibleCount) {
        const allCanon = (st.spares || []).length;
        if (spareListSearchQuery(st)) return `${visibleCount} / ${allCanon}`;
        return `${wrSpareCheckedCount(st)} selected`;
    }

    function buildWrLine(spare, qty) {
        const c = canon(spare);
        return {
            spare_part_id: c.id || spare.id,
            part_no: spareNumbering(c) || spare.part_no || '',
            name: c.name || spare.name || '',
            universal_code: c.universalItemCode || spare.universal_code || '',
            qty_on_hand: TVC_Inventory.currentStock(spare),
            qty_used: Math.max(0, Math.floor(Number(qty) || 0)),
        };
    }

    function wrQtyCellHtml(s, sid, ro = false) {
        const line = _wrSpareLineBySpareId?.get(wrSpareIdKey(s.id));
        if (!line) return '0';
        const qty = Number(line.qty_used) || 0;
        const over = spareCosExceedsRob('wrSpare', s);
        const overCls = over ? ' spare-cos-over-rob-input' : '';
        if (ro) return String(qty);
        return `<input type="number" min="0" step="1" inputmode="numeric" pattern="[0-9]*" class="spare-consume-qty-input${overCls}" value="${qty}"
            onclick="event.stopPropagation()" onmousedown="event.stopPropagation()"
            onfocus="event.stopPropagation();this.select()"
            onchange="TVC_SpareMenu.wrSpareSetQty('${sid}', this.value)">`;
    }

    function spareRobQty(spare, line) {
        if (spare) return Number(TVC_Inventory.currentStock(spare)) || 0;
        return Number(line?.qty_on_hand) || 0;
    }

    function qtyExceedsRob(qty, spare, line) {
        const n = Number(qty) || 0;
        if (n <= 0) return false;
        return n > spareRobQty(spare, line);
    }

    function spareCosExceedsRob(ctx, s) {
        if (ctx === 'wrSpare') {
            const line = _wrSpareLineBySpareId?.get(wrSpareIdKey(s.id));
            return !!(line && qtyExceedsRob(line.qty_used, s, line));
        }
        if (ctx === 'consume') {
            const line = _consumeLineBySpareId?.get(consumeSpareIdKey(s.id));
            return !!(line && qtyExceedsRob(line.qty_consumed, s, line));
        }
        return false;
    }

    function lineCosExceedsRob(line, spareRaw) {
        if (!line) return false;
        const cos = Number(line.qty_used ?? line.qty_consumed) || 0;
        return qtyExceedsRob(cos, spareRaw, line);
    }

    function formatCosOverRobAlert(items) {
        if (!items.length) return '';
        const lines = items.map(it => `${it.name}: Cos ${it.cos} > ROB ${it.rob}`);
        return `Consumption (Cos) exceeds ROB.\n\n${lines.join('\n')}`;
    }

    function wrSpareOverRobItems(st) {
        const spares = st?.spares || [];
        const byId = new Map();
        const bags = [st?._wrUsedParts, st?._dfUsedParts, st?._wpUsedParts];
        for (const rows of bags) {
            for (const line of rows || []) {
                const qty = Number(line.qty_used ?? line.qty_consumed ?? line.qty_estimated) || 0;
                if (qty <= 0) continue;
                const spare = spares.find(s => wrSameSpareId(s.id, line.spare_part_id));
                if (!qtyExceedsRob(qty, spare, line)) continue;
                const id = wrSpareIdKey(line.spare_part_id) || line.part_no || line.name;
                if (!id) continue;
                const rec = {
                    name: line.name || spare?.name || line.part_no || 'item',
                    code: line.part_no || spare?.part_no || line.name || 'item',
                    cos: qty,
                    rob: spareRobQty(spare, line),
                };
                const prev = byId.get(id);
                if (!prev || rec.cos > prev.cos) byId.set(id, rec);
            }
        }
        return Array.from(byId.values());
    }

    function consumeOverRobItems() {
        const draft = getConsumeSession();
        const spares = getState()?.spares || [];
        return (draft?.lines || []).map(line => {
            const qty = Number(line.qty_consumed ?? line.qty) || 0;
            if (qty <= 0) return null;
            const spare = spares.find(s => consumeSameSpareId(s.id, line.spare_part_id));
            if (!qtyExceedsRob(qty, spare, line)) return null;
            return {
                name: line.name || spare?.name || line.part_no || 'item',
                code: line.part_no || spare?.part_no || line.name || 'item',
                cos: qty,
                rob: spareRobQty(spare, line),
            };
        }).filter(Boolean);
    }

    function formatStockShortageConfirm(items) {
        if (!items.length) return '';
        const lines = items.map(it =>
            `Insufficient stock: ${it.code || it.name} (on hand ${it.rob}, requested ${it.cos})`);
        return `${lines.join('\n')}\n\nProceed anyway?`;
    }

    function toEnglishStockMessage(err) {
        const part = err?.part;
        const onHand = err?.onHand;
        const requested = err?.requested;
        if (part != null && onHand != null && requested != null) {
            return `Insufficient stock: ${part} (on hand ${onHand}, requested ${requested})`;
        }
        const raw = String(err?.message || '').trim();
        if (!raw || /[\uac00-\ud7a3]/.test(raw)) return 'Insufficient stock.';
        return raw;
    }

    function stockShortageDialogOpts(message) {
        return {
            title: 'Insufficient stock',
            message,
            confirmLabel: 'Yes',
            cancelLabel: 'Cancel',
        };
    }

    let _stockForceOk = false;

    function consumeStockForceOk() {
        return !!_stockForceOk;
    }

    function clearStockForceOk() {
        _stockForceOk = false;
    }

    async function confirmProceedDespiteStock(err) {
        const msg = toEnglishStockMessage(err);
        return !!(await TVC_Dialog.confirm(stockShortageDialogOpts(`${msg}\n\nProceed anyway?`)));
    }

    /** Returns false if Cos > ROB and the user cancels — stay on the current
     *  draft / modify editor; do not save and do not revert to view. */
    async function confirmIfCosExceedsRob(kind) {
        _stockForceOk = false;
        const items = kind === 'consume' ? consumeOverRobItems() : wrSpareOverRobItems(getState());
        const msg = formatStockShortageConfirm(items);
        if (!msg) return true;
        const ok = !!(await TVC_Dialog.confirm(stockShortageDialogOpts(msg)));
        if (ok) _stockForceOk = true;
        return ok;
    }

    async function alertIfCosExceedsRob(kind) {
        return confirmIfCosExceedsRob(kind);
    }

    function wrSpareListEditable() {
        const m = modState(getState());
        return !!m.wrSpareOpen && !m.wrSpareReadonly;
    }

    function updateSpareHeadCheckAll() {
        const el = document.getElementById('spareHeadChkAll');
        if (!el) return;
        const batchMap = getState().spareListSelected || {};
        const list = _cachedList || [];
        if (!list.length) {
            el.checked = false;
            el.indeterminate = false;
            return;
        }
        let n = 0;
        list.forEach(s => { if (batchMap[s.id]) n++; });
        el.checked = n === list.length;
        el.indeterminate = n > 0 && n < list.length;
    }

    function updateReqWorkHeadCheckAll() {
        const el = document.getElementById('reqWorkHeadChkAll');
        if (!el) return;
        const locked = reqWorkFormLocked();
        const list = _reqWorkCachedList || [];
        if (!list.length || locked) {
            el.checked = false;
            el.indeterminate = false;
            el.disabled = locked || !list.length;
            return;
        }
        el.disabled = false;
        let n = 0;
        list.forEach(s => { if (reqWorkRowChecked(s)) n++; });
        el.checked = n === list.length;
        el.indeterminate = n > 0 && n < list.length;
    }

    function toggleSpareAll(checked) {
        const st = getState();
        if (!st.spareListSelected) st.spareListSelected = {};
        (_cachedList || []).forEach(s => {
            if (checked) st.spareListSelected[s.id] = true;
            else delete st.spareListSelected[s.id];
        });
        refreshList();
    }

    function updateConsumeHeadCheckAll() {
        const el = document.getElementById('consumeHeadChkAll');
        if (!el) return;
        const list = _consumeCachedList || [];
        if (!list.length) {
            el.checked = false;
            el.indeterminate = false;
            return;
        }
        let n = 0;
        list.forEach(s => { if (consumeRowChecked(s)) n++; });
        el.checked = n === list.length;
        el.indeterminate = n > 0 && n < list.length;
    }

    function reqWorkToggleAll(checked) {
        if (reqWorkVesselOrderedOrReceivedView()) return;
        if (reqWorkFormLocked()) return;
        const req = getReqWorkSession();
        if (!req) return;
        captureReqWorkMeta();
        const list = _reqWorkCachedList || [];
        req.lines = req.lines || [];
        if (checked) {
            list.forEach(s => {
                if (!req.lines.some(l => reqWorkSameSpareId(l.spare_part_id, s.id))) {
                    req.lines.push(buildReqLine(s, 0));
                }
            });
        } else {
            const visibleIds = new Set(list.map(s => reqWorkSpareIdKey(s.id)));
            req.lines = req.lines.filter(l => !visibleIds.has(reqWorkSpareIdKey(l.spare_part_id)));
        }
        syncRequisitionDraftFromLines();
        syncReqLineMap();
        const st = getState();
        if (modState(st).reqWorkShowSelectedOnly && !reqWorkCheckedSpareCount(st)) {
            modState(st).reqWorkShowSelectedOnly = false;
            refreshReqWorkListUi();
        } else {
            refreshReqWorkListUiSoft();
        }
    }

    function consumeToggleAll(checked) {
        if (!consumeListEditable()) return;
        const draft = getConsumeSession();
        if (!draft) return;
        captureConsumeMeta();
        const list = _consumeCachedList || [];
        draft.lines = draft.lines || [];
        if (checked) {
            list.forEach(s => {
                if (!draft.lines.some(l => consumeSameSpareId(l.spare_part_id, s.id))) {
                    draft.lines.push(buildConsumeLine(s, 0));
                }
            });
        } else {
            const visibleIds = new Set(list.map(s => consumeSpareIdKey(s.id)));
            draft.lines = draft.lines.filter(l => !visibleIds.has(consumeSpareIdKey(l.spare_part_id)));
        }
        syncConsumeLineMap();
        const st = getState();
        if (modState(st).consumeShowSelectedOnly && !consumeCheckedSpareCount(st)) {
            modState(st).consumeShowSelectedOnly = false;
        }
        refreshConsumeListUi();
    }

    function spareBaselineQty(s) {
        const c = canon(s);
        const std = Number(TVC_Inventory.standardStock(c)) || 0;
        if (std > 0) return std;
        const min = Number(TVC_Inventory.minStock(c)) || 0;
        if (min > 0) return min;
        return null;
    }

    function formatNeedHtml(need) {
        if (need == null) return '<span class="qty-na muted" title="Standard or Min not set">—</span>';
        return esc(String(need));
    }

    function sparePipelineCols(s, line = null) {
        const stock = TVC_Inventory.currentStock(s);
        const awaiting = reportedWaitQty(s);
        const baseline = spareBaselineQty(s);
        const need = baseline != null ? Math.max(0, baseline - stock - awaiting) : null;
        const request = line ? (Number(line.qty_requested) || 0) : 0;
        const assess = line?.qty_approved != null ? String(line.qty_approved) : '—';
        const rcvd = line ? String(Number(line.qty_received) || 0) : '—';
        return { stock, awaiting, need, request, assess, rcvd };
    }

    /** Req / Eval / Rcvd 수량 불일치 — 셀 강조용 */
    function reqLineQtyMismatchFlags(line) {
        if (!line) return { reqEval: false, evalRcvd: false, reqRcvd: false };
        const req = Number(line.qty_requested) || 0;
        const evalSet = line.qty_approved != null && line.qty_approved !== '';
        const evalQty = evalSet ? (Number(line.qty_approved) || 0) : null;
        const rcvdSet = line.qty_received != null && line.qty_received !== '';
        const rcvd = rcvdSet ? (Number(line.qty_received) || 0) : null;
        return {
            reqEval: evalQty != null && req !== evalQty,
            evalRcvd: evalQty != null && rcvd != null && rcvd !== evalQty,
            reqRcvd: rcvd != null && req !== rcvd,
        };
    }

    function reqQtyMismatchClass(col, line) {
        const flags = reqLineQtyMismatchFlags(line);
        if (col === 'req' && flags.reqEval) return ' qty-mismatch';
        if (col === 'assess' && (flags.reqEval || flags.evalRcvd)) return ' qty-mismatch';
        if (col === 'rcvd' && (flags.evalRcvd || flags.reqRcvd)) return ' qty-mismatch';
        return '';
    }

    /** @deprecated alias */
    function spareOrderCols(s) {
        return sparePipelineCols(s, reqLineForSpareRow(s));
    }

    function spareInventoryUser(st) {
        const session = typeof TVC_Auth !== 'undefined' ? TVC_Auth.getCurrentUser() : null;
        let user = session || st?.user;
        if (!user) return null;
        const role = user.role || TVC_RBAC?.resolveUserRole?.(user);
        const resolved = role && role !== user.role ? { ...user, role } : user;
        if (st) st.user = resolved;
        return resolved;
    }

    function canModifySpare(st) {
        if (typeof TVC_App?.canEditSpareItems === 'function') {
            return TVC_App.canEditSpareItems();
        }
        return window.TVC_RBAC && TVC_RBAC.canModifySpareInventory(spareInventoryUser(st));
    }

    function canCreateRequisition(st) {
        const user = spareInventoryUser(st);
        return !!(typeof TVC_RBAC !== 'undefined' && user && TVC_RBAC.can(user, TVC_RBAC.Action.CREATE_REQUISITION));
    }

    function canCreateConsume(st) {
        const user = spareInventoryUser(st);
        return !!(typeof TVC_RBAC !== 'undefined' && user && TVC_RBAC.can(user, TVC_RBAC.Action.DEDUCT_INVENTORY));
    }

    function canCreateDeliver(st) {
        const user = spareInventoryUser(st);
        return !!(typeof TVC_RBAC !== 'undefined' && user && TVC_RBAC.can(user, TVC_RBAC.Action.SUPPLY_PARTS));
    }

    /** New Requisition Complete — Chief Engineer or HQ Superintendent */
    function canCompleteRequisition(st) {
        const user = spareInventoryUser(st);
        if (!user || !window.TVC_RBAC) return false;
        const role = TVC_RBAC.resolveUserRole(user);
        return role === TVC_RBAC.Role.SHIP_CHIEF || role === TVC_RBAC.Role.HQ_SUPERVISOR;
    }

    function getFocusedSpareId(st) {
        const m = modState(st);
        if (m.wrSpareOpen) return m.wrSpareFocusedId || null;
        if (m.receiveOpen) return m.receiveFocusedId || null;
        if (m.consumeOpen) return m.consumeFocusedId || null;
        if (m.reqWorkOpen) return m.reqWorkFocusedId || null;
        return st?.focusedSpareId || m.focusedId || null;
    }

    function setFocusedSpareId(st, id) {
        const m = modState(st);
        if (m.wrSpareOpen) {
            m.wrSpareFocusedId = id || null;
            return;
        }
        if (m.receiveOpen) {
            m.receiveFocusedId = id || null;
            return;
        }
        if (m.consumeOpen) {
            m.consumeFocusedId = id || null;
            return;
        }
        if (m.reqWorkOpen) {
            m.reqWorkFocusedId = id || null;
            return;
        }
        st.focusedSpareId = id || null;
        m.focusedId = id || null;
    }

    function afterSpareListChange(st, opts = {}) {
        const m = modState(st);
        if (m.consumeOpen) {
            refreshConsumeListUi();
            syncSpareToolbarUi();
        } else if (m.receiveOpen) {
            refreshReceiveListUi();
            syncSpareToolbarUi();
        } else if (m.wrSpareOpen) {
            refreshWrSpareListUi();
        } else if (m.reqWorkOpen) {
            refreshReqWorkListUi();
            syncSpareToolbarUi();
        } else if (st.currentTab === 'actual') {
            if (window.TVC_App?.renderPlanGroupHeader) TVC_App.renderPlanGroupHeader();
            if (window.TVC_App?.refreshActualPlan) TVC_App.refreshActualPlan();
        } else if (st.currentTab === 'spare' && document.getElementById('spareListScroll')) {
            refreshSpareInventoryUi(opts);
        } else {
            render();
        }
    }

    /** SPARE inventory — full render 없이 목록·트리·편집 블록만 갱신 (스크롤 유지) */
    function refreshSpareInventoryUi(opts = {}) {
        const st = getState();
        const preserve = opts.preserveScroll !== false;
        const scrollTop = preserve
            ? (opts.scrollTop != null ? opts.scrollTop : captureSpareListScroll())
            : 0;
        const scroll = document.getElementById('spareListScroll');
        ensureSpareGroupNodes(st);
        if (isSpareInventoryFilterContext(st)) {
            _cachedList = filteredSpares(st);
        }
        const list = _cachedList.length ? _cachedList : filteredSpares(st);
        const allCanon = (st.spares || []).map(canon);
        const countEl = document.getElementById('spareCount');
        if (countEl) countEl.textContent = `${list.length} / ${allCanon.length}`;
        renderSpareGroupTree();
        refreshSpareEditBlock();
        const hadVl = !!(vl && scroll?.querySelector('.vl-inner'));
        if (hadVl && list.length) {
            vl.refresh();
        } else if (scroll) {
            mountVirtualList(preserve ? scrollTop : null);
        }
        if (preserve) restoreSpareListScroll(scrollTop);
        else requestAnimationFrame(syncSpareHeadLayout);
        syncSpareToolbarUi();
        syncSpareInventoryActionBar();
        updateSpareHeadCheckAll();
        renderSpareFilterDashboard();
        if (window.TVC_App?.syncSpareItemToolbar) TVC_App.syncSpareItemToolbar();
    }

    function isSpareChecked(st, id) {
        return !!(st.spareListSelected && st.spareListSelected[id]);
    }

    function getCheckedSpareIds(st) {
        return Object.keys(st.spareListSelected || {}).filter(id => st.spareListSelected[id]);
    }

    /** @deprecated detail/legacy — 포커스 행 */
    function getSelectedSpareId(st) {
        return getFocusedSpareId(st);
    }

    function setSelectedSpareId(st, id) {
        setFocusedSpareId(st, id);
    }

    function spareGroupLabel(s) {
        return String(s.group || '').trim() || '—';
    }

    function escAttr(s) { return esc(s).replace(/'/g, '&#39;'); }

    /** 잘릴 수 있는 테이블 셀 — 마우스 오버 시 전체 텍스트 툴팁 */
    function cellTitleAttr(val) {
        const t = String(val ?? '').trim();
        if (!t || t === '—') return '';
        return ` title="${escAttr(t)}"`;
    }

    /** Original/Actual Plan과 동일한 GROUP Tree — SPARE 탭 전용 렌더 */
    function renderSpareGroupTree() {
        const st = getState();
        const root = document.getElementById('spareGroupTree');
        if (!root) return;
        if (spareInventoryGroupKey(st) === CRITICAL_GROUP_KEY) st.spareSelectedGroupKey = null;
        if (!st.idx && (st.jobs || []).length && window.TVC_Indexes) {
            st.idx = TVC_Indexes.build(st);
        }
        ensureSpareGroupNodes(st);
        if (!st.idx) {
            root.innerHTML = '<div class="tree-empty muted">Loading Maintenance Plan…<br>Please open the Original Plan tab once.</div>';
            return;
        }
        const q = (st.treeSearch || '').toLowerCase();
        const matchNode = (n) => !q || (n.label || '').toLowerCase().includes(q) || (n.department || '').toLowerCase().includes(q);
        const byDept = new Map();
        (spareGroupTreeNodes(st))
            .filter(n => {
                if (isHiddenSpareGroup(n.label, n.department)) return false;
                if (!spareGroupTreeIncludesDept(st, n)) return false;
                if (matchNode(n)) return true;
                return isGeneratorEngineGroupLabel(n.label) && matchMergedGeneratorSearch(q);
            })
            .forEach(n => {
                const dept = spareTreeDisplayDept(n);
                if (!byDept.has(dept)) byDept.set(dept, []);
                byDept.get(dept).push(n);
            });
        const allSelected = !spareInventoryGroupKey(st);
        let html = `<div class="tree-node${allSelected ? ' selected' : ''}" onclick="TVC_SpareMenu.selectSpareGroup(null)"><span>📋 All Groups</span></div>`;
        if (!byDept.size && q) {
            html += `<div class="tree-empty muted">No groups match "${esc(q)}"</div>`;
        }
        DEPT_TREE_ORDER.filter(d => byDept.has(d)).forEach(dept => {
            const nodes = byDept.get(dept);
            const collapsed = spareTreeDeptCollapsed(dept, st);
            const chevron = collapsed ? '▸' : '▾';
            html += `<div class="tree-dept tree-dept-toggle" role="button" tabindex="0" onclick="TVC_SpareMenu.toggleSpareTreeDept('${escAttr(dept)}', event)"><span class="tree-dept-chevron" aria-hidden="true">${chevron}</span><span>${esc(dept)}</span></div>`;
            if (!collapsed) {
                mergeSpareTreeNodes(nodes).forEach(n => {
                    const nSpares = Number(n.spareCount) || 0;
                    const countTag = `<span class="tree-empty-tag" title="${nSpares ? nSpares + ' spare(s)' : 'No spare parts'}">${nSpares}</span>`;
                    const sel = spareInventoryGroupKey(st) === n.key ? ' selected' : '';
                    html += `<div class="tree-node${sel}${nSpares ? '' : ' tree-node-empty'}" onclick="TVC_SpareMenu.selectSpareGroup('${escAttr(n.key)}')"><span>${esc(safeTreeLabel(n.label))}</span>${countTag}</div>`;
                });
            }
        });
        root.innerHTML = html;
        const searchEl = document.getElementById('spareTreeSearch');
        if (searchEl && document.activeElement !== searchEl) searchEl.value = st.treeSearch || '';
    }

    /** Original/Actual Plan GROUP 목록 — GROUP Tree와 동일 소스 */
    function buildGroupSelectHtml(st, selected) {
        if (!st.idx && (st.jobs || []).length && window.TVC_Indexes) {
            st.idx = TVC_Indexes.build(st);
        }
        ensureSpareGroupNodes(st);
        const deptRank = { DECK: 0, ENGINE: 1 };
        const nodes = (st.idx?.groupNodes || [])
            .filter(n => !st.department || n.department === st.department)
            .sort((a, b) => (deptRank[a.department] ?? 9) - (deptRank[b.department] ?? 9) || a.label.localeCompare(b.label));
        let html = '<option value="">— Unassigned —</option>';
        let curDept = '';
        nodes.forEach(n => {
            if (n.department !== curDept) {
                if (curDept) html += '</optgroup>';
                html += `<optgroup label="${esc(n.department)}">`;
                curDept = n.department;
            }
            const sel = String(selected || '').trim() === n.label ? ' selected' : '';
            html += `<option value="${esc(n.label).replace(/"/g, '&quot;')}"${sel}>${esc(n.label)}</option>`;
        });
        if (curDept) html += '</optgroup>';
        return html;
    }

    function spareMatchesGroup(s, node) {
        if (!node) return false;
        const spareDept = String(s.category || s.department || '').trim().toUpperCase();
        const nodeDept = String(node.department || '').trim().toUpperCase();
        if (spareDept && nodeDept && spareDept !== nodeDept) return false;
        const spareGroup = String(s.group || '').trim().toLowerCase();
        const nodeLabel = String(node.label || '').trim().toLowerCase();
        if (spareGroup && nodeLabel && spareGroup === nodeLabel) return true;
        const nodeNo = pmsGroupSortNo(node.label);
        const codeNo = spareCodeGroupNo(s);
        if (nodeNo != null && codeNo != null && nodeNo === codeNo) return true;
        return false;
    }

    async function vesselScope() {
        const st = getState();
        const isHq = window.TVC_RBAC && TVC_RBAC.isHqAccount(st.user);
        const vesselId = isHq ? st.selectedVesselId : (await TVC_DB.getMeta(TVC_META_KEYS.VESSEL_ID));
        return { st, isHq, vesselId };
    }

    function matchSpare(s, st, f) {
        const q = (f.partNo || f.description || '').toLowerCase().trim();
        if (q) {
            const hay = [
                spareNumbering(s),
                s.name,
                spareDwgNo(s, st),
                spareDrawingNo(s),
                spareUnit(s),
                spareWorking(s),
                s.universalItemCode || s.universalCode || s.universal_code || '',
                spareClass(s),
            ].join(' ').toLowerCase();
            if (!hay.includes(q)) return false;
        }
        const groupKey = spareFilterGroupKey(st);
        const deptScope = spareListDeptScope(st, groupKey);
        if (deptScope) {
            const cat = (s.category || 'GENERAL').toUpperCase();
            if (cat !== deptScope) return false;
        }
        const filterKey = spareFilterKeyNormalized(st, groupKey) || groupKey;
        if (filterKey === MERGED_GEN_ENGINE_KEY) {
            if (!spareInMergedGeneratorEngine(s)) return false;
        } else if (filterKey) {
            const node = findSpareGroupNode(st, filterKey);
            if (node && !spareMatchesGroup(s, node)) return false;
        }
        const sf = f.spareFilter || (f.showLowOnly ? 'lowStock' : 'total');
        if (sf === 'lowStock' && !TVC_Inventory.isLowStock(s)) return false;
        if (sf === 'legal' && spareClass(s) !== 'L') return false;
        if (sf === 'legalLowStock' && !(TVC_Inventory.isLowStock(s) && spareClass(s) === 'L')) return false;
        return true;
    }

    function isSpareInventoryFilterContext(st) {
        const m = modState(st);
        return !m.reqWorkOpen && !m.consumeOpen && !m.receiveOpen && !m.wrSpareOpen;
    }

    function filteredSpares(st) {
        const f = modState(st);
        let list = (st.spares || []).map(canon).filter(s => matchSpare(s, st, f));
        if (f.spareShowSelectedOnly && isSpareInventoryFilterContext(st)) {
            const checked = new Set(getCheckedSpareIds(st).map(String));
            list = list.filter(s => checked.has(String(s.id)));
        }
        return list.sort(compareSpareByCode);
    }

    /** 검색/재고 필터와 무관하게, 지정 그룹(병합/크리티컬 포함)에 속한 모든 부품 */
    function sparesInGroupKey(st, key) {
        const deptScope = spareListDeptScope(st, key);
        const all = (st.spares || []).map(canon).filter(s => {
            if (deptScope) {
                const cat = (s.category || 'GENERAL').toUpperCase();
                if (cat !== deptScope) return false;
            }
            return true;
        });
        if (!key) return all;
        if (key === MERGED_GEN_ENGINE_KEY) return all.filter(s => spareInMergedGeneratorEngine(s));
        const mapped = spareFilterKeyNormalized(st, key);
        if (mapped === MERGED_GEN_ENGINE_KEY) return all.filter(s => spareInMergedGeneratorEngine(s));
        const node = findSpareGroupNode(st, mapped || key);
        if (!node) return [];
        return all.filter(s => spareMatchesGroup(s, node));
    }

    /** SPARE 탭 inventory — 현재 선택 그룹의 모든 부품 */
    function sparesInSelectedGroup(st) {
        return sparesInGroupKey(st, spareInventoryGroupKey(st));
    }

    function spareListSearchQuery(st) {
        const f = modState(st);
        return (f.partNo || f.description || st.spareSearch || '').trim();
    }

    function filteredReqWorkSpares(st) {
        const m = modState(st);
        if (isRequisitionListWindow(m)) {
            if (m.reqWorkListEditing && !m.reqWorkShowSelectedOnly) {
                return filteredSpares(st);
            }
            const req = getReqWorkSession();
            let lineSpares = reqWorkLineSpares(st, req);
            const q = spareListSearchQuery(st);
            if (q) {
                const f = modState(st);
                lineSpares = lineSpares.filter(s => matchSpare(s, st, f));
            }
            return lineSpares.sort(compareSpareByCode);
        }
        const list = filteredSpares(st);
        if (!m.reqWorkShowSelectedOnly) return list;
        return list.filter(s => reqWorkRowChecked(s));
    }

    function filteredConsumeSpares(st) {
        const m = modState(st);
        const list = filteredSpares(st);
        if (!m.consumeShowSelectedOnly) return list;
        return list.filter(s => consumeRowChecked(s));
    }

    function filteredReceiveSpares(st) {
        const m = modState(st);
        const list = filteredSpares(st);
        if (!m.receiveShowSelectedOnly) return list;
        return list.filter(s => receiveRowChecked(s));
    }

    function filteredWrSpares(st) {
        const m = modState(st);
        if (!m.wrSpareShowSelectedOnly) return filteredSpares(st);
        if (spareListSearchQuery(st)) return filteredSpares(st);
        const f = modState(st);
        const stNoGroup = withSpareGroupFilter(st, null);
        return (st.spares || []).map(canon).filter(s => {
            if (!wrSpareRowChecked(s)) return false;
            return matchSpare(s, stNoGroup, f);
        });
    }

    function groupFilterLabel(st) {
        const key = spareFilterGroupKey(st);
        if (!key) return '';
        const mapped = spareFilterKeyNormalized(st, key);
        if (mapped === MERGED_GEN_ENGINE_KEY) return MERGED_GEN_ENGINE_LABEL;
        return groupKeyLabel(st, mapped || key);
    }

    function updatePanelLayout(open) {
        document.querySelector('.spare-layout')?.classList.toggle('panel-open', open);
        document.getElementById('spareDetailPanel')?.classList.toggle('open', open);
    }

    async function maintenanceHistory(spareId, st) {
        const s = (st.spares || []).map(canon).find(x => x.id === spareId);
        const items = [];
        (s?.history || []).forEach(h => {
            if (/TASK|MAINT|DEDUCT|CONFIRM/.test(h.type || '')) {
                items.push({ at: h.at, jobCode: h.ref || '—', qty: h.qty, type: h.type, note: h.note || '' });
            }
        });
        try {
            const bomLinks = await TVC_DB.indexGetAll('job_bom', 'by_spare', spareId);
            bomLinks.forEach(l => items.push({ at: l.created_at, jobCode: l.job_code, qty: l.qty_per_job, type: 'BOM', note: 'Linked in BOM' }));
        } catch (_) { /* noop */ }
        (st.reports || []).filter(r => TVC_RBAC.isConfirmedStatus(r.status) || TVC_RBAC.isApprovedStatus(r.status)).forEach(r => {
            (r.used_parts || []).filter(u => u.spare_part_id === spareId).forEach(u => {
                items.push({ at: r.confirmed_at || r.approved_at || r.created_at, jobCode: r.job_code, qty: -(u.qty_used || 0), type: 'WORK_REPORT', note: r.reporter_name || '' });
            });
        });
        return items.sort((a, b) => (b.at || '').localeCompare(a.at || ''));
    }

    function spareScopeSpares(st) {
        const f = { partNo: '', description: '', spareFilter: 'total', showLowOnly: false };
        return (st.spares || []).map(canon).filter(s => matchSpare(s, st, f));
    }

    function spareDashboardCounts(st) {
        const scope = spareScopeSpares(st);
        let lowStock = 0;
        let legalLowStock = 0;
        let legal = 0;
        scope.forEach(s => {
            const low = TVC_Inventory.isLowStock(s);
            const isLegal = spareClass(s) === 'L';
            if (low) lowStock++;
            if (low && isLegal) legalLowStock++;
            if (isLegal) legal++;
        });
        return { total: scope.length, lowStock, legalLowStock, legal };
    }

    function spareDashBtn(b, activeKey) {
        return `<button type="button" class="act-dash-btn ${b.cls}${activeKey === b.key ? ' active' : ''}" data-sfilter="${b.key}"
                onclick="TVC_SpareMenu.setSpareFilter('${b.key}')">
                <span class="act-dash-count">${b.count}</span>
                <span class="act-dash-label">${esc(b.label)}</span>
            </button>`;
    }

    function renderSpareFilterDashboard() {
        const host = document.getElementById('spareFilterDashboard');
        if (!host) return;
        const st = getState();
        const m = modState(st);
        if (m.spareFilter === 'major') m.spareFilter = 'total';
        const c = spareDashboardCounts(st);
        const f = m.spareFilter || 'total';
        const left = [
            { key: 'lowStock', label: 'Low Stock', count: c.lowStock, cls: 'act-dash-due30' },
            { key: 'legalLowStock', label: 'Legal Low Stock', count: c.legalLowStock, cls: 'act-dash-critical' },
        ];
        const right = [
            { key: 'legal', label: 'Legal Spare', count: c.legal, cls: 'act-dash-pending' },
            { key: 'total', label: 'Total', count: c.total, cls: 'act-dash-total' },
        ];
        host.innerHTML = `
            <div class="act-filter-dashboard-inner">
                ${left.map(b => spareDashBtn(b, f)).join('')}
                <span class="act-dash-sep" aria-hidden="true"></span>
                ${right.map(b => spareDashBtn(b, f)).join('')}
            </div>`;
        bindSpareDashLayoutSync(host);
        requestAnimationFrame(() => {
            syncSpareHeadLayout();
            requestAnimationFrame(syncSpareHeadLayout);
        });
    }

    function bindSpareDashLayoutSync(host) {
        if (!host || typeof ResizeObserver === 'undefined') return;
        if (_spareDashResizeObs) _spareDashResizeObs.disconnect();
        _spareDashResizeObs = new ResizeObserver(() => syncSpareHeadLayout());
        _spareDashResizeObs.observe(host);
    }

    function setSpareFilter(filter) {
        const st = getState();
        const m = modState(st);
        m.spareFilter = filter || 'total';
        m.showLowOnly = m.spareFilter === 'lowStock' || m.spareFilter === 'legalLowStock';
        renderSpareFilterDashboard();
        applySpareListFilter();
    }

    function spareActiveFilterLabel(m) {
        const f = m.spareFilter || (m.showLowOnly ? 'lowStock' : 'total');
        if (f === 'lowStock') return 'Low stock';
        if (f === 'legalLowStock') return 'Legal Low Stock';
        if (f === 'legal') return 'Legal Spare';
        return '';
    }

    async function render() {
        const root = document.getElementById('spareMenuBody');
        if (!root) return;
        if (await ensureInventoryLoaded()) return render();
        const { st, vesselId } = await vesselScope();
        await syncReqLineMap();
        await syncReportedWaitMap(vesselId);
        spareInventoryUser(st);
        const m = modState(st);
        const allCanon = (st.spares || []).map(canon);
        _cachedList = filteredSpares(st);
        const canRequisition = window.TVC_RBAC && st.user && TVC_RBAC.can(st.user, TVC_RBAC.Action.CREATE_REQUISITION);
        const canModify = canModifySpare(st);
        const needsImport = allCanon.length < 500;
        const fileMode = TVC_Env.isFileProtocol();
        const panelOpen = m.panelOpen && getFocusedSpareId(st);
        const tb = spareToolbarFlags(st);
        const prevTreeScroll = document.getElementById('spareGroupTree')?.scrollTop || 0;
        const prevListScroll = document.getElementById('spareListScroll')?.scrollTop || 0;

        const importBanners = `
          ${fileMode && needsImport ? `<div class="spare-import-banner file-mode">
            <strong>⚠ file:// mode</strong> — Auto Import unavailable. Click the <b>Select spare-inventory.xls</b> button below.
            (Recommended: <code>npm run serve</code> → <code>http://localhost:3000</code>)
          </div>` : ''}
          ${needsImport ? `<div class="spare-import-banner">
            <strong>⚠ ENGINE inventory not loaded</strong> — Currently ${allCanon.length} item(s) (demo data).
            ${canModify
                ? (fileMode
                    ? `<label class="btn btn-sm btn-green spare-file-pick" for="srInventoryImportFile">📂 Select spare-inventory.xls</label>`
                    : `<button type="button" class="btn btn-sm btn-green" onclick="TVC_SpareMenu.loadBundledXls()">📥 Import XLS (ENGINE) — Recommended</button>
                       <button type="button" class="btn btn-sm" onclick="TVC_SpareMenu.triggerInventoryImport()">📂 Select file</button>`)
                : 'Import using Chief Engineer / Captain account.'}
            ${st._spareImportMsg ? `<span class="muted">${esc(st._spareImportMsg)}</span>` : ''}
          </div>` : (st._spareImportMsg ? `<div class="spare-import-banner ok">${esc(st._spareImportMsg)}</div>` : '')}`;

        root.innerHTML = `
        <div class="sheet-head">
            <h2>🔩 SPARE</h2>
        </div>
        <div id="spareActionBar" class="plan-action-bar">
            <div class="plan-action-btns">${spareInventoryActionBarHtml(st)}</div>
        </div>
        ${importBanners}
        <div class="plan-layout actual-layout spare-layout${panelOpen ? ' panel-open' : ''}">
            <aside class="panel tree-panel">
              <div class="panel-head spare-tree-head">
                <span>🌳 SPARE GROUP Tree</span>
                ${renderSpareTreeActionBtns(st)}
              </div>
              <div class="tree-search-bar">
                <div class="search-field-wrap">
                  <input class="search-input" id="spareTreeSearch" placeholder="Search GROUP…" oninput="TVC_App.setTreeSearch(this.value)">
                  <button type="button" class="search-clear-btn hidden" title="Clear search" aria-label="Clear search" onclick="TVC_App.clearSearchField('spareTreeSearch')">×</button>
                </div>
              </div>
              <div class="panel-body tree-scroll" id="spareGroupTree"></div>
            </aside>
            <main class="panel spare-main">
              <div class="filter-bar orig-toolbar spare-item-toolbar">
                <button type="button" id="spareModifyBtn" class="btn btn-sm" onclick="TVC_App.openSpareModify()"${tb.modifyEnabled ? '' : ' disabled'} title="${esc(tb.modifyTitle)}">✏️ Modify</button>
                <button type="button" id="spareAppendBtn" class="btn btn-sm" onclick="TVC_App.openSpareAppend()"${tb.appendEnabled ? '' : ' disabled'} title="${esc(tb.appendTitle)}">➕ Append</button>
                <button type="button" id="spareDeleteBtn" class="btn btn-sm btn-red" onclick="TVC_App.deleteSpareItem()"${tb.deleteEnabled ? '' : ' disabled'} title="${esc(tb.deleteTitle)}">🗑 Delete</button>
                <button type="button" id="actSpareMasterExportBtn" class="btn btn-sm btn-excel hidden" onclick="TVC_App.exportSpareMasterExcel()" title="Export SPARE Master Excel — edit in Excel, then Master Import">📤 Master Export</button>
                <button type="button" id="actSpareMasterImportBtn" class="btn btn-sm hidden" onclick="TVC_App.triggerSpareMasterImport()" title="Import SPARE Master Excel after editing export file">📥 Master Import</button>
                <div class="tab-toolbar-end">
                    <button type="button" class="btn btn-sm" onclick="TVC_App.printTabList('spare', false)">🖨 Print</button>
                    <button type="button" class="btn btn-sm" onclick="TVC_App.printTabList('spare', true)">👁 Preview</button>
                </div>
              </div>
              <div id="spareFilterDashboard" class="act-filter-dashboard"></div>
              <div class="filter-bar spare-list-search-bar">
                <div class="search-field-wrap">
                  <input type="text" class="search-input spare-list-search-input" id="spareSearch" placeholder="Search Code / Item / Part No / Work"
                      value="${esc(m.partNo || m.description ? [m.partNo, m.description].filter(Boolean).join(' ') : (st.spareSearch || ''))}"
                      oninput="TVC_SpareMenu.setSearch(this.value)">
                  <button type="button" class="search-clear-btn hidden" title="Clear search" aria-label="Clear search" onclick="TVC_SpareMenu.clearSpareSearch()">×</button>
                </div>
                <span class="count-label" id="spareCount">${_cachedList.length} / ${allCanon.length}</span>
              </div>
              <div id="spareEditBlock">${renderSpareEditBlockHtml(st)}</div>
              <div id="spareEditorWrap"></div>
              <div class="panel spare-list-panel">
                <div id="spareListHead" class="vl-head-wrap sheet-scroll-original"></div>
                <div id="spareListScroll" class="virtual-scroll sheet-scroll-original spare-vl-scroll"></div>
              </div>
              <div id="spareReqSection" class="spare-req-section${m.showReqPanel ? '' : ' hidden'}"></div>
            </main>
            <aside id="spareDetailPanel" class="spare-detail-panel${panelOpen ? ' open' : ''}">
              <div id="spareDetailInner" class="spare-detail-inner"></div>
            </aside>
        </div>
        <input type="file" id="srImportFile" accept=".xlsx" class="hidden">
        <input type="file" id="srCsvUploadFile" accept=".csv" class="hidden">
        <input type="file" id="srInventoryImportFile" accept=".csv,.xls,.xlsx" class="hidden">
        <input type="file" id="spareHqImportFile" accept=".json" class="hidden">
        <input type="file" id="spareMasterImportFile" accept=".xlsx" class="hidden" onchange="TVC_App.importSpareMasterExcel(this.files[0]); this.value='';">`;

        renderSpareGroupTree();
        const treeScrollEl = document.getElementById('spareGroupTree');
        if (treeScrollEl && prevTreeScroll) treeScrollEl.scrollTop = prevTreeScroll;
        mountVirtualList();
        const listScrollEl = document.getElementById('spareListScroll');
        if (listScrollEl && prevListScroll) {
            listScrollEl.scrollTop = prevListScroll;
            if (vl) vl.refresh();
            requestAnimationFrame(() => {
                listScrollEl.scrollTop = prevListScroll;
                syncSpareHeadLayout();
            });
        }
        bindSpareListEvents();
        bindFileInputs();
        renderSpareFilterDashboard();
        syncSpareInventoryActionBar();

        if (st._spareEdit && !st._spareEdit.id) renderEditor(st._spareEdit);
        if (panelOpen) await renderDetailPanel(getFocusedSpareId(st), canRequisition, canModify);
        if (window.TVC_App?.syncSpareItemToolbar) TVC_App.syncSpareItemToolbar();
        else syncSpareToolbarUi();
        TVC_App.refreshSearchClearUi?.(root);
    }

    function refreshSpareTabAfterModalClose() {
        const st = getState();
        if (st.currentTab !== 'spare') return;
        if (document.getElementById('spareListScroll')) refreshList();
        else render();
    }

    function refreshList() {
        syncReportedWaitMap().finally(() => {
            const scrollTop = captureSpareListScroll();
            const st = getState();
            const m = modState(st);
            if (m.spareShowSelectedOnly && !getCheckedSpareIds(st).length) {
                m.spareShowSelectedOnly = false;
            }
            if (document.getElementById('spareListScroll') && isSpareInventoryFilterContext(st)) {
                _cachedList = filteredSpares(st);
            }
            if (vl) vl.refresh();
            refreshSpareEditBlock();
            syncSpareToolbarUi();
            syncSpareInventoryActionBar();
            updateSpareHeadCheckAll();
            if (modState(getState()).reqWorkOpen) refreshReqWorkListRows();
            restoreSpareListScroll(scrollTop);
        });
    }

    function spareActionIds(kind) {
        const st = getState();
        const checked = getCheckedSpareIds(st);
        const focused = getFocusedSpareId(st);
        if (kind === 'modify') {
            if (checked.length === 1) return checked;
            if (!checked.length && focused) return [focused];
            return [];
        }
        if (checked.length) return checked;
        return focused ? [focused] : [];
    }

    function spareToolbarFlags(st) {
        spareInventoryUser(st);
        const editing = isInlineEditing(st);
        const canModify = canModifySpare(st);
        const modifyIds = spareActionIds('modify');
        const deleteIds = spareActionIds('delete');
        const checkedCount = getCheckedSpareIds(st).length;
        const permTip = 'Chief Engineer, Chief Officer, Captain, or HQ Superintendent permission required';
        const pickTip = 'Click a row or select using the checkbox';
        const editingTip = 'Not available while editing';
        return {
            editing,
            canModify,
            modifyIds,
            deleteIds,
            modifyEnabled: canModify && !editing && modifyIds.length === 1,
            deleteEnabled: canModify && !editing && deleteIds.length >= 1,
            appendEnabled: canModify && !editing,
            modifyTitle: !canModify ? permTip : (editing ? editingTip : (checkedCount > 1 ? 'Modify supports only one selected item' : (modifyIds.length ? '' : pickTip))),
            deleteTitle: !canModify ? permTip : (editing ? editingTip : (deleteIds.length ? '' : pickTip)),
            appendTitle: !canModify ? permTip : (editing ? 'Cannot Append while editing' : 'Register new part'),
        };
    }

    function applySpareToolbarFlags(tb) {
        const setBtn = (id, on, title) => {
            const el = document.getElementById(id);
            if (!el) return;
            el.disabled = !on;
            if (on) {
                el.removeAttribute('disabled');
                el.removeAttribute('aria-disabled');
            } else {
                el.setAttribute('disabled', 'disabled');
                el.setAttribute('aria-disabled', 'true');
            }
            el.title = title || '';
        };
        if (tb.editing) {
            setBtn('spareModifyBtn', false, tb.modifyTitle);
            setBtn('spareAppendBtn', false, tb.appendTitle);
            setBtn('spareDeleteBtn', false, tb.deleteTitle);
            setBtn('reqWorkModifyBtn', false, tb.modifyTitle);
            setBtn('reqWorkAppendBtn', false, tb.appendTitle);
            setBtn('reqWorkDeleteBtn', false, tb.deleteTitle);
            return;
        }
        setBtn('spareAppendBtn', tb.appendEnabled, tb.appendTitle);
        setBtn('spareModifyBtn', tb.modifyEnabled, tb.modifyTitle);
        setBtn('spareDeleteBtn', tb.deleteEnabled, tb.deleteTitle);
        const canMaster = typeof TVC_App?.canSpareMasterExcel === 'function' && TVC_App.canSpareMasterExcel();
        ['actSpareMasterExportBtn', 'actSpareMasterImportBtn'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.classList.toggle('hidden', !canMaster);
        });
        const spareEx = document.getElementById('actSpareMasterExportBtn');
        const spareIm = document.getElementById('actSpareMasterImportBtn');
        if (spareEx) {
            spareEx.disabled = !canMaster;
            spareEx.title = canMaster
                ? 'Export Master Excel (Group · Equipment · Spare Parts) — edit file, then Master Import'
                : (typeof TVC_App?.spareMasterExcelDeniedMessage === 'function' ? TVC_App.spareMasterExcelDeniedMessage() : '');
        }
        if (spareIm) {
            spareIm.disabled = !canMaster;
            spareIm.title = canMaster
                ? 'Import edited Master Excel (codes GG-EE-III, Equipment, ROB/Std)'
                : (typeof TVC_App?.spareMasterExcelDeniedMessage === 'function' ? TVC_App.spareMasterExcelDeniedMessage() : '');
        }
        const m = modState(getState());
        const listLocked = isReqWorkListViewLocked();
        const vesselPostOrder = reqWorkVesselOrderedOrReceivedView();
        const postOrderTip = reqWorkVesselPostOrderLockTip();
        if (isRequisitionListWindow(m)) {
            const hasDisplayedReq = reqWorkListHasDisplayedReq(m);
            setBtn('reqWorkHeadModifyBtn', hasDisplayedReq && !m.reqWorkListEditing && !vesselPostOrder,
                vesselPostOrder ? postOrderTip : (hasDisplayedReq ? 'Enable editing' : 'Select a requisition from the list first'));
            setBtn('reqWorkHeadNewBtn', !m.reqWorkListEditing && !vesselPostOrder && canCreateRequisition(getState()),
                vesselPostOrder ? postOrderTip : (m.reqWorkListEditing ? 'Finish editing first' : ''));
        }
        const lockTip = reqWorkListLockTip();
        if (listLocked || vesselPostOrder) {
            setBtn('reqWorkModifyBtn', false, vesselPostOrder ? postOrderTip : lockTip);
            setBtn('reqWorkAppendBtn', false, vesselPostOrder ? postOrderTip : lockTip);
            setBtn('reqWorkDeleteBtn', false, vesselPostOrder ? postOrderTip : lockTip);
            const selBtn = document.getElementById('reqWorkSelectedBtn');
            if (selBtn) {
                selBtn.disabled = true;
                selBtn.title = vesselPostOrder ? postOrderTip : lockTip;
            }
            document.getElementById('reqWorkSearch')?.setAttribute('disabled', 'disabled');
            document.querySelector('#spareReqWorkBody .spare-list-search-bar input[type="checkbox"]')?.setAttribute('disabled', 'disabled');
            document.getElementById('reqWorkGroupTreeToggle')?.setAttribute('disabled', 'disabled');
        } else {
            setBtn('reqWorkAppendBtn', tb.appendEnabled, tb.appendTitle);
            setBtn('reqWorkModifyBtn', tb.modifyEnabled, tb.modifyTitle);
            setBtn('reqWorkDeleteBtn', tb.deleteEnabled, tb.deleteTitle);
            document.getElementById('reqWorkSearch')?.removeAttribute('disabled');
            document.querySelector('#spareReqWorkBody .spare-list-search-bar input[type="checkbox"]')?.removeAttribute('disabled');
            document.getElementById('reqWorkGroupTreeToggle')?.removeAttribute('disabled');
        }
    }

    function syncSpareToolbarUi() {
        applySpareToolbarFlags(spareToolbarFlags(getState()));
    }

    function bindSpareListEvents() {
        /* 행 선택은 rowHtml inline onclick (Original Plan과 동일) */
    }

    function rowCellInput(id, value, extraClass = '') {
        const cls = ['spare-inline-input', extraClass].filter(Boolean).join(' ');
        return `<input class="${cls}" id="${id}" value="${esc(String(value ?? ''))}" onclick="event.stopPropagation()">`;
    }

    const SPARE_CLASS_OPTIONS = [
        { value: 'L', label: 'L : Legal spare parts' },
        { value: 'G', label: 'G : General spare parts' },
    ];
    function rowCellClassSelect(id, value, extraClass = '') {
        const cur = TVC_SpareSchema.normalizePartClass(value);
        const wrapId = `${id}_wrap`;
        const wrapCls = ['spare-class-pick', extraClass].filter(Boolean).join(' ');
        const items = SPARE_CLASS_OPTIONS.map(o => {
            const sel = o.value === cur ? ' selected' : '';
            return `<button type="button" class="spare-class-pick-item${sel}" data-class-value="${o.value}"
                onclick="TVC_SpareMenu.pickSpareClass('${id}','${o.value}')">${esc(o.label)}</button>`;
        }).join('');
        const display = cur || '—';
        return `<div class="${wrapCls}" id="${wrapId}">
            <input type="hidden" id="${id}" value="${escAttr(cur)}">
            <button type="button" class="spare-class-pick-trigger" onclick="TVC_SpareMenu.toggleSpareClassPick(event,'${wrapId}')">
                <span class="spare-class-pick-val">${esc(display)}</span>
                <span class="spare-class-pick-caret" aria-hidden="true">▾</span>
            </button>
            <div class="spare-class-pick-menu" role="listbox" aria-label="Class">${items}</div>
        </div>`;
    }

    function spareClassPickMenuEl(wrap) {
        return wrap?._spareClassMenu || wrap?.querySelector('.spare-class-pick-menu') || null;
    }

    function spareClassPickClickInside(wrap, target) {
        if (!wrap || !target) return false;
        const menu = spareClassPickMenuEl(wrap);
        return wrap.contains(target) || (menu && menu.contains(target));
    }

    function resetSpareClassPickMenu(wrap) {
        if (!wrap) return;
        const menu = spareClassPickMenuEl(wrap);
        if (!menu) return;
        menu.classList.remove('spare-class-pick-menu-portal');
        menu.style.display = '';
        menu.style.position = '';
        menu.style.left = '';
        menu.style.top = '';
        menu.style.minWidth = '';
        menu.style.zIndex = '';
        if (wrap._spareClassMenu && menu.parentNode === document.body) wrap.appendChild(menu);
    }

    function positionSpareClassPickMenu(wrap) {
        const trigger = wrap.querySelector('.spare-class-pick-trigger');
        let menu = wrap.querySelector('.spare-class-pick-menu');
        if (!trigger || !menu) return;
        if (!wrap._spareClassMenu) wrap._spareClassMenu = menu;
        if (menu.parentNode !== document.body) document.body.appendChild(menu);
        menu.classList.add('spare-class-pick-menu-portal');
        const r = trigger.getBoundingClientRect();
        menu.style.display = 'block';
        menu.style.position = 'fixed';
        menu.style.left = `${r.left}px`;
        menu.style.top = `${r.bottom + 2}px`;
        menu.style.minWidth = `${Math.max(200, r.width)}px`;
        menu.style.zIndex = '10050';
    }

    function closeSpareClassPick(wrap) {
        if (!wrap) return;
        resetSpareClassPickMenu(wrap);
        wrap.classList.remove('open');
    }

    function toggleSpareClassPick(ev, wrapId) {
        ev?.stopPropagation();
        const wrap = document.getElementById(wrapId);
        if (!wrap) return;
        const opening = !wrap.classList.contains('open');
        document.querySelectorAll('.spare-class-pick.open').forEach(el => {
            if (el !== wrap) closeSpareClassPick(el);
        });
        if (!opening) {
            closeSpareClassPick(wrap);
            return;
        }
        wrap.classList.add('open');
        positionSpareClassPickMenu(wrap);
        const close = (e) => {
            if (!spareClassPickClickInside(wrap, e.target)) {
                closeSpareClassPick(wrap);
                document.removeEventListener('click', close);
                window.removeEventListener('scroll', onReposition, true);
                window.removeEventListener('resize', onReposition);
            }
        };
        const onReposition = () => {
            if (wrap.classList.contains('open')) positionSpareClassPickMenu(wrap);
        };
        setTimeout(() => {
            document.addEventListener('click', close);
            window.addEventListener('scroll', onReposition, true);
            window.addEventListener('resize', onReposition);
        }, 0);
    }

    function pickSpareClass(inputId, val) {
        const v = String(val || '').trim().toUpperCase();
        const hidden = document.getElementById(inputId);
        const wrap = document.getElementById(`${inputId}_wrap`);
        if (hidden) hidden.value = v;
        if (wrap) {
            const valEl = wrap.querySelector('.spare-class-pick-val');
            if (valEl) valEl.textContent = v || '—';
            wrap.querySelectorAll('.spare-class-pick-item').forEach(el => {
                el.classList.toggle('selected', el.dataset.classValue === v);
            });
            closeSpareClassPick(wrap);
        }
    }

    function rowHtml(s, focusedId, batchMap, ctx = 'main') {
        const low = TVC_Inventory.isLowStock(s);
        const sel = s.id === focusedId ? ' spare-row-focused row-selected' : '';
        const checked = ctx === 'reqWork'
            ? (reqWorkRowChecked(s) ? 'checked' : '')
            : ctx === 'consume'
                ? (consumeRowChecked(s) ? 'checked' : '')
                : ctx === 'receive'
                    ? (receiveRowChecked(s) ? 'checked' : '')
                : ctx === 'wrSpare'
                    ? (wrSpareRowChecked(s) ? 'checked' : '')
                    : (batchMap && batchMap[s.id] ? 'checked' : '');
        const sid = escAttr(s.id);
        const focusFn = ctx === 'reqWork' ? 'TVC_SpareMenu.reqWorkFocusRow'
            : ctx === 'consume' ? 'TVC_SpareMenu.consumeFocusRow'
                : ctx === 'receive' ? 'TVC_SpareMenu.receiveFocusRow'
                : ctx === 'wrSpare' ? 'TVC_SpareMenu.wrSpareFocusRow' : 'TVC_App.focusSpareRow';
        const focusClick = ctx === 'reqWork'
            ? `TVC_SpareMenu.reqWorkFocusRow('${sid}', true)`
            : ctx === 'receive'
                ? `TVC_SpareMenu.receiveFocusRow('${sid}', true)`
            : ctx === 'consume'
                ? `TVC_SpareMenu.consumeFocusRow('${sid}', ${consumeListEditable() ? 'true' : 'false'})`
            : ctx === 'wrSpare'
                ? `TVC_SpareMenu.wrSpareFocusRow('${sid}', ${wrSpareListEditable() ? 'true' : 'false'})`
            : `${focusFn}('${sid}')`;
        const toggleFn = ctx === 'reqWork' ? 'TVC_SpareMenu.reqWorkToggleRow'
            : ctx === 'consume' ? 'TVC_SpareMenu.consumeToggleRow'
                : ctx === 'receive' ? 'TVC_SpareMenu.receiveToggleRow'
                : ctx === 'wrSpare' ? 'TVC_SpareMenu.wrSpareToggleRow' : 'TVC_App.toggleSpareRow';
        const dblFn = `TVC_SpareMenu.openSpareItemHistory('${sid}')`;
        const dblAttr = (ctx === 'reqWork' || ctx === 'receive' || ctx === 'consume' || ctx === 'wrSpare') ? '' : ` ondblclick="event.preventDefault();${dblFn}"`;
        const colgroup = ctx === 'reqWork' ? reqWorkActiveColgroup()
            : ctx === 'consume' ? SPARE_CONSUME_COLGROUP
                : ctx === 'receive' ? SPARE_RECEIVE_COLGROUP
                : ctx === 'wrSpare' ? SPARE_WR_COLGROUP : SPARE_MAIN_COLGROUP;
        const reqLine = ctx === 'reqWork' ? reqLineForSpareRow(s) : null;
        const pipe = sparePipelineCols(s, reqLine);
        const stockCell = pipe.stock;
        const locked = ctx === 'reqWork' && reqWorkFormLocked();
        const quoteView = ctx === 'reqWork' && reqWorkHqQuoteViewActive();
        const vesselPostOrderRo = ctx === 'reqWork' && reqWorkVesselOrderedOrReceivedView();
        const rcvdEdit = ctx === 'reqWork' && reqWorkReceivedQtyEditable() && !quoteView
            && (!locked || reqWorkVesselReceivedRcvdOnlyEdit());
        const wrRo = ctx === 'wrSpare' && modState(getState()).wrSpareReadonly;
        const consumeRo = ctx === 'consume' && !consumeListEditable();
        const itemName = String(s.name || '').trim();
        const dwgText = String(spareDwgNo(s, getState()) || '').trim();
        const pnoText = String(spareDrawingNo(s) || '').trim();
        const workText = String(spareWorking(s) || '').trim();
        const cosOverRob = spareCosExceedsRob(ctx, s);
        const overCls = cosOverRob ? ' spare-cos-over-rob' : '';
        const overTitle = cosOverRob ? ' title="Consumption (Cos) exceeds ROB"' : '';
        const pipelineCells = (ctx === 'main' || (ctx === 'reqWork' && !quoteView))
            ? `<td class="c-await">${pipe.awaiting}</td><td class="c-need">${formatNeedHtml(pipe.need)}</td>`
            : '';
        const reqCells = ctx === 'reqWork'
            ? `${pipelineCells}<td class="c-req${reqQtyMismatchClass('req', reqLine)}">${rcvdEdit ? esc(String(pipe.request)) : reqWorkRequestCellHtml(s, sid, locked)}</td><td class="c-assess${reqQtyMismatchClass('assess', reqLine)}">${esc(pipe.assess)}</td><td class="c-rcvd${reqQtyMismatchClass('rcvd', reqLine)}">${rcvdEdit ? reqWorkReceivedCellHtml(s, sid) : esc(pipe.rcvd)}</td>`
            : (ctx === 'main' ? pipelineCells : '');
        const reqWorkMetricCells = ctx === 'reqWork'
            ? (quoteView
                ? reqWorkQuoteRowCells(s, reqWorkSpareIdKey(s.id), locked)
                : `<td class="c-work"${cellTitleAttr(workText)}>${spareWorking(s)}</td>
            <td class="c-std">${spareStandardQty(s)}</td>
            <td class="c-stk">${stockCell}</td>${reqCells}`)
            : `<td class="c-work"${cellTitleAttr(workText)}>${spareWorking(s)}</td>
            <td class="c-std">${spareStandardQty(s)}</td>
            <td class="c-stk${overCls}"${overTitle}>${stockCell}</td>${reqCells}`;
        const consumeCell = ctx === 'consume'
            ? `<td class="c-cons${overCls}"${overTitle}>${consumeQtyCellHtml(s, sid)}</td>`
            : '';
        const receiveCell = ctx === 'receive'
            ? `<td class="c-await">${pipe.awaiting}</td><td class="c-recv">${receiveQtyCellHtml(s, sid)}</td>`
            : '';
        const wrQtyCell = ctx === 'wrSpare'
            ? `<td class="c-cons${overCls}"${overTitle}>${wrQtyCellHtml(s, sid, wrRo)}</td>`
            : '';
        const tableCls = ctx === 'reqWork' ? 'spare-data-table spare-data-table-req spare-data-row'
            : ctx === 'consume' ? 'spare-data-table spare-data-table-consume spare-data-row'
                : ctx === 'receive' ? 'spare-data-table spare-data-table-receive spare-data-row'
                : ctx === 'wrSpare' ? 'spare-data-table spare-data-table-wrspare spare-data-row'
                    : 'spare-data-table spare-data-row';
        const identityCells = ctx === 'receive'
            ? `<td class="c-item"${cellTitleAttr(itemName)}>${esc(s.name)}</td>
            <td class="c-pno"${cellTitleAttr(pnoText)}>${esc(spareDrawingNo(s) || '—')}</td>`
            : `<td class="c-dwg"${cellTitleAttr(dwgText)}>${esc(spareDwgNo(s, getState()) || '—')}</td>
            <td class="c-pno"${cellTitleAttr(pnoText)}>${esc(spareDrawingNo(s) || '—')}</td>
            <td class="c-item"${cellTitleAttr(itemName)}>${esc(s.name)}</td>`;
        return `<table class="${tableCls}" role="presentation" data-spare-id="${sid}"
            onclick="${focusClick}"${dblAttr}>${colgroup}<tbody><tr class="spare-row${low ? ' row-overdue' : ''}${sel}"
            tabindex="0" role="button" style="cursor:pointer">
            <td class="c-chk" onclick="event.stopPropagation()">
                <input type="checkbox" class="spare-row-chk" ${checked}${locked || wrRo || consumeRo || vesselPostOrderRo ? ' disabled' : ''} aria-label="Select part"
                    onclick="event.stopPropagation()"
                    onchange="${toggleFn}('${sid}', this.checked)">
            </td>
            <td class="c-num"${cellTitleAttr(spareNumbering(s))}><strong>${esc(spareNumbering(s))}</strong></td>
            <td class="c-cls">${esc(spareClass(s))}</td>
            ${identityCells}
            <td class="c-unit">${esc(spareUnit(s))}</td>
            ${ctx === 'reqWork' ? reqWorkMetricCells : `<td class="c-work"${cellTitleAttr(workText)}>${spareWorking(s)}</td>
            <td class="c-std">${spareStandardQty(s)}</td>
            <td class="c-stk${overCls}"${overTitle}>${stockCell}</td>${reqCells}`}${consumeCell}${receiveCell}${wrQtyCell}
        </tr></tbody></table>`;
    }

    let _reqWorkResizeObs = null;
    let _spareListResizeObs = null;
    let _spareDashResizeObs = null;
    let _consumeResizeObs = null;
    let _receiveResizeObs = null;

    function syncHeadLayout(scrollId, headId, trackId, minWidth) {
        const scroll = document.getElementById(scrollId);
        const head = document.getElementById(headId);
        const track = document.getElementById(trackId);
        const table = head?.querySelector('.spare-data-table');
        const inner = scroll?.querySelector('.vl-inner');
        if (!scroll || !head || !track || !table) return;
        const tableW = Math.max(scroll.clientWidth, minWidth);
        const sb = scroll.offsetWidth - scroll.clientWidth;
        if (inner) {
            inner.style.setProperty('width', `${tableW}px`, 'important');
            inner.style.setProperty('min-width', `${minWidth}px`, 'important');
        }
        scroll.style.setProperty('--spare-table-w', `${tableW}px`);
        head.style.paddingRight = sb > 0 ? `${sb}px` : '';
        track.style.width = `${scroll.clientWidth}px`;
        table.style.width = `${tableW}px`;
        table.style.minWidth = `${tableW}px`;
        table.style.maxWidth = `${tableW}px`;
        track.scrollLeft = scroll.scrollLeft;
    }

    function bindHeadTrackScroll(scroll, headId) {
        const head = document.getElementById(headId);
        const track = head?.querySelector('.spare-head-track');
        if (!track) return;
        if (track === scroll._tvcHeadTrackEl) return;
        if (scroll._tvcHeadTrackEl && scroll._tvcHeadTrackHandler) {
            scroll._tvcHeadTrackEl.removeEventListener('scroll', scroll._tvcHeadTrackHandler);
        }
        scroll._tvcHeadTrackEl = track;
        scroll._tvcHeadTrackHandler = () => {
            if (Math.abs(scroll.scrollLeft - track.scrollLeft) > 0.5) {
                scroll.scrollLeft = track.scrollLeft;
            }
        };
        track.addEventListener('scroll', scroll._tvcHeadTrackHandler, { passive: true });
    }

    function bindHeadLayoutSync(scroll, syncFn, obsKey) {
        if (!scroll) return;
        const headId = obsKey === 'reqWork' ? 'reqWorkListHead'
            : obsKey === 'consume' ? 'consumeListHead'
                : obsKey === 'receive' ? 'receiveListHead'
                : obsKey === 'wrSpare' ? 'wrSpareListHead'
                    : 'spareListHead';
        const run = () => {
            syncFn();
            if (obsKey !== 'reqWork' && obsKey !== 'consume' && obsKey !== 'receive') bindHeadTrackScroll(scroll, headId);
        };
        const prevScroll = scroll.onscroll;
        scroll.onscroll = () => {
            if (typeof prevScroll === 'function') prevScroll();
            run();
        };
        run();
        requestAnimationFrame(() => {
            run();
            requestAnimationFrame(run);
        });
        if (obsKey === 'spare') {
            if (_spareListResizeObs) _spareListResizeObs.disconnect();
            if (typeof ResizeObserver !== 'undefined') {
                _spareListResizeObs = new ResizeObserver(run);
                _spareListResizeObs.observe(scroll);
                const head = document.getElementById('spareListHead');
                if (head) _spareListResizeObs.observe(head);
            }
        } else if (obsKey === 'reqWork') {
            if (_reqWorkResizeObs) _reqWorkResizeObs.disconnect();
            if (typeof ResizeObserver !== 'undefined') {
                _reqWorkResizeObs = new ResizeObserver(run);
                _reqWorkResizeObs.observe(scroll);
                const hscroll = scroll.closest('.spare-req-table-hscroll');
                if (hscroll) _reqWorkResizeObs.observe(hscroll);
                const workScroll = scroll.closest('.spare-req-work-scroll');
                if (workScroll) _reqWorkResizeObs.observe(workScroll);
                const modalBox = scroll.closest('.modal-box');
                if (modalBox) _reqWorkResizeObs.observe(modalBox);
            }
        } else if (obsKey === 'consume') {
            if (_consumeResizeObs) _consumeResizeObs.disconnect();
            if (typeof ResizeObserver !== 'undefined') {
                _consumeResizeObs = new ResizeObserver(run);
                _consumeResizeObs.observe(scroll);
                const hscroll = scroll.closest('.spare-req-table-hscroll');
                if (hscroll) _consumeResizeObs.observe(hscroll);
                const head = document.getElementById('consumeListHead');
                if (head) _consumeResizeObs.observe(head);
            }
        } else if (obsKey === 'receive') {
            if (_receiveResizeObs) _receiveResizeObs.disconnect();
            if (typeof ResizeObserver !== 'undefined') {
                _receiveResizeObs = new ResizeObserver(run);
                _receiveResizeObs.observe(scroll);
                const head = document.getElementById('receiveListHead');
                if (head) _receiveResizeObs.observe(head);
                const modalBox = scroll.closest('.modal-box');
                if (modalBox) _receiveResizeObs.observe(modalBox);
            }
        } else if (obsKey === 'wrSpare') {
            if (_wrSpareResizeObs) _wrSpareResizeObs.disconnect();
            if (typeof ResizeObserver !== 'undefined') {
                _wrSpareResizeObs = new ResizeObserver(run);
                _wrSpareResizeObs.observe(scroll);
                const hscroll = scroll.closest('.spare-req-table-hscroll');
                if (hscroll) _wrSpareResizeObs.observe(hscroll);
                const head = document.getElementById('wrSpareListHead');
                if (head) _wrSpareResizeObs.observe(head);
            }
        }
        if (!window._tvcSpareHeadResizeBound) {
            window._tvcSpareHeadResizeBound = true;
            window.addEventListener('resize', () => {
                syncSpareHeadLayout();
                const m = modState(getState());
                if (m.reqWorkOpen) syncReqWorkHeadLayout();
                if (m.consumeOpen) syncConsumeHeadLayout();
                if (m.receiveOpen) syncReceiveHeadLayout();
                if (m.wrSpareOpen) syncWrSpareHeadLayout();
            });
        }
    }

    function syncSpareHeadLayout() {
        syncHeadLayout('spareListScroll', 'spareListHead', 'spareListHeadTrack', SPARE_MAIN_MIN_WIDTH);
    }

    function captureSpareListScroll() {
        const scroll = document.getElementById('spareListScroll');
        return scroll ? scroll.scrollTop : 0;
    }

    function restoreSpareListScroll(scrollTop) {
        if (scrollTop == null || scrollTop < 0) return;
        const scroll = document.getElementById('spareListScroll');
        if (!scroll) return;
        const apply = () => {
            scroll.scrollTop = scrollTop;
            if (vl) vl.refresh();
        };
        apply();
        requestAnimationFrame(() => {
            apply();
            requestAnimationFrame(() => {
                apply();
                syncSpareHeadLayout();
            });
        });
    }

    function mountVirtualList(restoreScrollTop) {
        const head = document.getElementById('spareListHead');
        if (head) {
            head.innerHTML = `<div id="spareListHeadTrack" class="spare-head-track"><table class="spare-data-table spare-data-head">
                ${SPARE_MAIN_COLGROUP}
                ${SPARE_MAIN_TABLE_HEAD}
            </table></div>`;
        }
        const scroll = document.getElementById('spareListScroll');
        if (!scroll) return;
        if (vl) vl.destroy();
        if (!_cachedList.length) {
            const st = getState();
            const gLabel = groupFilterLabel(st);
            const filterTag = spareActiveFilterLabel(modState(st));
            const filterLabel = [gLabel, filterTag].filter(Boolean).join(' · ');
            scroll.innerHTML = `<div class="spare-empty-list muted" style="padding:24px;text-align:center">
                No parts to display.${filterLabel ? ' (Filter: ' + esc(filterLabel) + ' — <a href="#" onclick="TVC_SpareMenu.selectSpareGroup(null);TVC_SpareMenu.clearListFilters();return false">View all</a>)' : ''}
                ${gLabel ? '<br><small>No parts assigned to this GROUP. Use ✏️ Modify or the detail panel to set <b>GROUP (PMS)</b>.</small>' : ''}
            </div>`;
            return;
        }
        vl = TVC_VirtualList.mount(scroll, {
            getCount: () => _cachedList.length,
            renderRow: (i) => {
                const s = _cachedList[i];
                const st = getState();
                const focusedId = getFocusedSpareId(st);
                const batchMap = st.spareListSelected || {};
                return s ? rowHtml(s, focusedId, batchMap) : '';
            },
        });
        if (head) bindHeadLayoutSync(scroll, syncSpareHeadLayout, 'spare');
        updateSpareHeadCheckAll();
        requestAnimationFrame(() => {
            syncSpareHeadLayout();
            requestAnimationFrame(syncSpareHeadLayout);
        });
        if (restoreScrollTop != null && restoreScrollTop >= 0) {
            scroll.scrollTop = restoreScrollTop;
            if (vl) vl.refresh();
        }
    }

    async function renderDetailPanel(id, canRequisition, canModify) {
        const inner = document.getElementById('spareDetailInner');
        if (!inner) return;
        const st = getState();
        const s = (st.spares || []).map(canon).find(x => x.id === id);
        if (!s) { inner.innerHTML = '<p class="muted">Part not found</p>'; return; }

        const low = TVC_Inventory.isLowStock(s);
        const recQty = TVC_Inventory.recommendedOrderQty(s);
        const maint = await maintenanceHistory(id, st);

        const supplyRows = (s.history || []).slice().reverse().map(h => `<tr>
            <td>${esc((h.at || '').slice(0, 10))}</td>
            <td>${esc(h.type || '—')}</td>
            <td style="text-align:center">${h.qty ?? '—'}</td>
            <td style="text-align:right">${h.price != null ? esc(h.price) : '—'}</td>
            <td>${esc(h.vendorComment || h.note || '—')}</td>
        </tr>`).join('') || '<tr><td colspan="5" class="muted" style="text-align:center">No supply history</td></tr>';

        const maintRows = maint.slice(0, 20).map(h => `<tr>
            <td>${esc((h.at || '').slice(0, 10))}</td>
            <td>${esc(h.jobCode)}</td>
            <td style="text-align:center">${h.qty ?? '—'}</td>
            <td>${esc(h.type)}</td>
        </tr>`).join('') || '<tr><td colspan="4" class="muted" style="text-align:center">No maintenance history</td></tr>';

        inner.innerHTML = `
            <button class="spare-panel-close" onclick="TVC_SpareMenu.closeDetail()" title="Close">×</button>
            <h3 class="spare-panel-title">${esc(partNo(s))}</h3>
            <p class="spare-panel-sub">${esc(s.name)}</p>
            <div class="spare-panel-badges">
                ${s.isCritical ? '<span class="pill overdue">CRITICAL</span>' : ''}
                ${low ? '<span class="pill overdue">LOW STOCK</span>' : '<span class="pill ok">OK</span>'}
                ${s.partClass ? `<span class="pill">${esc(s.partClass)}</span>` : ''}
            </div>
            <div class="spare-panel-meta">
                <div><b>Universal Code</b><br>${esc(s.universalItemCode || s.universalCode || '—')}</div>
                <div><b>Stock</b><br>${s.currentStock ?? 0} <span class="muted">(prev ${s.previousStock ?? 0})</span></div>
                <div><b>Working</b><br>${spareWorking(s)}</div>
                <div><b>Standard</b><br>${TVC_Inventory.standardStock(s)}</div>
                <div><b>Min</b><br>${s.minStock ?? 0}</div>
                <div><b>GROUP (PMS)</b><br>${canModify
                    ? `<select id="spDetailGroup" class="spare-group-select" onchange="TVC_SpareMenu.saveDetailGroup('${s.id}')">${buildGroupSelectHtml(st, s.group)}</select>`
                    : esc(spareGroupLabel(s))}</div>
                <div><b>Location</b><br>${esc(s.location || '—')}</div>
                <div><b>Parent Equipment</b><br>${esc(s.parentEquipmentID || '—')}</div>
                <div><b>Price</b><br>${s.price != null ? esc(s.price) + ' ' + esc(s.currency || '') : '—'}</div>
                <div><b>Vendor</b><br>${esc(s.vendorComment || s.maker || '—')}</div>
            </div>
            <div class="spare-panel-actions">
                ${canRequisition ? `<button class="btn btn-sm btn-green" onclick="TVC_SpareMenu.createRequisition('${s.id}')">📝 Requisition</button>` : ''}
                <button class="btn btn-sm" onclick="TVC_SpareMenu.assignToTask('${s.id}')">🔧 Assign to Task</button>
                ${canModify ? `<button class="btn btn-sm" onclick="TVC_SpareMenu.edit('${s.id}')">✏️ Edit</button>` : ''}
            </div>
            <div class="spics-hist-head">Supply History</div>
            <div class="spare-panel-scroll"><table class="spics-hist-table">
                <thead><tr><th>Date</th><th>Type</th><th>Qty</th><th>Price</th><th>Comment</th></tr></thead>
                <tbody>${supplyRows}</tbody>
            </table></div>
            <div class="spics-hist-head">Maintenance / Task History</div>
            <div class="spare-panel-scroll"><table class="spics-hist-table">
                <thead><tr><th>Date</th><th>Job</th><th>Qty</th><th>Type</th></tr></thead>
                <tbody>${maintRows}</tbody>
            </table></div>
            ${low && canRequisition ? `<p class="muted spare-rec-hint">Recommended order qty: <strong>${recQty}</strong></p>` : ''}`;
    }

    function reqListTotalData(req) {
        return reqLineCount(req);
    }

    function reqLineTargetQty(line) {
        if (!line) return 0;
        return line.qty_approved != null ? (Number(line.qty_approved) || 0) : (Number(line.qty_requested) || 0);
    }

    /** Requisition list O/S — spare line count where Rcvd < Eval. */
    function reqLineOutstandingByEval(line) {
        if (!line) return false;
        return (Number(line.qty_received) || 0) < reqLineTargetQty(line);
    }

    /** Line has outstanding qty (Req − Rcvd) — same basis as Wait. */
    function reqLineIsOutstanding(line) {
        return reqLinePendingQty(line) > 0;
    }

    /** Raw O/S before waive — Req − Rcvd sum. */
    function reqRawOutstandingData(req) {
        const effective = reqEffectiveForWait(req);
        return (effective.lines || []).reduce((sum, l) => sum + reqLinePendingQty(l), 0);
    }

    function reqOsWaived(req) {
        return !!(req?.os_waived_approved_at);
    }

    function reqOsWaiveInitiated(req) {
        return !!(String(req?.os_waive_reason || '').trim());
    }

    function reqCanCloseOs(req) {
        if (!req || reqOsWaived(req)) return false;
        const st = getState();
        const label = reqListDisplayStatusLabel(req, st);
        if (label !== VESSEL_REQ_LIST_STATUS.RECEIVED && label !== VESSEL_REQ_LIST_STATUS.RECEIVED_EXPORT
            && label !== 'Received' && label !== 'Partial Recv'
            && reqWorkflowPhase(req) !== REQ_LIST_PHASE.RECEIVED) return false;
        return reqRawOutstandingData(req) > 0;
    }

    function closeOsApprovalState(req, st) {
        st = st || getState();
        const user = spareInventoryUser(st);
        const dept = req?.department || st?.department;
        const isConfirmed = !!(req?.os_waived_confirmed_at || req?.os_waived_confirmed_by);
        const isApproved = reqOsWaived(req);
        const initiated = reqOsWaiveInitiated(req);
        const canConfirmNow = initiated && !isConfirmed && !isApproved
            && !!user && TVC_RBAC.canConfirmDepartment(user, dept);
        const canApproveNow = isConfirmed && !isApproved
            && !!user && TVC_RBAC.canApproveHqReport(user);
        return {
            isConfirmed,
            isApproved,
            canConfirmNow,
            canApproveNow,
            confirmedByVal: isConfirmed ? (req.os_waived_confirmed_by || requisitionConfirmByLabel(st, req)) : '',
            approvedByVal: isApproved ? (req?.os_waived_approved_by || 'Company') : '',
        };
    }

    function reqCloseOsButtonEnabled(req, st) {
        if (!req || reqOsWaived(req)) return false;
        if (reqCanCloseOs(req)) return true;
        if (reqOsWaiveInitiated(req)) {
            const approval = closeOsApprovalState(req, st);
            return approval.canConfirmNow || approval.canApproveNow;
        }
        return false;
    }

    function resolveCloseOsTargetReq(allReqs, m, st) {
        st = st || getState();
        if (isRequisitionListWindow(m) && _reqWorkDraft?.id && reqWorkListHasDisplayedReq(m)
            && reqCloseOsButtonEnabled(_reqWorkDraft, st)) {
            return allReqs.find(r => r.id === _reqWorkDraft.id) || _reqWorkDraft;
        }
        if (m.selectedReqId) {
            const req = allReqs.find(r => r.id === m.selectedReqId);
            if (reqCloseOsButtonEnabled(req, st)) return req;
        }
        const checkedIds = Object.keys(m.reqListCheckedIds || {}).filter(k => m.reqListCheckedIds[k]);
        const eligible = checkedIds
            .map(id => allReqs.find(r => r.id === id))
            .filter(r => reqCloseOsButtonEnabled(r, st));
        if (eligible.length === 1) return eligible[0];
        if (eligible.length > 1 && m.selectedReqId) {
            const sel = eligible.find(r => r.id === m.selectedReqId);
            if (sel) return sel;
        }
        return eligible[0] || null;
    }

    function reqListAnyCloseOsEnabled(m, allReqs, st) {
        return !!resolveCloseOsTargetReq(allReqs, m, st);
    }

    /** Requisition List O/S — spare line count where Rcvd < Eval; 0 when O/S waived. */
    function reqListOutstandingData(req) {
        if (reqOsWaived(req)) return 0;
        const effective = reqEffectiveForWait(req);
        return normalizeReqLines(effective?.lines).filter(l => reqLineOutstandingByEval(l)).length;
    }

    function reqListDateCell(val) {
        return esc(val || '—');
    }

    function reqListReceivedDate(req) {
        return req.received_on || req.received_date || '';
    }

    function reqListReceivedPort(req) {
        return String(req.received_port || '').trim();
    }

    function reqListTypeKind(req) {
        if (req?.dock_use) return 'DOCK';
        if (String(req?.priority || '').toUpperCase() === 'URGENT') return 'URGENT';
        return 'ROUTINE';
    }

    function reqListTypeLabel(req) {
        const k = reqListTypeKind(req);
        if (k === 'URGENT') return 'Urgent';
        if (k === 'DOCK') return 'Dock Use';
        return 'Routine';
    }

    function reqListTypeCellClass(req) {
        const k = reqListTypeKind(req);
        if (k === 'URGENT') return 'rl-type-urgent';
        if (k === 'DOCK') return 'rl-type-dock';
        return 'rl-type-routine';
    }

    function reqApplyTypeKind(req, kind) {
        const k = String(kind || 'ROUTINE').toUpperCase();
        if (k === 'DOCK') {
            req.dock_use = true;
            req.priority = 'ROUTINE';
        } else if (k === 'URGENT') {
            req.dock_use = false;
            req.priority = 'URGENT';
        } else {
            req.dock_use = false;
            req.priority = 'ROUTINE';
        }
    }

    function reqListReportedDate(req) {
        return req.made_on || req.reported_on || '';
    }

    function reqListStatusLabel(req, st) {
        st = st || getState();
        if (isReqListHqUser(st)) return reqHqListWorkflowStatus(req);
        return reqVesselListWorkflowStatus(req);
    }

    function reqHqListWorkflowStatus(req) {
        if (!req) return HQ_REQ_LIST_STATUS.REQUISITION;

        if (reqWorkHqReceivedImportComplete(req)) return HQ_REQ_LIST_STATUS.RECEIVED;
        const hasReceivedDate = !!reqListReceivedDate(req);
        const hasLineReceived = (req.lines || []).some(l => Number(l.qty_received) > 0);
        if (hasReceivedDate && hasLineReceived) return HQ_REQ_LIST_STATUS.RECEIVED;

        if (reqWorkHqPurchaseOrderExportComplete(req)) return HQ_REQ_LIST_STATUS.ORDERED;

        if (reqWorkHqImportQuoteComplete(req)) return HQ_REQ_LIST_STATUS.EVALUATING;

        if (reqWorkHqQuoteExportComplete(req)) return HQ_REQ_LIST_STATUS.REQ_QUOTE;

        return HQ_REQ_LIST_STATUS.REQUISITION;
    }

    function reqHqWorkflowPhase(req) {
        switch (reqHqListWorkflowStatus(req)) {
            case HQ_REQ_LIST_STATUS.RECEIVED: return REQ_LIST_PHASE.RECEIVED;
            case HQ_REQ_LIST_STATUS.ORDERED:
            case HQ_REQ_LIST_STATUS.EVALUATING: return REQ_LIST_PHASE.ASSESSED;
            case HQ_REQ_LIST_STATUS.REQ_QUOTE: return REQ_LIST_PHASE.CONFIRMED;
            case HQ_REQ_LIST_STATUS.REQUISITION: return REQ_LIST_PHASE.SUBMITTED;
            default: return REQ_LIST_PHASE.DRAFT;
        }
    }

    /** HQ Report History — phase tab key (Evaluating vs Ordered kept separate) */
    function reqHqListPhaseKey(req) {
        switch (reqHqListWorkflowStatus(req)) {
            case HQ_REQ_LIST_STATUS.RECEIVED: return HQ_REQ_LIST_PHASE.RECEIVED;
            case HQ_REQ_LIST_STATUS.ORDERED: return HQ_REQ_LIST_PHASE.ORDERED;
            case HQ_REQ_LIST_STATUS.EVALUATING: return HQ_REQ_LIST_PHASE.EVALUATING;
            case HQ_REQ_LIST_STATUS.REQ_QUOTE: return HQ_REQ_LIST_PHASE.REQ_QUOTE;
            default: return HQ_REQ_LIST_PHASE.REQUISITION;
        }
    }

    function reqHqListPhaseLabel(phaseKey) {
        switch (phaseKey) {
            case HQ_REQ_LIST_PHASE.REQUISITION: return HQ_REQ_LIST_STATUS.REQUISITION;
            case HQ_REQ_LIST_PHASE.REQ_QUOTE: return HQ_REQ_LIST_STATUS.REQ_QUOTE;
            case HQ_REQ_LIST_PHASE.EVALUATING: return HQ_REQ_LIST_STATUS.EVALUATING;
            case HQ_REQ_LIST_PHASE.ORDERED: return HQ_REQ_LIST_STATUS.ORDERED;
            case HQ_REQ_LIST_PHASE.RECEIVED: return HQ_REQ_LIST_STATUS.RECEIVED;
            default: return phaseKey;
        }
    }

    function reqHqStatusFlowStage(req, m) {
        if (!req) return 'requisition';
        const status = reqHqListWorkflowStatus(req);
        switch (status) {
            case HQ_REQ_LIST_STATUS.RECEIVED: return 'received';
            case HQ_REQ_LIST_STATUS.ORDERED: return 'ordered';
            case HQ_REQ_LIST_STATUS.EVALUATING: return 'evaluation';
            case HQ_REQ_LIST_STATUS.REQ_QUOTE: return 'quoted';
            default:
                if (m?.reqWorkHqStickySelectVendorReqId === req?.id) return 'request-quote';
                return 'requisition';
        }
    }

    function applyHqFlowStageToUi(m, req, stage) {
        if (!m) return;
        const quoteStages = new Set(['request-quote', 'export-quote', 'quoted', 'import-quote', 'evaluation']);
        m.reqWorkHqQuoteView = quoteStages.has(stage);
        m.reqWorkHqEvalView = stage === 'evaluation';
        if (stage === 'evaluation' && req) initReqWorkEvalQtyFromReq(req);
        else closeReqQuoteHeadPicks();
    }

    function reqHqSetViewFlowStage(m, req, stage) {
        if (!m || !req?.id || !stage) return;
        m.reqWorkHqFlowStage = stage;
        m.reqWorkHqFlowReqId = req.id;
        if (stage === 'request-quote') m.reqWorkHqStickySelectVendorReqId = req.id;
        if (stage === 'requisition') m.reqWorkHqStickySelectVendorReqId = null;
        applyHqFlowStageToUi(m, req, stage);
    }

    function reqVesselListWorkflowStatus(req) {
        if (!req) return VESSEL_REQ_LIST_STATUS.REPORTED;
        if (reqVesselReceivedExportComplete(req)) return VESSEL_REQ_LIST_STATUS.RECEIVED_EXPORT;
        const phase = reqWorkflowPhase(req);
        if (phase === REQ_LIST_PHASE.RECEIVED) return VESSEL_REQ_LIST_STATUS.RECEIVED;
        if (phase === REQ_LIST_PHASE.ASSESSED) return VESSEL_REQ_LIST_STATUS.ORDERED;
        if (phase === REQ_LIST_PHASE.SUBMITTED) return VESSEL_REQ_LIST_STATUS.SUBMITTED;
        if (phase === REQ_LIST_PHASE.CONFIRMED) return VESSEL_REQ_LIST_STATUS.CONFIRMED;
        return VESSEL_REQ_LIST_STATUS.REPORTED;
    }

    function reqVesselHasEvalData(req) {
        if (!req) return false;
        if (req.assessed_on) return true;
        return (req.lines || []).some(l => l.qty_approved != null && l.qty_approved !== '');
    }

    /** Requisition Received 단계 — 입고 수량 기록 완료 */
    function reqVesselReceiveRecorded(req) {
        if (!req) return false;
        if (req?.vessel_flow?.receiveSaved) return true;
        const hasLineReceived = (req.lines || []).some(l => Number(l.qty_received) > 0);
        return !!reqListReceivedDate(req) && hasLineReceived;
    }

    /** Submit 탭 Data Export 완료 */
    function reqVesselSubmitExportComplete(req) {
        return !!TVC_Inventory?.isRequisitionSubmittedExport?.(req);
    }

    /** Received 탭 Data Export 완료 */
    function reqVesselReceivedExportComplete(req) {
        return !!req?.vessel_flow?.receivedExported;
    }

    /** Received Export 이후 워크플로 잠금 */
    function reqVesselWorkflowComplete(req) {
        return reqVesselReceivedExportComplete(req);
    }

    /** Order import 완료 — Eval·Ordered 반영 후 Received 단계 진입 */
    function reqVesselOrderImportComplete(req) {
        if (!req) return false;
        if (req?.vessel_flow?.orderImported) return true;
        if (!reqVesselHasEvalData(req)) return false;
        if (reqVesselListWorkflowStatus(req) === VESSEL_REQ_LIST_STATUS.ORDERED) return true;
        if (String(req.ordered_on || '').trim()) return true;
        const RS = TVC_Inventory?.REQ_STATUS || {};
        return String(req.status || '').toUpperCase() === RS.APPROVED;
    }

    function reqVesselReportTabHint(req) {
        if (!req) return 'Select a requisition first.';
        if (reqVesselFlowStageEnabled(req, 'report')) return '';
        return 'Report tab is locked after Confirm.';
    }

    function reqVesselConfirmTabHint(req) {
        if (!req) return 'Select a requisition first.';
        if (reqVesselFlowStageEnabled(req, 'confirm')) return '';
        if (reqVesselListWorkflowStatus(req) === VESSEL_REQ_LIST_STATUS.REPORTED) {
            return 'Report the requisition first.';
        }
        return 'Confirm tab is locked after Submit.';
    }

    function reqVesselEvaluatedTabHint(req) {
        if (!req) return 'Select a requisition first.';
        if (reqVesselFlowStageEnabled(req, 'evaluated')) return '';
        if (reqVesselWorkflowComplete(req)) return 'Workflow complete.';
        if (!reqVesselHasEvalData(req)) {
            return 'Import order first (Order tab → Data Import).';
        }
        return 'Ordered tab is not available.';
    }

    function reqVesselSubmittedTabHint(req) {
        if (!req) return 'Select a requisition first.';
        if (reqVesselFlowStageEnabled(req, 'submitted')) return '';
        if (reqVesselWorkflowComplete(req)) return 'Workflow complete.';
        if (!reqVesselSubmitExportComplete(req)) {
            return 'Export requisition first (Requisition tab → Data Export).';
        }
        return 'Submitted tab is not available.';
    }

    function reqVesselEvaluationImportTabHint(req) {
        if (!req) return 'Select a requisition first.';
        if (reqVesselFlowStageEnabled(req, 'evaluation-import')) return '';
        if (reqVesselWorkflowComplete(req)) return 'Workflow complete.';
        if (!reqVesselSubmitExportComplete(req)) {
            return 'Export requisition first (Requisition tab → Data Export).';
        }
        return 'Order import is not available.';
    }

    function reqVesselReceivedTabHint(req) {
        if (!req) return 'Select a requisition first.';
        if (reqVesselFlowStageEnabled(req, 'received')) return '';
        if (reqVesselWorkflowComplete(req)) return 'Workflow complete.';
        if (!reqVesselOrderImportComplete(req) && !reqVesselSubmitExportComplete(req)) {
            return 'Export requisition first (Requisition tab → Data Export).';
        }
        if (!reqVesselOrderImportComplete(req)) {
            return 'Import order first (Order tab → Data Import).';
        }
        return 'Received tab is not available.';
    }

    function reqVesselReceivedExportTabHint(req) {
        if (!req) return 'Select a requisition first.';
        if (reqVesselFlowStageEnabled(req, 'received-export')) return '';
        if (reqVesselWorkflowComplete(req)) return 'Received export complete.';
        if (!reqVesselReceiveRecorded(req)) {
            return 'Complete received quantities in Spare Parts Requisition first.';
        }
        return 'Received export is not available.';
    }

    function ensureReqWorkVesselFlowState(req) {
        if (!req) return {};
        if (!req.vessel_flow) req.vessel_flow = {};
        return req.vessel_flow;
    }

    const REQ_VESSEL_FLOW_STAGES = ['report', 'confirm', 'submit', 'submitted', 'evaluation-import', 'evaluated', 'received', 'received-export'];
    const REQ_HQ_FLOW_STAGES = ['requisition', 'request-quote', 'export-quote', 'quoted', 'import-quote', 'evaluation', 'purchase-order', 'ordered', 'received-import', 'received'];

    function normalizeHqFlowStage(stage) {
        const s = String(stage || '');
        if (s === 'reply-evaluation') return 'purchase-order';
        if (s === 'order') return 'ordered';
        return s;
    }

    function reqFlowStageIndex(stages, stage) {
        const idx = stages.indexOf(stage);
        return idx >= 0 ? idx : -1;
    }

    function reqFlowBumpMaxStage(stages, container, maxKey, stage) {
        const idx = reqFlowStageIndex(stages, stage);
        if (idx < 0) return;
        const curIdx = reqFlowStageIndex(stages, container[maxKey] || '');
        if (idx > curIdx) container[maxKey] = stage;
    }

    function reqVesselBumpMaxFlowStage(req, stage) {
        reqFlowBumpMaxStage(REQ_VESSEL_FLOW_STAGES, ensureReqWorkVesselFlowState(req), 'maxFlowStage', stage);
    }

    function reqHqBumpMaxFlowStage(req, stage) {
        reqFlowBumpMaxStage(REQ_HQ_FLOW_STAGES, ensureReqWorkQuoteState(req), 'maxFlowStage', normalizeHqFlowStage(stage));
    }

    function reqVesselSyncMaxFlowStage(req) {
        if (!req) return;
        const vf = ensureReqWorkVesselFlowState(req);
        if (!vf.maxFlowStage && vf.flowStage) reqVesselBumpMaxFlowStage(req, vf.flowStage);
        const idx = reqVesselFlowProgressIndex(req);
        if (idx >= 0) vf.maxFlowStage = REQ_VESSEL_FLOW_STAGES[idx];
    }

    function reqHqSyncMaxFlowStage(req) {
        if (!req) return;
        const q = ensureReqWorkQuoteState(req);
        if (!q.maxFlowStage && q.flowStage) reqHqBumpMaxFlowStage(req, q.flowStage);
        const idx = reqHqFlowProgressIndex(req);
        if (idx >= 0) q.maxFlowStage = REQ_HQ_FLOW_STAGES[idx];
    }

    function reqVesselFlowProgressIndex(req) {
        if (!req) return 0;
        let maxIdx = 0;
        const bump = (stage) => {
            const idx = REQ_VESSEL_FLOW_STAGES.indexOf(stage);
            if (idx >= 0) maxIdx = Math.max(maxIdx, idx);
        };
        const vf = req.vessel_flow || {};
        if (vf.maxFlowStage) bump(vf.maxFlowStage);
        if (reqVesselWorkflowComplete(req) || reqVesselReceiveRecorded(req) || reqVesselReceivedExportComplete(req)) {
            bump('received-export');
        } else {
            const status = reqVesselListWorkflowStatus(req);
            if (status === VESSEL_REQ_LIST_STATUS.RECEIVED) bump('received');
            else if (status === VESSEL_REQ_LIST_STATUS.ORDERED || reqVesselHasEvalData(req)) {
                bump('evaluated');
                if (reqVesselOrderImportComplete(req)) bump('received');
            }
            else if (status === VESSEL_REQ_LIST_STATUS.SUBMITTED || reqVesselSubmitExportComplete(req)) bump('submitted');
            else if (status === VESSEL_REQ_LIST_STATUS.CONFIRMED) bump('confirm');
            else bump('report');
        }
        return maxIdx;
    }

    function reqHqFlowProgressIndex(req) {
        if (!req) return 0;
        let maxIdx = 0;
        const bump = (stage) => {
            const idx = REQ_HQ_FLOW_STAGES.indexOf(normalizeHqFlowStage(stage));
            if (idx >= 0) maxIdx = Math.max(maxIdx, idx);
        };
        const q = req.hq_quote || {};
        if (q.maxFlowStage) bump(q.maxFlowStage);
        if (q.receivedImported || reqWorkHqReceivedImportComplete(req)) bump('received');
        if (q.orderExported || String(req.ordered_on || '').trim()) bump('ordered');
        if (q.replyExported) bump('purchase-order');
        if (reqWorkHqEvaluationReady(req)) bump('evaluation');
        if (reqWorkHqVendorQuoteImported(req)) bump('import-quote');
        if (q.quoteExported) bump('quoted');
        return maxIdx;
    }

    function reqVesselFlowStageReached(req, stage) {
        const stageIdx = REQ_VESSEL_FLOW_STAGES.indexOf(stage);
        return stageIdx >= 0 && stageIdx <= reqVesselFlowProgressIndex(req);
    }

    function reqHqFlowStageReached(req, stage) {
        const stageIdx = REQ_HQ_FLOW_STAGES.indexOf(stage);
        return stageIdx >= 0 && stageIdx <= reqHqFlowProgressIndex(req);
    }

    function reqVesselFlowStageEnabled(req, stage) {
        if (!req) return false;
        if (reqVesselFlowStageReached(req, stage)) return true;
        if (reqVesselWorkflowComplete(req)) return false;
        const status = reqVesselListWorkflowStatus(req);
        switch (stage) {
            case 'report':
                return status === VESSEL_REQ_LIST_STATUS.REPORTED;
            case 'confirm':
                return status === VESSEL_REQ_LIST_STATUS.REPORTED
                    || status === VESSEL_REQ_LIST_STATUS.CONFIRMED;
            case 'submit':
                return [
                    VESSEL_REQ_LIST_STATUS.CONFIRMED,
                    VESSEL_REQ_LIST_STATUS.SUBMITTED,
                    VESSEL_REQ_LIST_STATUS.ORDERED,
                    VESSEL_REQ_LIST_STATUS.RECEIVED,
                    VESSEL_REQ_LIST_STATUS.RECEIVED_EXPORT,
                ].includes(status);
            case 'submitted':
            case 'evaluation-import':
                return reqVesselSubmitExportComplete(req) || reqVesselOrderImportComplete(req);
            case 'evaluated':
                return (reqVesselSubmitExportComplete(req) && reqVesselHasEvalData(req))
                    || reqVesselOrderImportComplete(req);
            case 'received':
                return reqVesselSubmitExportComplete(req) || reqVesselOrderImportComplete(req);
            case 'received-export':
                return reqVesselOrderImportComplete(req) || reqVesselReceiveRecorded(req);
            default:
                return false;
        }
    }

    function reqVesselStatusFlowStage(req) {
        if (!req) return 'report';
        const status = reqVesselListWorkflowStatus(req);
        switch (status) {
            case VESSEL_REQ_LIST_STATUS.RECEIVED_EXPORT: return 'received-export';
            case VESSEL_REQ_LIST_STATUS.RECEIVED: return 'received';
            case VESSEL_REQ_LIST_STATUS.ORDERED: return 'evaluated';
            case VESSEL_REQ_LIST_STATUS.SUBMITTED: return 'submitted';
            case VESSEL_REQ_LIST_STATUS.CONFIRMED: return 'confirm';
            default: return 'report';
        }
    }

    function reqVesselSetViewFlowStage(m, req, stage) {
        if (!m || !req?.id || !stage) return;
        m.reqWorkVesselFlowStage = stage;
        m.reqWorkVesselFlowReqId = req.id;
    }

    function reqVesselResolvedFlowStage(req) {
        return reqVesselStatusFlowStage(req);
    }

    function reqVesselActiveFlowStage(m, req) {
        if (req?.id && m?.reqWorkVesselFlowReqId === req.id && m.reqWorkVesselFlowStage) {
            const stage = m.reqWorkVesselFlowStage;
            if (reqVesselFlowStageEnabled(req, stage)) return stage;
        }
        return reqVesselStatusFlowStage(req);
    }

    function applyReqWorkVesselStageOnLoad(req, m) {
        if (!req || !m) return;
        if (isReqListHqUser(getState())) return;
        m.reqWorkHqQuoteView = false;
        m.reqWorkHqEvalView = false;
        reqVesselSyncMaxFlowStage(req);
        m.reqWorkVesselFlowStage = reqVesselStatusFlowStage(req);
        m.reqWorkVesselFlowReqId = req.id;
    }

    async function persistReqWorkVesselDraft() {
        const req = _reqWorkDraft;
        if (!req?.id) return;
        captureReqWorkLineQtys();
        captureReqWorkMeta();
        try {
            await TVC_Inventory.saveRequisition(req);
        } catch (e) {
            console.warn('[VESSEL_FLOW] persist failed', e);
        }
    }

    function reqListDisplayStatusLabel(req, st) {
        st = st || getState();
        if (isReqListHqUser(st)) return reqHqListWorkflowStatus(req);
        return reqVesselListWorkflowStatus(req);
    }

    /** Requisition List work window — STATUS column */
    function reqWorkMetaStatusLabel(req, st) {
        return reqListDisplayStatusLabel(req, st);
    }

    function reqListDateInPeriod(dateStr, from, to) {
        if (!from && !to) return true;
        const d = String(dateStr || '').slice(0, 10);
        if (!d) return false;
        if (from && d < from) return false;
        if (to && d > to) return false;
        return true;
    }

    function reqListMatchSearch(req, q) {
        if (!q) return true;
        const hay = [
            req.req_no, req.deliver_port, reqListReportedDate(req), req.assessed_on,
            reqListReceivedDate(req), reqListReceivedPort(req), reqListStatusLabel(req), req.made_by, req.assessed_by,
        ].join(' ').toLowerCase();
        return hay.includes(q);
    }

    function resolveReqListGroupKey(req, st = getState()) {
        if (!req) return null;
        const direct = String(req.pms_group_key || req.spare_group_key || '').trim();
        if (direct) return direct;
        if (!st.idx && (st.jobs || []).length && window.TVC_Indexes) {
            st.idx = TVC_Indexes.build(st);
        }
        for (const line of req.lines || []) {
            const sid = reqWorkSpareIdKey(line.spare_part_id);
            if (!sid) continue;
            const raw = (st.spares || []).find(s => reqWorkSameSpareId(s.id, sid));
            if (!raw) continue;
            const s = canon(raw);
            const gl = String(s.group || '').trim();
            if (!gl) continue;
            if (st.idx?.groupNodes) {
                const node = st.idx.groupNodes.find(n =>
                    String(n.label || '').trim() === gl
                    || String(n.key || '').endsWith('|' + gl)
                );
                if (node) return node.key;
            }
            return `${s.department || st.department || ''}|${gl}`;
        }
        const pmsNo = String(req.pms_group_no || req.spare_group_label || '').trim();
        if (pmsNo && st.idx?.groupNodes) {
            const short = pmsNo.replace(/\s+/g, '');
            const node = st.idx.groupNodes.find(n =>
                String(n.label || '').replace(/\s+/g, '') === short
                || String(n.key || '').includes(short)
            );
            if (node) return node.key;
        }
        return null;
    }

    /** Open = not Received yet, or Received but still has O/S remaining. */
    function reqListIsOpen(req) {
        if (!req) return false;
        if (reqWorkflowPhase(req) !== REQ_LIST_PHASE.RECEIVED) return true;
        return reqListOutstandingData(req) > 0;
    }

    function getReqListFilters() {
        const m = modState(getState());
        return {
            groupKeys: [...(m.reqListFilterGroupKeys || [])],
            type: m.reqListFilterType || 'all',
            openOnly: !!m.reqListFilterOpen,
        };
    }

    function setReqListFilters(patch = {}) {
        const m = modState(getState());
        if (patch.groupKeys !== undefined) {
            m.reqListFilterGroupKeys = Array.isArray(patch.groupKeys) ? [...patch.groupKeys] : [];
        }
        if (patch.type !== undefined) {
            m.reqListFilterType = String(patch.type || 'all').toLowerCase() || 'all';
        }
        if (patch.openOnly !== undefined) {
            m.reqListFilterOpen = !!patch.openOnly;
        }
        if (typeof TVC_ListFilters !== 'undefined') TVC_ListFilters.syncBtn('reqList');
        refreshReqListUi();
    }

    function reqListMatchesTypeAndGroup(req, st) {
        const m = modState(st);
        const type = String(m.reqListFilterType || 'all').toLowerCase();
        const groupKeys = m.reqListFilterGroupKeys || [];
        if (type && type !== 'all') {
            if (String(reqListTypeKind(req) || '').toLowerCase() !== type) return false;
        }
        if (groupKeys.length) {
            const gk = resolveReqListGroupKey(req, st);
            if (!gk || !groupKeys.includes(gk)) return false;
        }
        if (m.reqListFilterOpen && !reqListIsOpen(req)) return false;
        return true;
    }

    function filterReqList(reqs, st) {
        const m = modState(st);
        if (isReqListHqUser(st)) {
            const cur = m.reqListPhaseTab || REQ_LIST_PHASE.ALL;
            if (cur !== REQ_LIST_PHASE.ALL && !Object.values(HQ_REQ_LIST_PHASE).includes(cur)) {
                m.reqListPhaseTab = REQ_LIST_PHASE.ALL;
            }
        }
        const phase = m.reqListPhaseTab || REQ_LIST_PHASE.ALL;
        return reqListFilterBase(reqs, st).filter(req => reqListMatchesPhase(req, phase, st));
    }

    function reqListFilterBase(reqs, st) {
        const m = modState(st);
        const from = m.reqListPeriodFrom || '';
        const to = m.reqListPeriodTo || '';
        const q = String(m.reqListSearch || '').trim().toLowerCase();
        return (reqs || []).filter(req =>
            reqListDateInPeriod(reqListReportedDate(req), from, to)
            && reqListMatchSearch(req, q)
            && reqListMatchesTypeAndGroup(req, st));
    }

    function reqListPhaseCounts(allReqs, st) {
        const filtered = reqListFilterBase(allReqs, st);
        const counts = { all: filtered.length };
        const isHq = isReqListHqUser(st);
        if (isHq) {
            Object.values(HQ_REQ_LIST_PHASE).forEach(p => { counts[p] = 0; });
        } else {
            Object.values(REQ_LIST_PHASE).forEach(p => { if (p !== REQ_LIST_PHASE.ALL) counts[p] = 0; });
        }
        filtered.forEach(req => {
            if (isHq) {
                const p = reqHqListPhaseKey(req);
                counts[p] = (counts[p] || 0) + 1;
                return;
            }
            const p = reqWorkflowPhase(req);
            if (p === REQ_LIST_PHASE.DRAFT || p === REQ_LIST_PHASE.REPORTED) {
                counts[REQ_LIST_PHASE.REPORTED] = (counts[REQ_LIST_PHASE.REPORTED] || 0) + 1;
            } else {
                counts[p] = (counts[p] || 0) + 1;
            }
        });
        return counts;
    }

    function reqListPhaseTabsHtml(m, counts, st) {
        st = st || getState();
        const isHq = isReqListHqUser(st);
        const tabs = isHq ? [
            [REQ_LIST_PHASE.ALL, 'All'],
            [HQ_REQ_LIST_PHASE.REQUISITION, HQ_REQ_LIST_STATUS.REQUISITION],
            [HQ_REQ_LIST_PHASE.REQ_QUOTE, HQ_REQ_LIST_STATUS.REQ_QUOTE],
            [HQ_REQ_LIST_PHASE.EVALUATING, HQ_REQ_LIST_STATUS.EVALUATING],
            [HQ_REQ_LIST_PHASE.ORDERED, HQ_REQ_LIST_STATUS.ORDERED],
            [HQ_REQ_LIST_PHASE.RECEIVED, HQ_REQ_LIST_STATUS.RECEIVED],
        ] : [
            [REQ_LIST_PHASE.ALL, 'All'],
            [REQ_LIST_PHASE.REPORTED, 'Reported'],
            [REQ_LIST_PHASE.CONFIRMED, 'Confirmed'],
            [REQ_LIST_PHASE.SUBMITTED, 'Submitted'],
            [REQ_LIST_PHASE.ASSESSED, 'Ordered'],
            [REQ_LIST_PHASE.RECEIVED, 'Received'],
        ];
        const cur = m.reqListPhaseTab || REQ_LIST_PHASE.ALL;
        return `<div class="req-list-phase-tabs" role="tablist" aria-label="Requisition phase">
            ${tabs.map(([id, label]) => {
                const n = counts[id] ?? 0;
                const active = cur === id ? ' active' : '';
                return `<button type="button" class="req-phase-tab${active}" role="tab" aria-selected="${cur === id ? 'true' : 'false'}"
                    onclick="TVC_SpareMenu.reqListSetPhase('${id}')">${esc(label)}${n ? `<span class="req-phase-count">${n}</span>` : ''}</button>`;
            }).join('')}
        </div>`;
    }

    function reqListSetPhase(phase) {
        const st = getState();
        const p = phase === 'exported' ? REQ_LIST_PHASE.SUBMITTED : (phase || REQ_LIST_PHASE.ALL);
        modState(st).reqListPhaseTab = p;
        refreshReqListUi();
    }

    function reqListSpareGroupNo(req, st) {
        const direct = String(req?.spare_group_label || req?.pms_group_no || '').trim();
        if (direct) return safeTreeLabel(direct) || direct;
        if (!req?.lines?.length || !st) return '—';
        if (!st.idx && (st.jobs || []).length && window.TVC_Indexes) {
            st.idx = TVC_Indexes.build(st);
        }
        for (const line of req.lines) {
            const sid = reqWorkSpareIdKey(line.spare_part_id);
            if (!sid) continue;
            const raw = (st.spares || []).find(s => reqWorkSameSpareId(s.id, sid));
            if (!raw) continue;
            const s = canon(raw);
            const gl = String(s.group || '').trim();
            if (gl) return safeTreeLabel(gl);
            const fromCode = groupLabelFromCode(st, s);
            if (fromCode) return safeTreeLabel(fromCode);
        }
        return '—';
    }

    function reqListRequiredDateCell(req) {
        const from = String(req.deliver_date_from || '').slice(0, 10);
        const to = String(req.deliver_date_to || '').slice(0, 10);
        if (from && to) return esc(`${from} ~ ${to}`);
        if (from) return esc(from);
        if (to) return esc(to);
        return '—';
    }

    function isReqListHqUser(st) {
        const user = spareInventoryUser(st);
        return !!(user && TVC_RBAC?.isHqAccount?.(user));
    }

    function reqListApprovalFlags(req) {
        const status = spareListStatus(req);
        const isConfirmed = status === SPARE_LIST_STATUS.CONFIRMED || status === SPARE_LIST_STATUS.APPROVED
            || !!(req?.confirmed_by || req?.confirmed_at);
        const isApproved = status === SPARE_LIST_STATUS.APPROVED || !!(req?.approved_by || req?.approved_at);
        return {
            status,
            isConfirmed,
            isApproved,
            phase: reqWorkflowPhase(req),
            workflowLabel: reqListWorkflowLabel(req),
        };
    }

    function reqListIsReportedForConfirm(req) {
        const flags = reqListApprovalFlags(req);
        if (flags.isConfirmed || flags.isApproved) return false;
        return flags.workflowLabel === 'Reported'
            || flags.phase === REQ_LIST_PHASE.REPORTED
            || flags.status === SPARE_LIST_STATUS.REPORTED;
    }

    function reqListIsConfirmedForApprove(req) {
        // legacy helper — HQ Approve now uses Submitted only (reqListIsSubmittedForApprove)
        const flags = reqListApprovalFlags(req);
        if (!flags.isConfirmed || flags.isApproved) return false;
        return flags.workflowLabel === 'Confirmed'
            || flags.phase === REQ_LIST_PHASE.CONFIRMED
            || flags.workflowLabel === 'Submitted'
            || flags.phase === REQ_LIST_PHASE.SUBMITTED
            || flags.workflowLabel === 'Ordered'
            || flags.workflowLabel === 'Evaluated'
            || flags.phase === REQ_LIST_PHASE.ASSESSED
            || flags.status === SPARE_LIST_STATUS.CONFIRMED;
    }

    function reqListIsSubmittedForApprove(req) {
        if (!req) return false;
        return reqWorkflowPhase(req) === REQ_LIST_PHASE.SUBMITTED
            || reqListWorkflowLabel(req) === 'Submitted';
    }

    function reqListIsEvaluatingForApprove(req, st) {
        if (!req) return false;
        st = st || getState();
        if (!isReqListHqUser(st)) return false;
        return reqHqListWorkflowStatus(req) === HQ_REQ_LIST_STATUS.EVALUATING;
    }

    function reqListIsHqRequisitionStatus(req) {
        return reqHqListWorkflowStatus(req) === HQ_REQ_LIST_STATUS.REQUISITION;
    }

    function reqListIsHqEvaluatingApproved(req) {
        if (!req) return false;
        if (reqHqListWorkflowStatus(req) !== HQ_REQ_LIST_STATUS.EVALUATING) return false;
        return reqListApprovalFlags(req).isApproved;
    }

    function canConfirmRequisition(st, req) {
        if (!req) return false;
        const user = spareInventoryUser(st);
        if (!user) return false;
        // Confirm = vessel mode only; Reported enables, Confirmed+ disables
        if (isReqListHqUser(st)) return false;
        if (!reqListIsReportedForConfirm(req)) return false;
        const dept = req.department || st.department;
        return TVC_RBAC.canConfirmDepartment(user, dept);
    }

    function requisitionConfirmByLabel(st, req) {
        const user = spareInventoryUser(st);
        const dept = req?.department || st?.department;
        if (window.TVC_RBAC?.isHqAccount?.(user)) return 'Superintendent';
        return TVC_RBAC.getDepartmentConfirmLabel(dept, user) || TVC_RBAC.getRankLabel(user);
    }

    function canUnconfirmRequisition(st, req) {
        if (!req) return false;
        if (spareListStatus(req) !== SPARE_LIST_STATUS.CONFIRMED) return false;
        const user = spareInventoryUser(st);
        const dept = req.department || st.department;
        return TVC_RBAC.canConfirmDepartment(user, dept);
    }

    function reqListCanConfirm(st, req) {
        return canConfirmRequisition(st, req);
    }

    function reqListCheckedConfirmableIds(m, allReqs, st) {
        const map = m.reqListCheckedIds || {};
        return Object.keys(map).filter(id => {
            if (!map[id]) return false;
            const req = allReqs.find(r => r.id === id);
            return reqListCanConfirm(st, req);
        });
    }

    function reqListAnyCheckedCanConfirm(m, allReqs, st) {
        return reqListCheckedConfirmableIds(m, allReqs, st).length > 0;
    }

    function canApproveRequisition(st, req) {
        if (!req) return false;
        const user = spareInventoryUser(st);
        if (!user || !TVC_RBAC.canApproveHqReport(user)) return false;
        if (reqListApprovalFlags(req).isApproved) return false;
        // HQ Superintendent 작성분: Reported만 있어도 Approve 가능
        if (TVC_RBAC.canHqDirectApprove(user, req)) {
            return spareListStatus(req) !== SPARE_LIST_STATUS.DRAFT;
        }
        // Evaluating — Company Approve 후 Order Export 가능
        if (reqListIsEvaluatingForApprove(req, st)) return true;
        // 선박 작성분: Submitted일 때 Approve
        return reqListIsSubmittedForApprove(req);
    }

    function reqListCanApprove(st, req) {
        return canApproveRequisition(st, req);
    }

    function reqListCheckedApprovableIds(m, allReqs, st) {
        const map = m.reqListCheckedIds || {};
        return Object.keys(map).filter(id => {
            if (!map[id]) return false;
            const req = allReqs.find(r => r.id === id);
            return reqListCanApprove(st, req);
        });
    }

    function reqListAnyCheckedCanApprove(m, allReqs, st) {
        return reqListCheckedApprovableIds(m, allReqs, st).length > 0;
    }

    function reqListAnyChecked(m) {
        return Object.keys(m.reqListCheckedIds || {}).some(k => m.reqListCheckedIds[k]);
    }

    function reqListCanDeleteSelection(m, st) {
        if (!canCreateRequisition(st)) return false;
        return reqListAnyChecked(m) || !!m.selectedReqId;
    }

    function isHistoryReqListVisible() {
        const pane = document.getElementById('histSparePane');
        return !!(pane && !pane.classList.contains('hidden') && document.getElementById('spareHistReqListHost'));
    }

    function activeReqListFilterPrefix() {
        if (isHistoryReqListVisible() && document.getElementById('spareHistReqPeriodFrom')) return 'spareHistReq';
        const hist = document.getElementById('reqWorkHistPanel');
        if (_reqWorkHistOpen && hist && !hist.classList.contains('hidden')
            && hist.querySelector('#reqHistPeriodFrom')) return 'reqHist';
        return 'reqList';
    }

    function syncReqListFilterUi(st) {
        const m = modState(st);
        ['reqList', 'reqHist', 'spareHistReq'].forEach(prefix => {
            const fromEl = document.getElementById(prefix + 'PeriodFrom');
            const toEl = document.getElementById(prefix + 'PeriodTo');
            const searchEl = document.getElementById(prefix + 'Search');
            const filterEl = document.getElementById(prefix + 'PeriodFilter');
            if (fromEl) fromEl.value = m.reqListPeriodFrom || '';
            if (toEl) toEl.value = m.reqListPeriodTo || '';
            if (searchEl) searchEl.value = m.reqListSearch || '';
            if (filterEl) filterEl.classList.toggle('active', !!(m.reqListPeriodFrom || m.reqListPeriodTo));
            const clearBtn = searchEl?.parentElement?.querySelector('.search-clear-btn');
            if (clearBtn) clearBtn.classList.toggle('hidden', !m.reqListSearch);
        });
        if (typeof TVC_ListFilters !== 'undefined') TVC_ListFilters.syncBtn('reqList');
    }

    function renderReqListFiltersHtml(m, opts = {}) {
        const prefix = opts.prefix || 'reqList';
        const btnId = prefix === 'reqHist' ? 'reqHistListFilterBtn'
            : prefix === 'spareHistReq' ? 'spareHistReqListFilterBtn'
            : 'reqListFilterBtn';
        const pmsLayout = !!opts.pmsLayout;
        const periodClear = `<button type="button" class="btn btn-sm act-period-clear" onclick="TVC_SpareMenu.reqListClearPeriodAndFilters()">Clear</button>`;
        const filterBtn = `<div class="list-filter-wrap">
                        <button type="button" id="${btnId}" class="btn btn-sm list-filter-btn" onclick="TVC_ListFilters.toggle('reqList', event)">Filter</button>
                    </div>`;
        const countHtml = opts.countId
            ? `<span class="count-label" id="${escAttr(opts.countId)}">${esc(opts.countLabel || '—')}</span>`
            : '';
        const periodInput = pmsLayout
            ? (id, val) => `<input type="date" id="${id}" class="act-period-input" aria-label="${id.endsWith('From') ? 'Period from' : 'Period to'}"
                            value="${escAttr(val || '')}" onchange="TVC_SpareMenu.reqListSetPeriod()">`
            : (id, val) => `<input type="text" id="${id}" class="act-period-input tvc-date-input" placeholder="YYYY-MM-DD" autocomplete="off" aria-label="${id.endsWith('From') ? 'Period from' : 'Period to'}"
                            value="${escAttr(val || '')}" onchange="TVC_SpareMenu.reqListSetPeriod()">`;
        return `<div class="hist-toolbar hist-toolbar-filters spare-req-list-filters list-filter-stack${pmsLayout ? ' spare-hist-pms-filters' : ''}">
                <div class="filter-bar list-filter-period-row">
                    <div id="${prefix}PeriodFilter" class="act-period-filter" title="Filter by Reported Date">
                        <span class="act-period-label">Period</span>
                        ${periodInput(prefix + 'PeriodFrom', m.reqListPeriodFrom)}
                        <span class="act-period-sep">~</span>
                        ${periodInput(prefix + 'PeriodTo', m.reqListPeriodTo)}
                        ${filterBtn}
                    </div>
                    ${periodClear}
                    ${countHtml}
                </div>
                <div class="filter-bar list-filter-search-row">
                    <div class="search-field-wrap">
                        <input class="search-input" id="${prefix}Search" placeholder="Search REQ NO / PORT / STATUS…"
                            value="${esc(m.reqListSearch || '')}" oninput="TVC_SpareMenu.reqListSetSearch(this.value)">
                        <button type="button" class="search-clear-btn${m.reqListSearch ? '' : ' hidden'}" title="Clear search" aria-label="Clear search"
                            onclick="TVC_SpareMenu.reqListClearSearch()">×</button>
                    </div>
                </div>
            </div>`;
    }

    function reqListSetPeriod() {
        const st = getState();
        const m = modState(st);
        const prefix = activeReqListFilterPrefix();
        m.reqListPeriodFrom = document.getElementById(prefix + 'PeriodFrom')?.value || '';
        m.reqListPeriodTo = document.getElementById(prefix + 'PeriodTo')?.value || '';
        refreshReqListUi();
    }

    function reqListClearPeriod() {
        const st = getState();
        const m = modState(st);
        m.reqListPeriodFrom = '';
        m.reqListPeriodTo = '';
        refreshReqListUi();
    }

    function reqListClearPeriodAndFilters() {
        const st = getState();
        const m = modState(st);
        m.reqListPeriodFrom = '';
        m.reqListPeriodTo = '';
        m.reqListFilterGroupKeys = [];
        m.reqListFilterType = 'all';
        m.reqListFilterOpen = false;
        TVC_ListFilters?.refreshOpenPopover?.();
        refreshReqListUi();
    }

    function reqListSetSearch(v) {
        modState(getState()).reqListSearch = v;
        clearTimeout(_reqListSearchT);
        _reqListSearchT = setTimeout(() => refreshReqListUi(), 150);
    }

    function reqListClearSearch() {
        modState(getState()).reqListSearch = '';
        ['reqListSearch', 'reqHistSearch', 'spareHistReqSearch'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.value = '';
        });
        refreshReqListUi();
    }

    let _reqListSearchT = null;

    function spareListToolbarBtn(label, onclick, disabled = false, cls = '') {
        return `<button type="button" class="btn btn-sm${cls ? ' ' + cls : ''}" onclick="${onclick}"${disabled ? ' disabled' : ''}>${esc(label)}</button>`;
    }

    function spareListPrintStyles() {
        return `body{font-family:system-ui,sans-serif;font-size:11px;margin:16px;color:#1a202c}
            h1{font-size:18px;color:#1a365d;margin:0 0 4px}
            .meta{color:#4a5568;margin:0 0 12px;font-size:11px}
            table{width:100%;border-collapse:collapse}
            th,td{border:1px solid #cbd5e0;padding:5px 7px;text-align:left;vertical-align:top}
            th{background:#1a365d;color:#fff;font-weight:600;text-align:center}
            td.num{text-align:center;font-variant-numeric:tabular-nums}
            tr:nth-child(even){background:#f7fafc}
            @media print{body{margin:10mm}}`;
    }

    async function spareListPrintMeta(title) {
        const { st, vesselId } = await vesselScope();
        const ship = await vesselLabel(vesselId, st.department)
            || document.getElementById('cmaxsShipName')?.textContent?.trim() || '—';
        const dept = TVC_RBAC.getDeptLabel(st.department);
        return `<h1>${esc(title)}</h1><p class="meta">${esc(ship)} · ${esc(dept)} · ${new Date().toLocaleString()}</p>`;
    }

    function spareListPrintFilterNote(parts) {
        const notes = parts.filter(Boolean);
        return notes.length ? `<p class="meta">${notes.map(n => esc(n)).join(' · ')}</p>` : '';
    }

    async function openSpareListPrintWindow(title, bodyHtml, preview) {
        const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>TVC — ${esc(title)}</title>
            <style>${spareListPrintStyles()}</style></head><body>${bodyHtml}</body></html>`;
        const features = 'width=980,height=760,menubar=no,toolbar=no,location=no,status=no';
        const w = window.open('', '_blank', features);
        if (!w) {
            await TVC_Dialog.alert('Pop-up blocked. Allow pop-ups to print or preview.');
            return;
        }
        w.document.open();
        w.document.write(html);
        w.document.close();
        w.focus();
        if (!preview) setTimeout(() => { try { w.print(); } catch (_) {} }, 400);
    }

    async function buildConsumedLogListPrintBody() {
        const { st, vesselId } = await vesselScope();
        const m = modState(st);
        const allLogs = await TVC_Inventory.listConsumeLogs(vesselId);
        const logs = filterConsumeLogs(allLogs, st);
        const filterParts = [];
        if (m.consumeLogSearch) filterParts.push(`Search: "${m.consumeLogSearch}"`);
        if (m.consumeLogPeriodFrom || m.consumeLogPeriodTo) {
            filterParts.push(`Period: ${m.consumeLogPeriodFrom || '…'} ~ ${m.consumeLogPeriodTo || '…'}`);
        }
        if (m.consumeLogFilterType && m.consumeLogFilterType !== 'all') {
            filterParts.push(`Type: ${String(m.consumeLogFilterType).toUpperCase()}`);
        }
        if ((m.consumeLogFilterGroupKeys || []).length) {
            filterParts.push(`PMS Group: ${m.consumeLogFilterGroupKeys.length} selected`);
        }
        const head = `<tr>
            <th>Type</th><th>File No</th><th>JOB CODE</th><th>SORT-1</th><th>SORT-2</th>
            <th>Reported Date</th><th>Status</th><th><span class="hist-th-stack"><span>Spare</span><span>Data</span></span></th>
        </tr>`;
        const rows = logs.map(log => {
            const reported = log.made_on || log.consumed_date || '';
            const jobItems = consumeLogJobItems(log);
            const jobText = jobItems.map(i => i.job_code).filter(Boolean).join(', ') || String(log.job_code || '').trim();
            const sort1Text = jobItems.length > 1
                ? jobItems.map(i => i.sort1).filter(Boolean).join(' · ')
                : String(jobItems[0]?.sort1 || log.sort1 || '').trim();
            const sort2Text = jobItems.length > 1
                ? jobItems.map(i => i.sort2).filter(Boolean).join(' · ')
                : String(jobItems[0]?.sort2 || log.sort2 || '').trim();
            const page1 = resolveConsumeLogPage1Meta(log);
            return `<tr>
                <td class="num">${esc(consumeLogTypeMarker(log).letter)}</td>
                <td>${esc(page1.file_no || '—')}</td>
                <td>${esc(jobText || '—')}</td>
                <td>${esc(sort1Text || '—')}</td>
                <td>${esc(sort2Text || '—')}</td>
                <td class="num">${esc(reported || '—')}</td>
                <td class="num">${esc(consumeLogStatusLabel(log))}</td>
                <td class="num">${consumeLogTotalData(log)}</td>
            </tr>`;
        }).join('');
        const meta = await spareListPrintMeta('Consumption List');
        return `${meta}
            ${spareListPrintFilterNote(filterParts)}
            <p class="meta">${logs.length} item(s)</p>
            <table>${head}${rows || `<tr><td colspan="8">No consumed logs to print.</td></tr>`}</table>`;
    }

    async function buildRequisitionListPrintBody() {
        const { st, vesselId } = await vesselScope();
        const m = modState(st);
        const allReqs = await TVC_Inventory.listRequisitions(vesselId);
        const reqs = filterReqList(allReqs, st);
        const filterParts = [];
        if (m.reqListSearch) filterParts.push(`Search: "${m.reqListSearch}"`);
        if (m.reqListPeriodFrom || m.reqListPeriodTo) {
            filterParts.push(`Period: ${m.reqListPeriodFrom || '…'} ~ ${m.reqListPeriodTo || '…'}`);
        }
        if (m.reqListFilterType && m.reqListFilterType !== 'all') {
            filterParts.push(`Type: ${String(m.reqListFilterType)}`);
        }
        if ((m.reqListFilterGroupKeys || []).length) {
            filterParts.push(`PMS Group: ${m.reqListFilterGroupKeys.length} selected`);
        }
        if (m.reqListFilterOpen) filterParts.push('Open');
        if (m.reqListPhaseTab && m.reqListPhaseTab !== REQ_LIST_PHASE.ALL) {
            const phaseLabel = isReqListHqUser(getState())
                ? reqHqListPhaseLabel(m.reqListPhaseTab)
                : m.reqListPhaseTab;
            filterParts.push(`Phase: ${phaseLabel}`);
        }
        const head = `<tr>
            <th rowspan="2">Type</th>
            <th rowspan="2">Requisition No.</th>
            <th rowspan="2">SPARE Group No.</th>
            <th colspan="2">Required</th>
            <th rowspan="2">Reported Date</th>
            <th rowspan="2">Status</th>
            <th colspan="2">Received</th>
            <th rowspan="2">O/S</th>
            <th rowspan="2">Total Data</th>
        </tr>
        <tr><th>Date</th><th>Port</th><th>Date</th><th>Port</th></tr>`;
        const rows = reqs.map(r => {
            const reported = reqListReportedDate(r);
            const received = reqListReceivedDate(r);
            const recvPort = reqListReceivedPort(r);
            const spareGroup = reqListSpareGroupNo(r, st);
            return `<tr>
                <td>${esc(reqListTypeLabel(r))}</td>
                <td>${esc(r.req_no || '—')}</td>
                <td>${esc(spareGroup)}</td>
                <td class="num">${reqListRequiredDateCell(r)}</td>
                <td>${esc(r.deliver_port || '—')}</td>
                <td class="num">${reqListDateCell(reported)}</td>
                <td>${esc(reqListDisplayStatusLabel(r, st))}</td>
                <td class="num">${reqListDateCell(received)}</td>
                <td>${esc(recvPort || '—')}</td>
                <td class="num">${reqListOutstandingData(r)}</td>
                <td class="num">${reqListTotalData(r)}</td>
            </tr>`;
        }).join('');
        const meta = await spareListPrintMeta('Requisition List');
        return `${meta}
            ${spareListPrintFilterNote(filterParts)}
            <p class="meta">${reqs.length} item(s)</p>
            <table>${head}${rows || `<tr><td colspan="12">No requisitions to print.</td></tr>`}</table>`;
    }

    function clearReqListUiState(m) {
        m.reqListCheckedIds = {};
        m.selectedReqId = null;
    }

    function applyReqListSelection(m, id) {
        // 행 선택(하이라이트)만 — 체크는 ㅁ를 직접 눌러야 함
        m.selectedReqId = id || null;
    }

    function isReqWorkXferExportReturn(returnTo) {
        return returnTo === 'req-work' || returnTo === 'req-work-select-vendor';
    }

    function restoreReqWorkSelectVendorView() {
        const m = modState(getState());
        reqHqSetViewFlowStage(m, _reqWorkDraft, 'request-quote');
        refreshReqWorkListUi();
    }

    async function applyReqListXferExportCheck(checkId) {
        if (!checkId || !_reqListXferExportKind) return;
        const { vesselId } = await vesselScope();
        const allReqs = await TVC_Inventory.listRequisitions(vesselId);
        const m = modState(getState());
        const req = allReqs.find(r => String(r.id) === String(checkId));
        if (req && reqListCanXferExport(req)) {
            ensureReqListChecked(m)[req.id] = true;
            updateReqListHeadCheckAll(filterReqList(allReqs, getState()));
            syncReqListRowSelection(document.getElementById('spareReqListBody'));
            await syncReqListModalToolbar();
        }
    }

    function ensureReqListChecked(m) {
        if (!m.reqListCheckedIds) m.reqListCheckedIds = {};
        return m.reqListCheckedIds;
    }

    function reqListIsRowChecked(m, id) {
        return !!m.reqListCheckedIds?.[id];
    }

    function updateReqListHeadCheckAll(reqs) {
        const scopeReqs = _reqListXferExportKind
            ? (reqs || []).filter(r => reqListCanXferExport(r))
            : (reqs || []);
        const m = modState(getState());
        const headLocked = isRequisitionListWindow(m) && !m.reqWorkListEditing;
        document.querySelectorAll('.spare-req-list-head-chk').forEach(el => {
            if (headLocked || !scopeReqs.length) {
                el.checked = false;
                el.indeterminate = false;
                el.disabled = headLocked || !scopeReqs.length;
                return;
            }
            el.disabled = false;
            let n = 0;
            scopeReqs.forEach(r => { if (reqListIsRowChecked(m, r.id)) n++; });
            el.checked = n === scopeReqs.length;
            el.indeterminate = n > 0 && n < scopeReqs.length;
        });
    }

    async function patchReqListUi() {
        const body = document.getElementById('spareReqListBody');
        if (!body) return;
        const { st, vesselId } = await vesselScope();
        const m = modState(st);
        const allReqs = await TVC_Inventory.listRequisitions(vesselId);
        const reqs = filterReqList(allReqs, st);
        const phaseCounts = reqListPhaseCounts(allReqs, st);
        const reqRows = buildReqListRowsHtml(reqs, 'modal');
        const countLabel = `${reqs.length}${reqs.length !== allReqs.length ? ` / ${allReqs.length}` : ''} item(s)`;

        body.querySelectorAll('.spare-req-list-count').forEach(el => { el.textContent = countLabel; });
        const tbody = body.querySelector('#spareReqListScroll .spare-req-list-body-table tbody');
        if (tbody) tbody.innerHTML = reqRows;

        const phaseHost = body.querySelector('.req-list-phase-tabs');
        if (phaseHost && !_reqListXferExportKind) {
            phaseHost.outerHTML = reqListPhaseTabsHtml(m, phaseCounts, st);
        }

        updateReqListHeadCheckAll(reqs);
        await syncReqListModalToolbar();

        const searchEl = document.getElementById('reqListSearch');
        const clearBtn = searchEl?.parentElement?.querySelector('.search-clear-btn');
        if (clearBtn) clearBtn.classList.toggle('hidden', !m.reqListSearch);
        const periodEl = document.getElementById('reqListPeriodFilter');
        if (periodEl) periodEl.classList.toggle('active', !!(m.reqListPeriodFrom || m.reqListPeriodTo));
        if (typeof TVC_ListFilters !== 'undefined') TVC_ListFilters.syncBtn('reqList');
    }

    function reqListCanSoftPatch() {
        const modal = document.getElementById('spareReqListModal');
        return !!(modal && !modal.classList.contains('hidden')
            && document.querySelector('#spareReqListScroll .spare-req-list-body-table tbody'));
    }

    async function refreshReqListUi(opts = {}) {
        const modal = document.getElementById('spareReqListModal');
        if (modal && !modal.classList.contains('hidden')) {
            if (!opts.full && reqListCanSoftPatch()) await patchReqListUi();
            else await renderReqListModal();
        }
        if (isHistoryReqListVisible()) {
            if (!opts.full && document.querySelector('#spareHistReqListScroll .spare-req-list-body-table tbody')) {
                await patchHistoryReqList();
            } else {
                await renderHistoryReqList();
            }
        }
        if (_reqWorkHistOpen) await refreshReqWorkHistList(opts.full ? { full: true } : {});
    }

    function syncReqListRowSelection(root) {
        const scope = root || document;
        const m = modState(getState());
        const selId = m.selectedReqId;
        scope.querySelectorAll('.spare-req-list-body-table tbody tr[data-req-id]').forEach(tr => {
            const id = tr.getAttribute('data-req-id');
            tr.classList.toggle('sr-req-sel', id === selId);
            const cb = tr.querySelector('input[type="checkbox"]');
            if (cb && !cb.disabled) cb.checked = reqListIsRowChecked(m, id);
        });
    }

    /** History list highlight follows the requisition currently open in Detail Report. */
    function followSpareHistReqList(nextId) {
        if (!nextId) return;
        applyReqListSelection(modState(getState()), nextId);
        const host = document.getElementById('spareHistReqListHost');
        if (host) syncReqListRowSelection(host);
        const scroll = document.getElementById('spareHistReqListScroll');
        const sel = scroll?.querySelector('tr.sr-req-sel');
        if (sel) sel.scrollIntoView({ block: 'nearest' });
    }

    function reqListScrollSelectedIntoView() {
        const scroll = document.getElementById('reqWorkHistListScroll')
            || document.getElementById('spareHistReqListScroll')
            || document.getElementById('spareReqListScroll');
        if (!scroll) return;
        const sel = scroll.querySelector('tr.sr-req-sel');
        if (sel) sel.scrollIntoView({ block: 'nearest' });
    }

    async function reqListMoveSelection(delta) {
        const { vesselId } = await vesselScope();
        const reqs = filterReqList(await TVC_Inventory.listRequisitions(vesselId), getState());
        if (!reqs.length) return;
        const m = modState(getState());
        let idx = reqs.findIndex(r => r.id === m.selectedReqId);
        if (idx < 0) idx = delta > 0 ? -1 : 0;
        const next = Math.max(0, Math.min(reqs.length - 1, idx + delta));
        await reqListSelectRow(reqs[next].id);
        requestAnimationFrame(reqListScrollSelectedIntoView);
    }

    function onReqListKeydown(e) {
        if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
        const t = e.target;
        if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' || t.isContentEditable)) {
            if (t.closest('#reqWorkHistPanel') || t.closest('#spareReqListBody')) {
                if (t.classList.contains('search-input')
                    || t.classList.contains('act-period-input')
                    || t.classList.contains('tvc-date-input')) return;
            }
        }
        const histOpen = _reqWorkHistOpen && document.getElementById('reqWorkHistPanel')
            && !document.getElementById('reqWorkHistPanel').classList.contains('hidden');
        const standalone = document.getElementById('spareReqListModal')
            && !document.getElementById('spareReqListModal').classList.contains('hidden');
        const historyList = isHistoryReqListVisible();
        if (!histOpen && !standalone && !historyList) return;
        if (histOpen && !isRequisitionListWindow() && !standalone) {
            // New Requisition pick list — still allow arrow nav
        }
        e.preventDefault();
        e.stopPropagation();
        reqListMoveSelection(e.key === 'ArrowDown' ? 1 : -1);
    }

    function bindReqListKeyboard() {
        const workModal = document.getElementById('spareReqWorkModal');
        if (workModal && !workModal._reqListKeyBound) {
            workModal._reqListKeyBound = true;
            workModal.addEventListener('keydown', onReqListKeydown, true);
        }
        const standalone = document.getElementById('spareReqListModal');
        if (standalone && !standalone._reqListKeyBound) {
            standalone._reqListKeyBound = true;
            standalone.addEventListener('keydown', onReqListKeydown, true);
        }
        const histHost = document.getElementById('spareHistReqListHost');
        if (histHost && !histHost._reqListKeyBound) {
            histHost._reqListKeyBound = true;
            histHost.addEventListener('keydown', onReqListKeydown, true);
        }
        bindSpareHistReqListTouchEvents();
    }

    /** Spare Report History — mobile double-tap opens Detail Report (same as desktop dblclick) */
    function bindSpareHistReqListTouchEvents() {
        const host = document.getElementById('spareHistReqListHost');
        if (!host || host._spareHistTouchBound) return;
        host._spareHistTouchBound = true;
        const DBL_TAP_MS = 300;
        let lastTouch = { id: '', time: 0 };
        host.addEventListener('touchend', (ev) => {
            if (ev.target.closest('.spare-req-list-chk')) return;
            const row = ev.target.closest('tr.spare-req-list-row[data-req-id]');
            if (!row) return;
            const reqId = row.dataset.reqId;
            if (!reqId) return;
            const now = Date.now();
            if (lastTouch.id === reqId && (now - lastTouch.time) <= DBL_TAP_MS) {
                lastTouch = { id: '', time: 0 };
                ev.preventDefault();
                reqListOpenRow(reqId);
                return;
            }
            lastTouch = { id: reqId, time: now };
        }, { passive: false });
    }

    function setSpareListToolbarBtnDisabled(scope, onclickNeedle, disabled) {
        if (!scope) return;
        const next = !!disabled;
        scope.querySelectorAll(`button[onclick*="${onclickNeedle}"]`).forEach(btn => {
            if (btn.disabled !== next) btn.disabled = next;
        });
    }

    async function syncReqListModalToolbar() {
        const body = document.getElementById('spareReqListBody');
        if (!body) return;
        const { st, vesselId } = await vesselScope();
        const m = modState(st);
        const allReqs = await TVC_Inventory.listRequisitions(vesselId);
        if (_reqListXferExportKind) {
            const ids = reqListCheckedExportableIds(m, allReqs);
            setSpareListToolbarBtnDisabled(body, 'reqListExportToMaster', !ids.length);
            return;
        }
        const selReq = m.selectedReqId ? allReqs.find(r => r.id === m.selectedReqId) : null;
        const hasSel = !!selReq;
        const canRequisition = canCreateRequisition(st);
        const canConfirm = reqListAnyCheckedCanConfirm(m, allReqs, st);
        const canApprove = reqListAnyCheckedCanApprove(m, allReqs, st);
        const canDelete = reqListCanDeleteSelection(m, st);
        const canCloseOs = reqListAnyCloseOsEnabled(m, allReqs, st);
        setSpareListToolbarBtnDisabled(body, 'reqListDetailReport', !hasSel);
        setSpareListToolbarBtnDisabled(body, 'reqListExportExcel', !hasSel);
        setSpareListToolbarBtnDisabled(body, 'reqListReportConfirm', !canConfirm);
        setSpareListToolbarBtnDisabled(body, 'reqListReportApprove', !canApprove);
        setSpareListToolbarBtnDisabled(body, 'openCloseOsModal', !canCloseOs);
        setSpareListToolbarBtnDisabled(body, 'reqListModify', !canRequisition || !hasSel);
        setSpareListToolbarBtnDisabled(body, 'reqListDelete', !canDelete);
    }

    async function syncReqHistPopoverToolbar() {
        const panel = document.getElementById('reqWorkHistPanel');
        if (!panel || panel.classList.contains('hidden')) return;
        const m = modState(getState());
        if (!isRequisitionListWindow(m)) return;
        const { st, vesselId } = await vesselScope();
        const reqs = await TVC_Inventory.listRequisitions(vesselId);
        const selReq = m.selectedReqId ? reqs.find(r => r.id === m.selectedReqId) : null;
        const hasSel = !!selReq;
        const canRequisition = canCreateRequisition(st);
        const canConfirm = reqListAnyCheckedCanConfirm(m, reqs, st);
        const canApprove = reqListAnyCheckedCanApprove(m, reqs, st);
        const canDelete = reqListCanDeleteSelection(m, st);
        const canCloseOs = reqListAnyCloseOsEnabled(m, reqs, st);
        setSpareListToolbarBtnDisabled(panel, 'reqListReportConfirm', !canConfirm);
        setSpareListToolbarBtnDisabled(panel, 'reqListReportApprove', !canApprove);
        setSpareListToolbarBtnDisabled(panel, 'openCloseOsModal', !canCloseOs);
        setSpareListToolbarBtnDisabled(panel, 'reqListDelete', !canDelete);
    }

    function applyReqWorkMetaFromSession(req) {
        if (!req) return;
        const setVal = (id, val) => {
            const el = document.getElementById(id);
            if (el) el.value = val ?? '';
        };
        setVal('reqWorkReqNo', req.req_no || '');
        setVal('reqWorkDelFrom', fmtSpareDate(req.deliver_date_from || ''));
        setVal('reqWorkDelTo', fmtSpareDate(req.deliver_date_to || ''));
        setVal('reqWorkDelPort', req.deliver_port || '');
        setVal('reqWorkShipComments', req.ships_comments || '');
        setVal('reqWorkVendorComments', req.vendor_comments || '');
        setVal('reqWorkMadeOn', fmtSpareDate(req.made_on || ''));
        setVal('reqWorkAssessedOn', fmtSpareDate(req.assessed_on || ''));
        setVal('reqWorkAssessedBy', req.assessed_by || '');
        setVal('reqWorkOrderedOn', fmtSpareDate(req.ordered_on || ''));
        setVal('reqWorkOrderedBy', req.ordered_by || '');
        setVal('reqWorkReceivedOn', fmtSpareDate(reqListReceivedDate(req) || ''));
        setVal('reqWorkReceivedPort', reqListReceivedPort(req));
        setVal('reqWorkStatus', reqWorkMetaStatusLabel(req, getState()));
        setVal('reqWorkMadeBy', resolveSpareReportedBy(req, spareInventoryUser(getState())));
        const reqType = reqListTypeKind(req);
        document.querySelectorAll('input[name="reqWorkPriority"]').forEach(radio => {
            radio.checked = radio.value === reqType;
        });
        syncReqWorkMetaDatePickers(document.getElementById('spareReqWorkBody'));
    }

    function syncReqWorkApprovalSection(req) {
        const meta = document.querySelector('#spareReqWorkBody .spare-req-work-meta');
        if (!meta || !req || !isRequisitionListWindow(modState(getState()))) return;
        const st = getState();
        const m = modState(st);
        const html = renderReqWorkApprovalRow(req, {
            prefix: 'reqWork',
            department: req.department || st.department,
            listMode: true,
            listEditing: m.reqWorkListEditing,
        });
        const existing = meta.querySelector('.spare-req-approval-row');
        if (existing) existing.outerHTML = html;
        else {
            const legacy = meta.querySelector('.wr-maint-approval')?.closest('section');
            if (legacy) legacy.outerHTML = html;
            else meta.insertAdjacentHTML('afterbegin', html);
        }
    }

    function syncReqWorkListWindowHeadButtons() {
        const m = modState(getState());
        if (!isRequisitionListWindow(m)) return;
        const head = document.querySelector('#spareReqWorkBody .spare-req-work-head');
        if (!head) return;
        const hasDisplayedReq = reqWorkListHasDisplayedReq(m);
        const vesselPostOrder = reqWorkVesselOrderedOrReceivedView();
        const vesselRcvdOnly = reqWorkVesselReceivedRcvdOnlyEdit();
        const listViewLocked = !m.reqWorkListEditing && !vesselRcvdOnly;
        const completeDone = !!m.reqWorkCompleted;
        const saveDisabled = completeDone || listViewLocked;
        const modifyBtn = document.getElementById('reqWorkHeadModifyBtn');
        const newBtn = document.getElementById('reqWorkHeadNewBtn');
        const saveBtn = document.getElementById('reqWorkSaveBtn');
        if (modifyBtn) modifyBtn.disabled = !hasDisplayedReq || m.reqWorkListEditing || vesselPostOrder;
        if (newBtn) newBtn.disabled = m.reqWorkListEditing || !canCreateRequisition(getState()) || vesselPostOrder;
        if (saveBtn) saveBtn.disabled = saveDisabled;
        const cancelBtn = document.getElementById('reqWorkCancelBtn');
        if (cancelBtn) cancelBtn.disabled = !m.reqWorkListEditing;
        setSpareListToolbarBtnDisabled(head, 'reqWorkPrint', !hasDisplayedReq);
        setSpareListToolbarBtnDisabled(head, 'reqWorkDocPreview', !hasDisplayedReq);
        setSpareListToolbarBtnDisabled(head, 'reqWorkExportExcel', !hasDisplayedReq);
        syncReqWorkHqFlowBtns();
        const closeOsBtn = document.getElementById('reqWorkHeadCloseOsBtn');
        if (closeOsBtn) {
            const req = _reqWorkDraft;
            closeOsBtn.disabled = !(hasDisplayedReq && reqCloseOsButtonEnabled(req, getState()));
        }
        syncSparePartsRequisitionWindowTitle();
    }

    async function refreshReqWorkListWindowFromSession(st, opts = {}) {
        st = st || getState();
        const req = getReqWorkSession();
        if (!opts.skipReload && req?.vessel_id) await reloadSparesCache({ vesselId: req.vessel_id });
        if (!opts.skipLineMap) await syncReqLineMap();
        syncRequisitionDraftFromLines();
        syncReqWorkHeaderFocusFromLines(st);
        _reqWorkCachedList = filteredReqWorkSpares(st);
        refreshReqWorkListUi(opts);
        updateReqWorkSelectedBtn();
        updateReqWorkHeadStats();
        if (!opts.skipHeadLayout) {
            requestAnimationFrame(() => {
                syncReqWorkHeadLayout();
                if (!opts.soft) requestAnimationFrame(syncReqWorkHeadLayout);
            });
        }
    }

    function bindReqWorkHistListClicks() {
        const root = document.getElementById('spareReqWorkBody');
        if (!root || root._reqHistClickBound) return;
        root._reqHistClickBound = true;
        root.addEventListener('click', (e) => {
            const tr = e.target.closest('#reqWorkHistPanel tr[data-req-id]');
            if (!tr || e.target.closest('.spare-req-list-chk')) return;
            const id = tr.dataset.reqId;
            if (!id) return;
            e.preventDefault();
            e.stopPropagation();
            reqListSelectRow(id);
        });
        root.addEventListener('dblclick', (e) => {
            const tr = e.target.closest('#reqWorkHistPanel tr[data-req-id]');
            if (!tr || e.target.closest('.spare-req-list-chk')) return;
            const id = tr.dataset.reqId;
            if (!id) return;
            e.preventDefault();
            e.stopPropagation();
            reqListOpenRow(id);
        });
    }

    function bindSpareReqListModalClicks() {
        const modal = document.getElementById('spareReqListModal');
        if (!modal || modal._reqListClickBound) return;
        modal._reqListClickBound = true;
        modal.addEventListener('click', (e) => {
            const tr = e.target.closest('#spareReqListBody tr[data-req-id]');
            if (!tr || e.target.closest('.spare-req-list-chk')) return;
            const id = tr.dataset.reqId;
            if (!id) return;
            e.preventDefault();
            e.stopPropagation();
            reqListSelectRow(id);
        });
        modal.addEventListener('dblclick', (e) => {
            const tr = e.target.closest('#spareReqListBody tr[data-req-id]');
            if (!tr || e.target.closest('.spare-req-list-chk')) return;
            const id = tr.dataset.reqId;
            if (!id) return;
            e.preventDefault();
            e.stopPropagation();
            reqListOpenRow(id);
        });
    }

    async function reqListSelectRow(id) {
        try {
        const m = modState(getState());
        // 행 클릭은 하이라이트(선택)만 — 체크는 ㅁ를 직접 눌러야 함
        m.selectedReqId = id;
        if (isRequisitionListWindow(m)) {
            await loadRequisitionIntoListWindow(id);
        } else {
            syncReqListRowSelection(document.getElementById('spareReqListBody'));
            syncReqListRowSelection(document.getElementById('reqWorkHistPanel'));
            syncReqListRowSelection(document.getElementById('spareHistReqListHost'));
            await syncReqListModalToolbar();
            await syncHistoryReqListToolbar();
        }
        const scroll = document.getElementById('reqWorkHistListScroll')
            || document.getElementById('spareHistReqListScroll')
            || document.getElementById('spareReqListScroll');
        if (scroll && document.activeElement?.closest?.('.spare-req-list-filters') == null
            && document.activeElement?.tagName !== 'INPUT'
            && document.activeElement?.tagName !== 'TEXTAREA') {
            scroll.setAttribute('tabindex', '-1');
            try { scroll.focus({ preventScroll: true }); } catch (_) { /* ignore */ }
        }
        requestAnimationFrame(reqListScrollSelectedIntoView);
        } catch (e) {
            console.error('[reqListSelectRow]', e);
            await TVC_Dialog.alert(e?.message || 'Failed to load requisition.');
        }
    }

    async function reqListOpenRow(id) {
        const m = modState(getState());
        if (isRequisitionListWindow(m)) {
            await reqListSelectRow(id);
        } else if (isHistoryReqListVisible()) {
            await spareHistOpenRequisition(id);
            return;
        } else {
            const req = await TVC_Inventory.getRequisition(id);
            await reqListPickRow(id, req?.req_no || '');
        }
        if (_reqWorkHistOpen) {
            setReqWorkHistOpen(false);
            if (typeof TVC_ListFilters !== 'undefined') TVC_ListFilters.closePopover();
        }
    }

    async function reqListToggleRow(id, checked) {
        const m = modState(getState());
        const map = ensureReqListChecked(m);
        if (checked) {
            map[id] = true;
            m.selectedReqId = id;
        } else {
            delete map[id];
            if (m.selectedReqId === id) m.selectedReqId = null;
        }
        const modal = document.getElementById('spareReqListModal');
        const modalOpen = modal && !modal.classList.contains('hidden');
        const histOpen = _reqWorkHistOpen && document.getElementById('reqWorkHistPanel')
            && !document.getElementById('reqWorkHistPanel').classList.contains('hidden');
        if (modalOpen || histOpen) {
            const { vesselId } = await vesselScope();
            const allReqs = await TVC_Inventory.listRequisitions(vesselId);
            const reqs = filterReqList(allReqs, getState());
            updateReqListHeadCheckAll(reqs);
            syncReqListRowSelection(document.getElementById('spareReqListBody'));
            syncReqListRowSelection(document.getElementById('reqWorkHistPanel'));
            if (modalOpen) await syncReqListModalToolbar();
            if (histOpen) {
                if (checked && isRequisitionListWindow(m)) {
                    await loadRequisitionIntoListWindow(id);
                    syncReqWorkHqFlowBtns();
                    return;
                }
                await syncReqHistPopoverToolbar();
                syncReqWorkListWindowHeadButtons();
            }
            return;
        }
        await refreshReqListUi();
    }

    async function reqListToggleAll(checked) {
        const m = modState(getState());
        const { vesselId } = await vesselScope();
        const allReqs = await TVC_Inventory.listRequisitions(vesselId);
        const reqs = filterReqList(allReqs, getState());
        if (checked) {
            const map = ensureReqListChecked(m);
            reqs.forEach(r => {
                if (!_reqListXferExportKind || reqListCanXferExport(r)) map[r.id] = true;
            });
            if (!m.selectedReqId && reqs.length) m.selectedReqId = reqs[0].id;
        } else {
            m.reqListCheckedIds = {};
            m.selectedReqId = null;
        }
        await refreshReqListUi();
    }

    async function loadRequisitionIntoListWindow(reqId, opts = {}) {
        closeReqQuoteHeadPicks();
        const req = await TVC_Inventory.getRequisition(reqId);
        if (!req) {
            await TVC_Dialog.alert('Requisition not found.');
            return false;
        }
        const st0 = getState();
        const m0 = modState(st0);
        const uiMounted = isRequisitionListWindow(m0) && m0.reqWorkOpen && !!document.getElementById('reqWorkListScroll');
        const prevLayout = uiMounted ? (reqWorkUsesGroupedList(st0) ? 'grouped' : 'virtual') : null;
        const prevQuoteView = !!m0.reqWorkHqQuoteView;
        const prevEvalView = !!m0.reqWorkHqEvalView;

        _reqWorkDraft = {
            ...req,
            lines: normalizeReqLines(req.lines),
        };
        syncReqReportedByFromAuthor(_reqWorkDraft);
        _reqSheet.reqId = req.id;
        const st = getState();
        const m = modState(st);
        applyReqListSelection(m, req.id);
        m.reqWorkListEditing = !!opts.keepEditing;
        m.reqWorkPostSaveView = !!opts.postSaveView;
        if (!opts.keepFromHistory && !opts.postSaveView) m.reqWorkFromHistory = false;
        if (isReqListHqUser(st)) {
            applyReqWorkHqStageOnLoad(_reqWorkDraft, m);
        } else {
            applyReqWorkVesselStageOnLoad(_reqWorkDraft, m);
        }
        m.reqWorkShowSelectedOnly = true;
        m.reqWorkLastSavedId = req.id;
        modState(st).modalSpareGroupKey = null;
        st.treeSearch = '';
        clearReqWorkSearch(st);

        const listScroll = document.getElementById('reqWorkListScroll');
        const listScrollTop = listScroll?.scrollTop ?? 0;
        const histPanel = document.getElementById('reqWorkHistPanel');
        const histWasOpen = _reqWorkHistOpen && histPanel && !histPanel.classList.contains('hidden');
        const histScroll = document.getElementById('reqWorkHistListScroll');
        const histScrollTop = histScroll?.scrollTop ?? 0;
        const nextLayout = reqWorkUsesGroupedList(st) ? 'grouped' : 'virtual';
        const layoutChanged = !!prevLayout && prevLayout !== nextLayout;
        const viewModeChanged = prevQuoteView !== !!m.reqWorkHqQuoteView || prevEvalView !== !!m.reqWorkHqEvalView;
        const reportChrome = !!m.reqWorkFromHistory || !!m.reqWorkPostSaveView || !!opts.postSaveView || !!opts.keepFromHistory;
        const canPatchInPlace = uiMounted && !m.reqWorkListDocPreview && !opts.forceFullRender
            && !opts.skipRender
            && (opts.softNav || (!reportChrome && (histWasOpen || (!layoutChanged && !viewModeChanged))));

        if (!opts.softNav) await reloadSparesCache({ vesselId: req.vessel_id });

        if (canPatchInPlace) {
            const remountList = layoutChanged || viewModeChanged;
            await syncReqLineMap();
            await refreshReqWorkListWindowFromSession(st, {
                skipReload: true,
                skipLineMap: true,
                soft: !remountList,
                skipTree: true,
                skipScrollLock: true,
                skipHeadLayout: !remountList,
            });
            applyReqWorkMetaFromSession(_reqWorkDraft);
            syncReqWorkApprovalSection(_reqWorkDraft);
            applyReqWorkScrollLock(document.getElementById('spareReqWorkBody'));
            syncReqWorkMetaDatePickers(document.getElementById('spareReqWorkBody'));
            syncReqWorkFlowBtns();
            syncSparePartsRequisitionWindowTitle();
            syncReqWorkListWindowHeadButtons();
            syncReqListRowSelection(document.getElementById('spareReqListBody'));
            syncReqListRowSelection(document.getElementById('spareHistReqListHost'));
            if (histWasOpen) {
                syncReqListRowSelection(histPanel);
                await syncReqHistPopoverToolbar();
            }
            if (listScroll) listScroll.scrollTop = listScrollTop;
            if (histScroll) histScroll.scrollTop = histScrollTop;
            requestAnimationFrame(() => {
                if (histWasOpen) {
                    positionReqWorkHistPopover();
                    syncReqWorkHistHeadPad();
                }
                if (remountList) syncReqWorkHeadLayout();
            });
            return true;
        }

        syncRequisitionDraftFromLines();
        syncReqWorkHeaderFocusFromLines(st);
        _reqWorkCachedList = filteredReqWorkSpares(st);
        if (opts.skipRender) return true;
        await renderReqWorkModal();
        if (histScroll) histScroll.scrollTop = histScrollTop;
        return true;
    }

    async function clearRequisitionListWindowSelection() {
        closeReqQuoteHeadPicks();
        const st = getState();
        const m = modState(st);
        _reqWorkDraft = await buildBlankRequisitionDraft();
        _reqSheet.reqId = null;
        m.selectedReqId = null;
        m.reqWorkFocusedId = null;
        m.reqWorkListEditing = false;
        m.reqWorkPostSaveView = false;
        m.reqWorkFromHistory = false;
        m.reqWorkShowSelectedOnly = true;
        m.reqWorkLastSavedId = null;
        m.reqWorkHqQuoteView = false;
        m.reqWorkHqEvalView = false;
        m.reqWorkVesselFlowStage = 'report';
        m.reqWorkVesselFlowReqId = null;
        resetReqWorkQuoteState(_reqWorkDraft);
        st.requisitionDraft = [];
        clearReqListWindowAuditMeta(_reqWorkDraft);
        await syncReqLineMap();
        await renderReqWorkModal();
    }

    async function reqListPickRow(id, reqNo) {
        const m = modState(getState());
        m.selectedReqId = id;
        if (isRequisitionListWindow(m)) {
            await loadRequisitionIntoListWindow(id);
            syncReqWorkHqFlowBtns();
            return;
        }
        const histScroll = document.getElementById('reqWorkHistListScroll');
        const histScrollTop = histScroll?.scrollTop ?? 0;
        reqWorkSetReqNoInput(reqNo);
        syncReqListRowSelection(document.getElementById('reqWorkHistPanel'));
        if (histScroll) histScroll.scrollTop = histScrollTop;
    }

    function syncReqListHeadPad() {
        const scroll = document.getElementById('spareReqListScroll');
        const head = document.getElementById('spareReqListHead');
        if (!scroll || !head) return;
        const sb = scroll.offsetWidth - scroll.clientWidth;
        head.style.paddingRight = sb > 0 ? `${sb}px` : '';
    }

    function buildReqListRowsHtml(reqs, mode = 'modal') {
        if (!reqs.length) {
            return `<tr><td colspan="12" class="spare-req-list-empty">
                <span class="spare-req-list-empty-icon" aria-hidden="true">🧾</span>
                <p class="spare-req-list-empty-title">No requisitions yet</p>
                <p class="spare-req-list-empty-sub muted">${mode === 'pick'
                    ? 'Save a requisition to see it here.'
                    : 'Click <strong>New</strong> to create a requisition, or adjust Phase / Period / Search.'}</p>
            </td></tr>`;
        }
        const m = modState(getState());
        const st = getState();
        return reqs.map(r => {
            const rid = escAttr(r.id);
            const no = escAttr(r.req_no || '');
            const checked = reqListIsRowChecked(m, r.id);
            const sel = m.selectedReqId === r.id;
            const rowClick = mode === 'pick'
                ? `onclick="TVC_SpareMenu.reqListPickRow('${rid}', '${no}')" ondblclick="event.preventDefault(); TVC_SpareMenu.reqListOpenRow('${rid}')"`
                : `onclick="TVC_SpareMenu.reqListSelectRow('${rid}')" ondblclick="event.preventDefault(); TVC_SpareMenu.reqListOpenRow('${rid}')"`;
            const toggleFn = mode === 'pick' ? 'reqListPickToggleRow' : 'reqListToggleRow';
            const port = String(r.deliver_port || '').trim();
            const reported = reqListReportedDate(r);
            const received = reqListReceivedDate(r);
            const recvPort = reqListReceivedPort(r);
            const reqDate = reqListRequiredDateCell(r);
            const reqType = reqListTypeLabel(r);
            const reqTypeCls = reqListTypeCellClass(r);
            const spareGroup = reqListSpareGroupNo(r, st);
            const canSelect = !_reqListXferExportKind || reqListCanXferExport(r);
            const chkDisabled = canSelect ? '' : ` disabled title="${escAttr(reqListXferExportSelectDisabledTitle(r))}"`;
            return `<tr class="spare-req-list-row${sel ? ' sr-req-sel' : ''}${canSelect ? '' : ' menu-xfer-defect-row-disabled'}" data-req-id="${rid}" ${rowClick} style="cursor:pointer" title="Double-click to open">
                <td class="spare-req-list-chk" onclick="event.stopPropagation()">
                    <input type="checkbox" aria-label="Select requisition ${no}"
                        ${checked ? 'checked' : ''}${chkDisabled} onchange="TVC_SpareMenu.${toggleFn}('${rid}', this.checked)">
                </td>
                <td class="spare-req-list-type ${reqTypeCls}"${cellTitleAttr(reqType)}>${esc(reqType)}</td>
                <td class="spare-req-list-reqno"${cellTitleAttr(r.req_no)}>${esc(r.req_no || '—')}</td>
                <td class="spare-req-list-spare-group"${cellTitleAttr(spareGroup)}>${esc(spareGroup)}</td>
                <td class="spare-req-list-date spare-req-list-daterange"${cellTitleAttr(reqDate)}>${reqDate}</td>
                <td class="spare-req-list-port spare-req-list-req-port"${cellTitleAttr(port)}>${esc(r.deliver_port || '—')}</td>
                <td class="spare-req-list-date spare-req-list-submitted"${cellTitleAttr(reported)}>${reqListDateCell(reported)}</td>
                <td class="spare-req-list-status">${reqListStatusCell(r)}</td>
                <td class="spare-req-list-date spare-req-list-received"${cellTitleAttr(received)}>${reqListDateCell(received)}</td>
                <td class="spare-req-list-port spare-req-list-recv-port"${cellTitleAttr(recvPort)}>${esc(recvPort || '—')}</td>
                <td class="spare-req-list-os">${reqListOutstandingData(r)}</td>
                <td class="spare-req-list-total">${reqListTotalData(r)}</td>
            </tr>`;
        }).join('');
    }

    async function reqListPickToggleRow(id, checked) {
        const m = modState(getState());
        const map = ensureReqListChecked(m);
        if (checked) {
            map[id] = true;
            m.selectedReqId = id;
        } else {
            delete map[id];
            if (m.selectedReqId === id) m.selectedReqId = null;
        }
        if (isRequisitionListWindow(m)) {
            if (checked) {
                await loadRequisitionIntoListWindow(id);
                syncReqWorkHqFlowBtns();
                return;
            }
            const { vesselId } = await vesselScope();
            const reqs = await TVC_Inventory.listRequisitions(vesselId);
            updateReqListHeadCheckAll(reqs);
            syncReqListRowSelection(document.getElementById('reqWorkHistPanel'));
            await syncReqHistPopoverToolbar();
            syncReqWorkListWindowHeadButtons();
            return;
        }
        if (checked) {
            const req = await TVC_Inventory.getRequisition(id);
            if (req?.req_no) reqWorkSetReqNoInput(req.req_no);
        }
        await refreshReqWorkHistList();
    }

    function syncReqWorkHistHeadPad() {
        const scroll = document.getElementById('reqWorkHistListScroll');
        const head = document.getElementById('reqWorkHistListHead');
        if (!scroll || !head) return;
        const sb = scroll.offsetWidth - scroll.clientWidth;
        head.style.paddingRight = sb > 0 ? `${sb}px` : '';
    }

    async function renderReqListModal() {
        const body = document.getElementById('spareReqListBody');
        if (!body) return;
        const { st, vesselId } = await vesselScope();
        const m = modState(st);
        const canRequisition = canCreateRequisition(st);
        const allReqs = await TVC_Inventory.listRequisitions(vesselId);
        const phaseCounts = reqListPhaseCounts(allReqs, st);
        const reqs = filterReqList(allReqs, st);
        const reqRows = buildReqListRowsHtml(reqs, 'modal');
        const selId = m.selectedReqId;
        const selReq = selId ? allReqs.find(r => r.id === selId) : null;
        const hasSel = !!selReq;
        const canConfirm = reqListAnyCheckedCanConfirm(m, allReqs, st);
        const canApprove = reqListAnyCheckedCanApprove(m, allReqs, st);
        const canDelete = reqListCanDeleteSelection(m, st);
        const canCloseOs = reqListAnyCloseOsEnabled(m, allReqs, st);
        const exportXfer = _reqListXferExportKind;
        const exportableCount = exportXfer ? reqListCheckedExportableIds(m, allReqs).length : 0;
        const exportXferMeta = exportXfer ? reqListXferExportMeta(exportXfer) : null;
        const exportXferTitle = exportXferMeta?.title || '';
        const exportXferHint = exportXferMeta?.hint || '';

        const isHq = isReqListHqUser(st);
        const isAuthor = isSpareAuthorAccount(spareInventoryUser(st));
        const showConfirm = !isHq && !isAuthor;
        const showCloseOs = !isAuthor;
        const headToolbar = exportXfer
            ? `${spareListToolbarBtn('Export', 'TVC_SpareMenu.reqListExportToMaster()', !exportableCount, 'btn-green')}
            ${spareListToolbarBtn('← Back', 'TVC_SpareMenu.reqListXferExportBack()')}
            ${spareListToolbarBtn('Close', 'TVC_SpareMenu.closeReqListModal()')}
            <button type="button" class="modal-x" onclick="TVC_SpareMenu.closeReqListModal()" title="Close">×</button>`
            : `${spareListToolbarBtn('Detail Report', 'TVC_SpareMenu.reqListDetailReport()', !hasSel)}
            ${showConfirm ? spareListToolbarBtn('Report Confirm', 'TVC_SpareMenu.reqListReportConfirm()', !canConfirm, 'btn-green') : ''}
            ${isHq ? spareListToolbarBtn('Approve', 'TVC_SpareMenu.reqListReportApprove()', !canApprove, 'btn-green') : ''}
            ${showCloseOs ? spareListToolbarBtn('Close O/S', 'TVC_SpareMenu.openCloseOsModal()', !canCloseOs) : ''}
            <span class="orig-toolbar-sep" aria-hidden="true"></span>
            ${spareListToolbarBtn('New', 'TVC_SpareMenu.reqListNew()', !canRequisition, 'btn-green')}
            ${spareListToolbarBtn('Modify', 'TVC_SpareMenu.reqListModify()', !canRequisition || !hasSel)}
            ${spareListToolbarBtn('Delete', 'TVC_SpareMenu.reqListDelete()', !canDelete, 'btn-red')}
            <span class="orig-toolbar-sep" aria-hidden="true"></span>
            ${spareListToolbarBtn('Print', 'TVC_SpareMenu.reqListPrint()')}
            ${spareListToolbarBtn('Preview', 'TVC_SpareMenu.reqListDocPreview()')}
            ${spareListToolbarBtn('Excel', 'TVC_SpareMenu.reqListExportExcel()', !hasSel)}
            ${spareListToolbarBtn('Close', 'TVC_SpareMenu.closeReqListModal()')}
            <button type="button" class="modal-x" onclick="TVC_SpareMenu.closeReqListModal()" title="Close">×</button>`;

        body.innerHTML = `
        <div class="spare-req-list-wrap spare-req-list-main-wrap${exportXfer ? ' spare-req-list-xfer-export' : ''}">
          <div class="spare-req-list-head">
            <h3 class="spare-req-work-title">📋 Requisition List${exportXferTitle}
              <span class="muted spare-req-list-count">${reqs.length}${reqs.length !== allReqs.length ? ` / ${allReqs.length}` : ''} item(s)</span>
            </h3>
            <span class="spare-req-work-head-spacer"></span>
            ${headToolbar}
          </div>
          ${exportXfer ? `<p class="spare-sync-note muted spare-req-list-xfer-hint">${exportXferHint}</p>` : ''}
          ${exportXfer ? '' : reqListPhaseTabsHtml(m, phaseCounts, st)}
          ${renderReqListFiltersHtml(m)}
          <div class="spare-req-list-panel-wrap">
            <div class="panel spare-req-list-panel">
              <div class="spare-req-list-head-wrap" id="spareReqListHead">
                <table class="spare-data-table spare-req-list-table spare-req-list-head-table">${REQ_LIST_COLGROUP}${reqListTableHeadHtml()}</table>
              </div>
              <div class="spare-req-list-scroll" id="spareReqListScroll">
                <table class="spare-data-table spare-req-list-table spare-req-list-body-table">${REQ_LIST_COLGROUP}<tbody>${reqRows}</tbody></table>
              </div>
            </div>
          </div>
        </div>`;
        updateReqListHeadCheckAll(reqs);
        syncReqListFilterUi(st);
        syncSpareDateInputs(body);
        bindReqListKeyboard();
        bindSpareReqListModalClicks();
        TVC_App.bindSearchClearInput?.('reqListSearch');
        TVC_App.updateSearchClearBtn?.('reqListSearch');
        requestAnimationFrame(syncReqListHeadPad);
    }

    /* ── Consumption List window (consumeLogListMode) — mirrors Requisition List ── */

    function isConsumedLogWindow(m) {
        const s = m?.consumeLogListMode !== undefined ? m : modState(getState());
        return !!s.consumeOpen && !!s.consumeLogListMode;
    }

    function consumeLogHistPickBtnLabel(listMode) {
        return listMode ? 'Check History' : 'Consumption List';
    }

    function consumeReportWindowTitle(m) {
        const s = m?.consumeLogListEditing !== undefined ? m : modState(getState());
        if (s.consumeFromHistory) return 'Consumption Report';
        return s.consumeLogListEditing ? 'Consumption Report (Draft)' : 'Consumption Report';
    }

    function sparePartsRequisitionWindowTitle(m) {
        const s = m?.reqWorkListEditing !== undefined ? m : modState(getState());
        if (s.reqWorkFromHistory) return 'Spare Parts Requisition';
        return s.reqWorkListEditing ? 'Spare Parts Requisition (Draft)' : 'Spare Parts Requisition';
    }

    function syncConsumeReportWindowTitle() {
        const m = modState(getState());
        if (!isConsumedLogWindow(m)) return;
        const el = document.getElementById('consumeReportHeadTitle');
        if (el) el.textContent = consumeReportWindowTitle(m);
    }

    function syncSparePartsRequisitionWindowTitle() {
        const m = modState(getState());
        if (!isRequisitionListWindow(m) || !m.reqWorkOpen) return;
        const el = document.getElementById('reqWorkHeadTitle');
        if (el) el.textContent = sparePartsRequisitionWindowTitle(m);
    }

    function consumeLogListHasDisplayedLog(m) {
        const s = m?.consumeLogListMode !== undefined ? m : modState(getState());
        if (!isConsumedLogWindow(s)) return false;
        const draft = _consumeDraft;
        if (!draft) return false;
        if (draft.log_id) return true;
        const fileNo = String(draft.file_no || document.getElementById('consumeFileNo')?.value || '').trim();
        const hasLines = (draft.lines || []).length > 0;
        return !!(fileNo && hasLines);
    }

    function consumeLogFormLocked() {
        const m = modState(getState());
        if (m.consumePreview) return true;
        return isConsumedLogWindow(m) && !m.consumeLogListEditing;
    }

    function applyConsumeLogScrollLock(body) {
        const scroll = body?.querySelector?.('.spare-req-work-scroll');
        if (!scroll) return;
        const locked = consumeLogFormLocked();
        scroll.classList.toggle('is-req-locked', locked);
        const keepActive = new Set(['consumeLogHistBtn', 'consumeLogListFilterBtn']);
        scroll.querySelectorAll('input, select, textarea, button').forEach(el => {
            if (keepActive.has(el.id)) return;
            // Consumption List hist popover stays interactive (Period / Search / Filter / Confirm / Delete / Print / Preview)
            if (el.closest('#consumeLogHistPanel')) return;
            if (locked) el.setAttribute('disabled', 'disabled');
            else el.removeAttribute('disabled');
        });
        if (!locked) syncSpareToolbarUi();
    }

    function syncConsumeLogRowSelection(root) {
        const scope = root || document;
        const m = modState(getState());
        const selId = m.selectedConsumeLogId;
        scope.querySelectorAll('.spare-consume-log-body-table tbody tr[data-consume-log-id]').forEach(tr => {
            const id = tr.getAttribute('data-consume-log-id');
            tr.classList.toggle('sr-req-sel', id === selId);
            const cb = tr.querySelector('input.spare-row-chk');
            if (cb) cb.checked = consumeLogIsRowChecked(m, id);
        });
        const logs = [...scope.querySelectorAll('.spare-consume-log-body-table tbody tr[data-consume-log-id]')]
            .map(tr => ({ id: tr.getAttribute('data-consume-log-id') }))
            .filter(l => l.id);
        updateConsumeLogHeadCheckAll(logs);
    }

    function consumeLogHistScrollSelectedIntoView() {
        const scroll = document.getElementById('consumeLogHistListScroll')
            || document.getElementById('spareConsumeLogScroll');
        if (!scroll) return;
        const sel = scroll.querySelector('tr.sr-req-sel');
        if (sel) sel.scrollIntoView({ block: 'nearest' });
    }

    async function consumeLogMoveSelection(delta) {
        const { vesselId } = await vesselScope();
        const logs = filterConsumeLogs(await TVC_Inventory.listConsumeLogs(vesselId), getState());
        if (!logs.length) return;
        const m = modState(getState());
        let idx = logs.findIndex(l => l.id === m.selectedConsumeLogId);
        if (idx < 0) idx = delta > 0 ? -1 : 0;
        const next = Math.max(0, Math.min(logs.length - 1, idx + delta));
        await consumeLogSelectRow(logs[next].id);
        requestAnimationFrame(consumeLogHistScrollSelectedIntoView);
    }

    function onConsumeLogHistKeydown(e) {
        if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return;
        const t = e.target;
        if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' || t.isContentEditable)) {
            // Period / Search typing — do not steal arrows
            if (t.closest('#consumeLogHistPanel') || t.closest('#spareConsumeLogBody')) {
                if (t.classList.contains('search-input')
                    || t.classList.contains('act-period-input')
                    || t.classList.contains('tvc-date-input')) return;
            }
        }
        const histOpen = _consumeLogHistOpen && document.getElementById('consumeLogHistPanel')
            && !document.getElementById('consumeLogHistPanel').classList.contains('hidden');
        const standalone = document.getElementById('spareConsumeLogModal')
            && !document.getElementById('spareConsumeLogModal').classList.contains('hidden');
        if (!histOpen && !standalone) return;
        if (!isConsumedLogWindow() && !standalone) return;
        e.preventDefault();
        e.stopPropagation();
        consumeLogMoveSelection(e.key === 'ArrowDown' ? 1 : -1);
    }

    function bindConsumeLogHistKeyboard() {
        const modal = document.getElementById('spareConsumeModal');
        if (modal && !modal._consumeLogHistKeyBound) {
            modal._consumeLogHistKeyBound = true;
            modal.addEventListener('keydown', onConsumeLogHistKeydown, true);
        }
        const standalone = document.getElementById('spareConsumeLogModal');
        if (standalone && !standalone._consumeLogHistKeyBound) {
            standalone._consumeLogHistKeyBound = true;
            standalone.addEventListener('keydown', onConsumeLogHistKeydown, true);
        }
    }

    function syncConsumeLogListWindowHeadButtons() {
        const m = modState(getState());
        if (!isConsumedLogWindow(m)) return;
        const head = document.querySelector('#spareConsumeBody .spare-req-work-head');
        if (!head) return;
        const hasDisplayed = consumeLogListHasDisplayedLog(m);
        const modifyBtn = document.getElementById('consumeLogHeadModifyBtn');
        const newBtn = document.getElementById('consumeLogHeadNewBtn');
        const saveBtn = document.getElementById('consumeLogSaveBtn');
        const cancelBtn = document.getElementById('consumeLogCancelBtn');
        if (modifyBtn) modifyBtn.disabled = !hasDisplayed || m.consumeLogListEditing;
        if (newBtn) newBtn.disabled = m.consumeLogListEditing || !canCreateConsume(getState());
        if (saveBtn) saveBtn.disabled = !m.consumeLogListEditing;
        if (cancelBtn) cancelBtn.disabled = !m.consumeLogListEditing;
        setSpareListToolbarBtnDisabled(head, 'consumeLogPrintPreview', !hasDisplayed);
        setSpareListToolbarBtnDisabled(head, 'consumeLogWindowDocPreview', !hasDisplayed);
        syncConsumeReportWindowTitle();
    }

    function clearConsumeLogUiState(m) {
        m.consumeLogCheckedIds = {};
        m.selectedConsumeLogId = null;
    }

    function ensureConsumeLogChecked(m) {
        if (!m.consumeLogCheckedIds) m.consumeLogCheckedIds = {};
        return m.consumeLogCheckedIds;
    }

    function consumeLogIsRowChecked(m, id) {
        return !!m.consumeLogCheckedIds?.[id];
    }

    function consumeLogTotalData(log) {
        return Number(log.line_count) || (log.lines || []).length || 0;
    }

    function consumeLogDateCell(val) {
        return esc(val || '—');
    }

    function consumeLogComments(log) {
        return String(log.ships_comments || '').trim();
    }

    function consumeLogDateInPeriod(dateStr, from, to) {
        if (!from && !to) return true;
        const d = String(dateStr || '').slice(0, 10);
        if (!d) return false;
        if (from && d < from) return false;
        if (to && d > to) return false;
        return true;
    }

    function consumeLogStatusLabel(log) {
        if (!log) return SPARE_LIST_STATUS.DRAFT;
        if (log.approved_by || log.approved_at || spareListStatus(log) === SPARE_LIST_STATUS.APPROVED) {
            return SPARE_LIST_STATUS.APPROVED;
        }
        if (log.sync_status === 'SYNCED') return 'Submitted';
        const s = spareListStatus(log);
        return s || SPARE_LIST_STATUS.DRAFT;
    }

    function consumeLogStatusCell(log) {
        const label = consumeLogStatusLabel(log);
        const cls = label.replace(/\s+/g, '');
        return `<span class="sr-status cl-st-${escAttr(cls)}">${esc(label)}</span>`;
    }

    function consumeLogMatchSearch(log, q) {
        if (!q) return true;
        const type = consumeLogTypeMarker(log);
        const jobHay = consumeLogJobItems(log).map(i =>
            [i.job_code, i.sort1, i.sort2, i.job_detail].join(' ')
        ).join(' ');
        const hay = [
            type.letter, type.title, log.file_no,
            log.job_code, log.sort1, log.sort2, log.job_detail, jobHay,
            log.made_on, log.made_by, consumeLogStatusLabel(log),
            log.pms_group_no, consumeLogComments(log),
        ].join(' ').toLowerCase();
        return hay.includes(q);
    }

    function resolveConsumeLogGroupKey(log, st = getState()) {
        if (!log) return null;
        const direct = String(log.pms_group_key || log.spare_group_key || '').trim();
        if (direct) return direct;
        const jobCode = consumeLogJobItems(log).map(i => i.job_code).find(Boolean)
            || String(log.job_code || '').trim();
        if (jobCode) {
            const job = findJobByCode(st, jobCode, {
                department: log.department || st.department,
                groupKey: log.pms_group_key || log.spare_group_key,
                group: log.pms_group_no,
            });
            if (job) return `${job.department || ''}|${String(job.group || '').trim()}`;
        }
        const pmsNo = String(log.pms_group_no || '').trim();
        if (pmsNo && st.idx?.groupNodes) {
            const short = pmsNo.replace(/\s+/g, '');
            const node = st.idx.groupNodes.find(n =>
                String(n.label || '').replace(/\s+/g, '') === short
                || String(n.key || '').includes(short)
            );
            if (node) return node.key;
        }
        return null;
    }

    function getConsumeLogListFilters() {
        const m = modState(getState());
        return {
            groupKeys: [...(m.consumeLogFilterGroupKeys || [])],
            type: m.consumeLogFilterType || 'all',
        };
    }

    function setConsumeLogListFilters(patch = {}) {
        const m = modState(getState());
        if (patch.groupKeys !== undefined) {
            m.consumeLogFilterGroupKeys = Array.isArray(patch.groupKeys) ? [...patch.groupKeys] : [];
        }
        if (patch.type !== undefined) {
            m.consumeLogFilterType = String(patch.type || 'all').toLowerCase() || 'all';
        }
        if (typeof TVC_ListFilters !== 'undefined') TVC_ListFilters.syncBtn('consumeLog');
        refreshConsumeLogListUi();
    }

    function filterConsumeLogs(logs, st) {
        const m = modState(st);
        const from = m.consumeLogPeriodFrom || '';
        const to = m.consumeLogPeriodTo || '';
        const q = String(m.consumeLogSearch || '').trim().toLowerCase();
        const type = String(m.consumeLogFilterType || 'all').toLowerCase();
        const groupKeys = m.consumeLogFilterGroupKeys || [];
        return (logs || []).filter(log => {
            if (!consumeLogDateInPeriod(log.made_on || log.consumed_date, from, to)) return false;
            if (!consumeLogMatchSearch(log, q)) return false;
            if (type && type !== 'all') {
                const letter = String(consumeLogTypeMarker(log).letter || '').toLowerCase();
                if (letter !== type) return false;
            }
            if (groupKeys.length) {
                const gk = resolveConsumeLogGroupKey(log, st);
                if (!gk || !groupKeys.includes(gk)) return false;
            }
            return true;
        });
    }

    function consumeLogIsSubmitted(log) {
        if (!log) return false;
        if (log.approved_by || log.approved_at) return false;
        if (log.sync_status === 'SYNCED') return true;
        return consumeLogStatusLabel(log) === 'Submitted';
    }

    function canModifyConsumeHistory(st, log) {
        if (!log || !canCreateConsume(st)) return false;
        const status = spareListStatus(log);
        if (status === SPARE_LIST_STATUS.APPROVED || log.approved_by || log.approved_at) {
            return isReqListHqUser(st);
        }
        if (isReqListHqUser(st)) return true;
        return !consumeLogIsSubmitted(log);
    }

    function consumeHistModifyDisabledTitle(st, log) {
        if (canModifyConsumeHistory(st, log)) return '';
        if (!canCreateConsume(st)) return 'No permission';
        if (spareListStatus(log) === SPARE_LIST_STATUS.APPROVED || log?.approved_by || log?.approved_at) {
            return 'Approved — modify not available';
        }
        if (consumeLogIsSubmitted(log)) return 'Submitted — modify not available';
        return 'Modify not available';
    }

    function consumeLogCanConfirm(st, log) {
        if (!log) return false;
        const user = spareInventoryUser(st);
        return consumeLogStatusLabel(log) === SPARE_LIST_STATUS.REPORTED
            && !!user && TVC_RBAC.canConfirmDepartment(user, log.department || st.department);
    }

    function consumeLogCanApprove(st, log) {
        if (!log) return false;
        const user = spareInventoryUser(st);
        if (!user || !TVC_RBAC.canApproveHqReport(user)) return false;
        const status = spareListStatus(log);
        const isConfirmed = status === SPARE_LIST_STATUS.CONFIRMED || status === SPARE_LIST_STATUS.APPROVED
            || !!(log?.confirmed_by || log?.confirmed_at);
        const isApproved = status === SPARE_LIST_STATUS.APPROVED || !!(log?.approved_by || log?.approved_at);
        if (isApproved) return false;
        // HQ Superintendent 작성분: Reported만 있어도 Approve 가능
        if (TVC_RBAC.canHqDirectApprove(user, log) || TVC_RBAC.canApproveHqReport(user)) {
            return status !== SPARE_LIST_STATUS.DRAFT;
        }
        return isConfirmed;
    }

    function consumeLogCheckedConfirmableIds(m, allLogs, st) {
        const map = m.consumeLogCheckedIds || {};
        return Object.keys(map).filter(id => {
            if (!map[id]) return false;
            const log = allLogs.find(l => l.id === id);
            return consumeLogCanConfirm(st, log);
        });
    }

    function consumeLogCheckedApprovableIds(m, allLogs, st) {
        const map = m.consumeLogCheckedIds || {};
        return Object.keys(map).filter(id => {
            if (!map[id]) return false;
            const log = allLogs.find(l => l.id === id);
            return consumeLogCanApprove(st, log);
        });
    }

    function consumeLogAnyCheckedCanConfirm(m, allLogs, st) {
        return consumeLogCheckedConfirmableIds(m, allLogs, st).length > 0;
    }

    function consumeLogAnyCheckedCanApprove(m, allLogs, st) {
        return consumeLogCheckedApprovableIds(m, allLogs, st).length > 0;
    }

    function consumeLogCanDeleteSelection(m, st) {
        if (!canCreateConsume(st)) return false;
        const ids = Object.keys(m.consumeLogCheckedIds || {}).filter(k => m.consumeLogCheckedIds[k]);
        if (!ids.length && m.selectedConsumeLogId) ids.push(m.selectedConsumeLogId);
        if (!ids.length) return false;
        const logs = st.consumeLogs || [];
        return ids.some(id => {
            const log = logs.find(l => String(l.id) === String(id));
            if (!log) return true;
            if (log.approved_by || log.approved_at) return false;
            if (consumeLogIsSubmitted(log)) return false;
            return true;
        });
    }

    function syncConsumeLogFilterUi(st) {
        const m = modState(st);
        const fromEl = document.getElementById('consumeLogPeriodFrom');
        const toEl = document.getElementById('consumeLogPeriodTo');
        const searchEl = document.getElementById('consumeLogSearch');
        const filterEl = document.getElementById('consumeLogPeriodFilter');
        if (fromEl) fromEl.value = m.consumeLogPeriodFrom || '';
        if (toEl) toEl.value = m.consumeLogPeriodTo || '';
        if (searchEl) searchEl.value = m.consumeLogSearch || '';
        if (filterEl) filterEl.classList.toggle('active', !!(m.consumeLogPeriodFrom || m.consumeLogPeriodTo));
        if (typeof TVC_ListFilters !== 'undefined') TVC_ListFilters.syncBtn('consumeLog');
    }

    function renderConsumeLogFiltersHtml(m) {
        return `<div class="hist-toolbar hist-toolbar-filters spare-consume-log-filters list-filter-stack">
                <div class="filter-bar list-filter-period-row">
                    <div id="consumeLogPeriodFilter" class="act-period-filter" title="Filter by Reported Date">
                        <span class="act-period-label">Period</span>
                        <input type="text" id="consumeLogPeriodFrom" class="act-period-input tvc-date-input" placeholder="YYYY-MM-DD" autocomplete="off" aria-label="Period from"
                            value="${escAttr(m.consumeLogPeriodFrom || '')}" onchange="TVC_SpareMenu.consumeLogSetPeriod()">
                        <span class="act-period-sep">~</span>
                        <input type="text" id="consumeLogPeriodTo" class="act-period-input tvc-date-input" placeholder="YYYY-MM-DD" autocomplete="off" aria-label="Period to"
                            value="${escAttr(m.consumeLogPeriodTo || '')}" onchange="TVC_SpareMenu.consumeLogSetPeriod()">
                        <div class="list-filter-wrap">
                            <button type="button" id="consumeLogListFilterBtn" class="btn btn-sm list-filter-btn" onclick="TVC_ListFilters.toggle('consumeLog', event)">Filter</button>
                        </div>
                    </div>
                    <button type="button" class="btn btn-sm act-period-clear" onclick="TVC_SpareMenu.consumeLogClearPeriodAndFilters()">Clear</button>
                </div>
                <div class="filter-bar list-filter-search-row">
                    <div class="search-field-wrap">
                        <input class="search-input" id="consumeLogSearch" placeholder="Search File No / JOB CODE / SORT / STATUS…"
                            value="${esc(m.consumeLogSearch || '')}" oninput="TVC_SpareMenu.consumeLogSetSearch(this.value)">
                        <button type="button" class="search-clear-btn${m.consumeLogSearch ? '' : ' hidden'}" title="Clear search" aria-label="Clear search"
                            onclick="TVC_SpareMenu.consumeLogClearSearch()">×</button>
                    </div>
                </div>
            </div>`;
    }

    function consumeLogSetPeriod() {
        const st = getState();
        const m = modState(st);
        m.consumeLogPeriodFrom = document.getElementById('consumeLogPeriodFrom')?.value || '';
        m.consumeLogPeriodTo = document.getElementById('consumeLogPeriodTo')?.value || '';
        refreshConsumeLogListUi();
    }

    function consumeLogClearPeriod() {
        consumeLogClearPeriodAndFilters();
    }

    function consumeLogClearPeriodAndFilters() {
        const st = getState();
        const m = modState(st);
        m.consumeLogPeriodFrom = '';
        m.consumeLogPeriodTo = '';
        m.consumeLogFilterGroupKeys = [];
        m.consumeLogFilterType = 'all';
        TVC_ListFilters?.refreshOpenPopover?.();
        refreshConsumeLogListUi();
    }

    function consumeLogSetSearch(v) {
        modState(getState()).consumeLogSearch = v;
        clearTimeout(_consumeLogSearchT);
        _consumeLogSearchT = setTimeout(() => refreshConsumeLogListUi(), 150);
    }

    function consumeLogClearSearch() {
        modState(getState()).consumeLogSearch = '';
        const el = document.getElementById('consumeLogSearch');
        if (el) el.value = '';
        refreshConsumeLogListUi();
    }

    let _consumeLogSearchT = null;

    function resolveConsumeDraftWorkReportId(draft, st) {
        if (!draft) return '';
        if (draft.work_report_id) return draft.work_report_id;
        const logId = draft.log_id;
        if (!logId) return '';
        const rep = (st.reports || []).find(r => r.consume_log_id === logId);
        return rep?.id || '';
    }

    function consumeDraftFromLog(log) {
        const jobItems = consumeLogJobItems(log);
        const page1 = resolveConsumeLogPage1Meta(log);
        const draft = {
            log_id: log.id,
            work_report_id: log.work_report_id || '',
            defect_case_id: log.defect_case_id || '',
            source: log.source || '',
            consumed_date: log.consumed_date || '',
            made_on: log.made_on || '',
            made_by: log.made_by || '',
            created_by_username: log.created_by_username || '',
            file_no: page1.file_no || '',
            voy_no: page1.voy_no || '',
            place: page1.place || '',
            spare_group_key: log.pms_group_key || '',
            spare_group_label: log.pms_group_no || '',
            job_code: log.job_code || '',
            sort1: log.sort1 || '',
            sort2: log.sort2 || '',
            job_detail: log.job_detail || '',
            job_items: jobItems,
            ships_comments: log.ships_comments || '',
            list_status: log.list_status || spareListStatus(log),
            department: log.department || '',
            sync_status: log.sync_status || 'LOCAL',
            confirmed_by: log.confirmed_by || '',
            confirmed_at: log.confirmed_at || '',
            approved_by: log.approved_by || '',
            approved_at: log.approved_at || '',
            lines: (log.lines || []).map(l => ({
                spare_part_id: l.spare_part_id,
                part_no: l.part_no || '',
                name: l.name || '',
                qty_consumed: Number(l.qty ?? l.qty_consumed) || 0,
            })),
        };
        syncConsumeDraftJobSummary(draft);
        return draft;
    }

    function consumeLogPreviewSource(draft) {
        ensureConsumeJobItems(draft);
        syncConsumeDraftJobSummary(draft);
        return {
            consumed_date: draft.consumed_date,
            made_on: draft.made_on,
            made_by: draft.made_by,
            pms_group_no: draft.spare_group_label || '',
            job_code: draft.job_code,
            sort1: draft.sort1,
            sort2: draft.sort2,
            job_detail: draft.job_detail,
            job_items: draft.job_items.map(i => ({ ...i })),
            ships_comments: draft.ships_comments,
            lines: (draft.lines || []).map(l => ({
                part_no: l.part_no,
                name: l.name,
                qty: Number(l.qty_consumed) || 0,
            })),
        };
    }

    function applyConsumeLogSelection(m, id) {
        // 행 클릭/로드는 하이라이트(선택)만 — 체크는 ㅁ를 직접 눌러야 함
        if (!id) return;
        m.selectedConsumeLogId = id;
    }

    function updateConsumeLogHeadCheckAll(logs) {
        document.querySelectorAll('.spare-consume-log-head-chk').forEach(el => {
            if (!logs.length) {
                el.checked = false;
                el.indeterminate = false;
                return;
            }
            const m = modState(getState());
            let n = 0;
            logs.forEach(l => { if (consumeLogIsRowChecked(m, l.id)) n++; });
            el.checked = n === logs.length;
            el.indeterminate = n > 0 && n < logs.length;
        });
    }

    function syncConsumeLogHeadPad() {
        const scroll = document.getElementById('spareConsumeLogScroll');
        const head = document.getElementById('spareConsumeLogHead');
        if (!scroll || !head) return;
        const sb = scroll.offsetWidth - scroll.clientWidth;
        head.style.paddingRight = sb > 0 ? `${sb}px` : '';
    }

    function syncConsumeLogHistHeadPad() {
        const scroll = document.getElementById('consumeLogHistListScroll');
        const head = document.getElementById('consumeLogHistListHead');
        if (!scroll || !head) return;
        const sb = scroll.offsetWidth - scroll.clientWidth;
        head.style.paddingRight = sb > 0 ? `${sb}px` : '';
    }

    /** Soft-refresh list rows/count/toolbar only — keep Period/Search inputs (focus & typing). */
    async function patchConsumeLogListUi() {
        const { st, vesselId } = await vesselScope();
        const m = modState(st);
        const allLogs = await TVC_Inventory.listConsumeLogs(vesselId);
        const logs = filterConsumeLogs(allLogs, st);
        const rows = buildConsumeLogRowsHtml(logs);
        const countLabel = `${logs.length}${logs.length !== allLogs.length ? ` / ${allLogs.length}` : ''} item(s)`;

        document.querySelectorAll('#consumeLogHistPanel .spare-req-list-count, #spareConsumeLogBody .spare-req-list-count')
            .forEach(el => { el.textContent = countLabel; });

        const histTbody = document.querySelector('#consumeLogHistListScroll .spare-consume-log-body-table tbody');
        const modalTbody = document.querySelector('#spareConsumeLogScroll .spare-consume-log-body-table tbody');
        if (histTbody) histTbody.innerHTML = rows;
        if (modalTbody) modalTbody.innerHTML = rows;

        updateConsumeLogHeadCheckAll(logs);

        const isHq = isReqListHqUser(st);
        const canConfirm = consumeLogAnyCheckedCanConfirm(m, allLogs, st);
        const canApprove = isHq && consumeLogAnyCheckedCanApprove(m, allLogs, st);
        const canDelete = consumeLogCanDeleteSelection(m, st);
        const toolbarRoots = [
            document.getElementById('consumeLogHistPanel'),
            document.getElementById('spareConsumeLogBody'),
        ].filter(Boolean);
        toolbarRoots.forEach(root => {
            setSpareListToolbarBtnDisabled(root, 'consumeLogReportConfirm', !canConfirm);
            if (isHq) setSpareListToolbarBtnDisabled(root, 'consumeLogReportApprove', !canApprove);
            setSpareListToolbarBtnDisabled(root, 'consumeLogDelete', !canDelete);
        });

        document.querySelectorAll('#consumeLogSearch').forEach(searchEl => {
            const clearBtn = searchEl.parentElement?.querySelector('.search-clear-btn');
            if (clearBtn) clearBtn.classList.toggle('hidden', !m.consumeLogSearch);
        });
        const periodEl = document.getElementById('consumeLogPeriodFilter');
        if (periodEl) periodEl.classList.toggle('active', !!(m.consumeLogPeriodFrom || m.consumeLogPeriodTo));
        if (typeof TVC_ListFilters !== 'undefined') TVC_ListFilters.syncBtn('consumeLog');
    }

    function consumeLogListCanSoftPatch() {
        if (_consumeLogHistOpen && document.querySelector('#consumeLogHistListScroll .spare-consume-log-body-table tbody')) {
            return true;
        }
        const modal = document.getElementById('spareConsumeLogModal');
        return !!(modal && !modal.classList.contains('hidden')
            && document.querySelector('#spareConsumeLogScroll .spare-consume-log-body-table tbody'));
    }

    async function refreshConsumeLogListUi(opts = {}) {
        if (!opts.full && consumeLogListCanSoftPatch()) {
            await patchConsumeLogListUi();
            return;
        }
        if (_consumeLogHistOpen) {
            await refreshConsumeLogHistList();
            return;
        }
        const modal = document.getElementById('spareConsumeLogModal');
        if (modal && !modal.classList.contains('hidden')) {
            await renderConsumeLogModal();
        }
    }

    async function syncConsumeLogHistPopoverToolbar() {
        const panel = document.getElementById('consumeLogHistPanel');
        if (!panel || panel.classList.contains('hidden')) return;
        const m = modState(getState());
        if (!isConsumedLogWindow(m)) return;
        const { st, vesselId } = await vesselScope();
        const allLogs = await TVC_Inventory.listConsumeLogs(vesselId);
        const isHq = isReqListHqUser(st);
        const canConfirm = consumeLogAnyCheckedCanConfirm(m, allLogs, st);
        const canApprove = isHq && consumeLogAnyCheckedCanApprove(m, allLogs, st);
        const canDelete = consumeLogCanDeleteSelection(m, st);
        setSpareListToolbarBtnDisabled(panel, 'consumeLogReportConfirm', !canConfirm);
        if (isHq) setSpareListToolbarBtnDisabled(panel, 'consumeLogReportApprove', !canApprove);
        setSpareListToolbarBtnDisabled(panel, 'consumeLogDelete', !canDelete);
    }

    function consumeHistMetaAnchor() {
        const btn = document.getElementById('consumeLogHistBtn');
        return btn?.closest('.spare-consume-meta-form')
            || document.querySelector('#spareConsumeBody .spare-consume-meta-form');
    }

    function attachConsumeHistPanelToAnchor(histPanel) {
        if (!histPanel) return;
        const anchor = consumeHistMetaAnchor();
        if (!anchor) return;
        const placeholder = anchor.querySelector('#consumeLogHistPanel');
        if (placeholder && placeholder !== histPanel) {
            placeholder.replaceWith(histPanel);
        } else if (!anchor.contains(histPanel)) {
            anchor.appendChild(histPanel);
        }
    }

    function positionConsumeLogHistPopover() {
        const btn = document.getElementById('consumeLogHistBtn');
        const panel = document.getElementById('consumeLogHistPanel');
        const meta = consumeHistMetaAnchor();
        if (!btn || !panel || !meta || panel.classList.contains('hidden')) return;
        if (!meta.contains(panel)) attachConsumeHistPanelToAnchor(panel);
        const top = btn.getBoundingClientRect().bottom - meta.getBoundingClientRect().top + 6;
        panel.style.top = `${Math.max(top, 0)}px`;
    }

    function setConsumeLogHistOpen(open, opts = {}) {
        _consumeLogHistOpen = open;
        if (!open || opts.reset) clearConsumeLogUiState(modState(getState()));
        const panel = document.getElementById('consumeLogHistPanel');
        const btn = document.getElementById('consumeLogHistBtn');
        const meta = consumeHistMetaAnchor();
        if (panel && meta) attachConsumeHistPanelToAnchor(panel);
        if (panel) {
            panel.classList.toggle('hidden', !open);
            panel.setAttribute('aria-hidden', open ? 'false' : 'true');
        }
        if (btn) btn.classList.toggle('is-open', open);
        syncConsumeHistOpenClasses(open);
        if (open) {
            requestAnimationFrame(() => {
                positionConsumeLogHistPopover();
                syncConsumeLogHistHeadPad();
            });
        }
    }

    async function refreshConsumeLogHistList() {
        const panel = document.getElementById('consumeLogHistPanel');
        if (!panel) return;
        const { st, vesselId } = await vesselScope();
        const m = modState(st);
        const listMode = isConsumedLogWindow(m);
        const allLogs = await TVC_Inventory.listConsumeLogs(vesselId);
        const logs = filterConsumeLogs(allLogs, st);
        const rows = buildConsumeLogRowsHtml(logs);
        const isHq = isReqListHqUser(st);
        const isAuthor = isSpareAuthorAccount(spareInventoryUser(st));
        const showConfirm = !isHq && !isAuthor;
        const canConfirm = consumeLogAnyCheckedCanConfirm(m, allLogs, st);
        const canApprove = isHq && consumeLogAnyCheckedCanApprove(m, allLogs, st);
        const canDelete = consumeLogCanDeleteSelection(m, st);
        const countLabel = `${logs.length}${logs.length !== allLogs.length ? ` / ${allLogs.length}` : ''} item(s)`;
        let headHtml;
        if (listMode) {
            const approveBtn = isHq
                ? consumeLogToolbarBtn('Approve', 'TVC_SpareMenu.consumeLogReportApprove()', !canApprove, 'btn-green')
                : '';
            headHtml = `<div class="spare-req-list-head spare-req-hist-popover-head spare-consume-log-toolbar">
                <h3 class="spare-req-work-title">📋 Consumption List
                    <span class="muted spare-req-list-count">${countLabel}</span>
                </h3>
                <span class="spare-req-work-head-spacer"></span>
                ${showConfirm ? consumeLogToolbarBtn('Confirm', 'TVC_SpareMenu.consumeLogReportConfirm()', !canConfirm, 'btn-green') : ''}
                ${approveBtn}
                ${consumeLogToolbarBtn('Delete', 'TVC_SpareMenu.consumeLogDelete()', !canDelete, 'btn-red')}
                <span class="orig-toolbar-sep" aria-hidden="true"></span>
                ${consumeLogToolbarBtn('Print', 'TVC_SpareMenu.consumeLogPrint()')}
                ${consumeLogToolbarBtn('Preview', 'TVC_SpareMenu.consumeLogDocPreview()')}
                <button type="button" class="modal-x" onclick="TVC_SpareMenu.toggleConsumeLogHistList()" title="Close">×</button>
            </div>`;
        } else {
            headHtml = `<div class="spare-req-hist-popover-head">${consumeLogHistPickBtnLabel(false)}
                <span class="muted spare-req-list-count">${countLabel}</span>
                <button type="button" class="modal-x" onclick="TVC_SpareMenu.toggleConsumeLogHistList()" title="Close">×</button></div>`;
        }
        const hintText = listMode
            ? 'Click a row to load · Double-click to open and close this list.'
            : 'Click a row to fill File No. · Double-click to apply and close.';
        panel.innerHTML = `${headHtml}
            ${renderConsumeLogFiltersHtml(m)}
            <div class="spare-req-list-panel-wrap spare-req-hist-panel-wrap">
                <div class="panel spare-req-list-panel spare-consume-log-panel spare-req-hist-list-panel">
                  <div class="spare-req-list-head-wrap" id="consumeLogHistListHead">
                    <table class="spare-data-table spare-req-list-table spare-consume-log-table spare-req-list-head-table spare-consume-log-head-table">${CONSUME_LOG_COLGROUP}${consumeLogTableHeadHtml('consumeLogHistHeadChkAll')}</table>
                  </div>
                  <div class="spare-req-hist-list-scroll" id="consumeLogHistListScroll">
                    <table class="spare-data-table spare-req-list-table spare-consume-log-table spare-req-list-body-table spare-consume-log-body-table">${CONSUME_LOG_COLGROUP}<tbody>${rows}</tbody></table>
                  </div>
                </div>
            </div>
            <p class="spare-req-list-hint spare-req-hist-hint muted">${hintText}</p>`;
        updateConsumeLogHeadCheckAll(logs);
        syncConsumeLogFilterUi(st);
        syncSpareDateInputs(panel);
        bindConsumeLogHistKeyboard();
        TVC_App.bindSearchClearInput?.('consumeLogSearch');
        TVC_App.updateSearchClearBtn?.('consumeLogSearch');
        positionConsumeLogHistPopover();
        requestAnimationFrame(() => {
            positionConsumeLogHistPopover();
            syncConsumeLogHistHeadPad();
            consumeLogHistScrollSelectedIntoView();
        });
    }

    function consumeSetFileNoFromLog(log) {
        if (!log) return;
        const page1 = resolveConsumeLogPage1Meta(log);
        const draft = getConsumeSession();
        if (draft) {
            draft.file_no = page1.file_no || '';
            draft.voy_no = page1.voy_no || '';
            draft.place = page1.place || '';
        }
        const setVal = (id, val) => {
            const el = document.getElementById(id);
            if (el) el.value = val || '';
        };
        setVal('consumeFileNo', page1.file_no);
        setVal('consumeVoyNo', page1.voy_no);
        setVal('consumePlace', page1.place);
        captureConsumeMeta();
    }

    async function toggleConsumeLogHistList() {
        if (_consumeLogHistOpen) {
            setConsumeLogHistOpen(false);
            return;
        }
        setConsumeLogHistOpen(true, { reset: true });
        await refreshConsumeLogHistList();
    }

    function consumeMetaLayoutKey(draft, st = getState()) {
        const m = modState(st);
        const ro = !!m.consumePreview || (m.consumeLogListMode && !m.consumeLogListEditing);
        return isConsumeWrPage2View(draft, ro, m.consumeLogListMode, st) ? 'wr-page2' : 'standard';
    }

    function canPatchConsumeMetaInPlace(draft, st = getState()) {
        const root = document.querySelector('#spareConsumeBody .consume-report-meta');
        if (!root || !draft) return false;
        return root.dataset.consumeMetaLayout === consumeMetaLayoutKey(draft, st);
    }

    function syncConsumeHistOpenClasses(open = _consumeLogHistOpen) {
        const wrap = document.querySelector('#spareConsumeBody .spare-req-work-wrap');
        if (wrap) wrap.classList.toggle('is-consume-hist-open', open);
        const metaRoot = document.querySelector('#spareConsumeBody .consume-report-meta');
        if (metaRoot) metaRoot.classList.toggle('is-consume-hist-open', open);
        const meta = consumeHistMetaAnchor();
        if (meta) meta.classList.toggle('is-consume-hist-open', open);
    }

    function syncConsumeLogApprovalSection(draft) {
        const root = document.querySelector('#spareConsumeBody .consume-report-meta')
            || document.querySelector('#spareConsumeBody .spare-req-work-scroll');
        if (!root || !draft || !isConsumedLogWindow(modState(getState()))) return;
        const st = getState();
        const m = modState(st);
        const html = renderConsumeLogApprovalRow(draft, {
            prefix: 'consumeLog',
            department: st.department,
            listMode: true,
            listEditing: m.consumeLogListEditing,
        });
        const existing = root.querySelector('.wr-maint-approval');
        if (existing) existing.outerHTML = html;
        else root.insertAdjacentHTML('afterbegin', html);
    }

    function applyConsumeWrPage2MetaFromSession(draft, st = getState()) {
        const reportedByVal = resolveSpareReportedBy(draft, spareInventoryUser(st));
        const meta = buildConsumeWrPage2Meta(draft, reportedByVal, st);
        const pmsLabel = meta.pmsGroupNo ? safeTreeLabel(meta.pmsGroupNo) : '—';
        const pmsInp = document.querySelector('#spareConsumeBody .consume-report-meta .wr-maint-grid .wr-maint-span-all input.wr-ro');
        if (pmsInp) pmsInp.value = pmsLabel;
        setPage2JobContext({
            items: meta.jobItems,
            groupKey: meta.groupKey || '',
            readonly: true,
            allowAdd: false,
            containerId: 'consumePage2JobRows',
        });
        const container = page2JobRowsEl('consumePage2JobRows');
        if (container) {
            container.innerHTML = renderPage2JobRowsInner(getPage2JobContext(), {
                readonly: true,
                allowAdd: false,
                maintStyle: true,
            });
        }
        const comments = document.getElementById('wrSpareShipComments');
        if (comments) comments.value = meta.spareShipComments || '';
    }

    function applyConsumeMetaFromSession(draft, st = getState()) {
        if (!draft) return;
        const setVal = (id, val) => {
            const el = document.getElementById(id);
            if (el) el.value = val ?? '';
        };
        setVal('consumeFileNo', draft.file_no || '');
        setVal('consumeVoyNo', draft.voy_no || '');
        setVal('consumePlace', draft.place || '');
        setVal('consumeDate', fmtSpareDate(draft.consumed_date || ''));
        setVal('consumeMadeOn', fmtSpareDate(draft.made_on || ''));
        setVal('consumeMadeBy', resolveSpareReportedBy(draft, spareInventoryUser(st)));
        setVal('consumeShipComments', draft.ships_comments || '');
        syncConsumeLogApprovalSection(draft);
        if (consumeMetaLayoutKey(draft, st) === 'wr-page2') {
            applyConsumeWrPage2MetaFromSession(draft, st);
        } else {
            const pickText = document.getElementById('consumeGroupPickText');
            if (pickText) {
                const label = draft.spare_group_label ? safeTreeLabel(draft.spare_group_label) : '— Select PMS Group —';
                pickText.textContent = label;
            }
            renderConsumeJobRowsSection();
        }
        const scroll = document.querySelector('#spareConsumeBody .spare-req-work-scroll');
        if (scroll) syncSpareDateInputs(scroll);
    }

    /** Consumption List 행 전환 — layout 변경 시에만 meta DOM 교체 */
    function syncConsumeMetaPanelFromSession(draft, st) {
        const scroll = document.querySelector('#spareConsumeBody .spare-req-work-scroll');
        if (!scroll || !draft) return;
        const m = modState(st);
        const listMode = !!m.consumeLogListMode;
        const metaHtml = renderConsumeMetaHtml(draft, {
            readonly: m.consumePreview,
            department: st.department,
            listMode,
        });
        const layout = scroll.querySelector('.spare-consume-work-layout')
            || scroll.querySelector('.plan-layout');
        if (!layout) return;

        const histPanel = document.getElementById('consumeLogHistPanel');
        const histWasOpen = _consumeLogHistOpen && histPanel
            && !histPanel.classList.contains('hidden');

        while (scroll.firstChild && scroll.firstChild !== layout) {
            scroll.removeChild(scroll.firstChild);
        }
        layout.insertAdjacentHTML('beforebegin', metaHtml);

        if (histWasOpen && histPanel) {
            attachConsumeHistPanelToAnchor(histPanel);
            histPanel.classList.remove('hidden');
            histPanel.setAttribute('aria-hidden', 'false');
            syncConsumeHistOpenClasses(true);
            positionConsumeLogHistPopover();
        }
        syncSpareDateInputs(scroll);
    }

    function syncConsumeLogHistRowHighlight(st) {
        const panel = document.getElementById('consumeLogHistPanel');
        if (!panel) return;
        const m = modState(st);
        panel.querySelectorAll('.spare-consume-log-row[data-consume-log-id]').forEach(row => {
            row.classList.toggle('sr-req-sel', row.dataset.consumeLogId === m.selectedConsumeLogId);
        });
        syncConsumeLogRowSelection(panel);
    }

    async function refreshConsumeListWindowFromSession(st) {
        const m = modState(st);
        const allCanon = (st.spares || []).map(canon);
        const prevCount = _consumeCachedList.length;
        _consumeCachedList = filteredConsumeSpares(st);
        if (m.consumeShowSelectedOnly) {
            _consumeCachedList = _consumeCachedList.filter(s => consumeRowChecked(s));
        }
        const scroll = document.getElementById('consumeListScroll');
        const canRefresh = !!(vlConsume && scroll?.querySelector('.vl-inner')
            && prevCount > 0 && _consumeCachedList.length > 0);
        const block = document.getElementById('consumeEditBlock');
        if (block) {
            block.innerHTML = renderConsumeGroupHeaderHtml(st);
        }
        if (canRefresh) {
            vlConsume.refresh();
            requestAnimationFrame(syncConsumeHeadLayout);
        } else {
            mountConsumeVirtualList();
        }
        updateConsumeHeadStats();
        updateConsumeHeadCheckAll();
        const countEl = document.getElementById('consumeCount');
        if (countEl) {
            countEl.textContent = m.consumeShowSelectedOnly
                ? consumeSelectedCountLabel(st, _consumeCachedList.length)
                : `${_consumeCachedList.length} / ${allCanon.length}`;
        }
        updateConsumeSelectedBtn();
        syncSpareItemHistoryBtns();
        initConsumeListView(st);
    }

    function canSoftPatchConsumeHistNav(st = getState()) {
        const m = modState(st);
        if (!m.consumeFromHistory || !m.consumeOpen || m.consumeLogListEditing) return false;
        const modal = document.getElementById('spareConsumeModal');
        if (!modal || modal.classList.contains('hidden')) return false;
        return !!document.querySelector('#spareConsumeBody .spare-consume-draft-wrap');
    }

    function captureConsumeHistScroll() {
        const modal = document.getElementById('spareConsumeModal');
        const workScroll = document.querySelector('#spareConsumeBody .spare-req-work-scroll');
        const listScroll = document.getElementById('consumeListScroll');
        return {
            modal: modal?.scrollTop ?? 0,
            modalBox: modal?.querySelector('.modal-box')?.scrollTop ?? 0,
            work: workScroll?.scrollTop ?? 0,
            list: listScroll?.scrollTop ?? 0,
        };
    }

    function restoreConsumeHistScroll(saved) {
        if (!saved) return;
        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                const modal = document.getElementById('spareConsumeModal');
                const workScroll = document.querySelector('#spareConsumeBody .spare-req-work-scroll');
                const listScroll = document.getElementById('consumeListScroll');
                if (modal) modal.scrollTop = saved.modal;
                const box = modal?.querySelector('.modal-box');
                if (box) box.scrollTop = saved.modalBox;
                if (workScroll) workScroll.scrollTop = saved.work;
                if (listScroll) listScroll.scrollTop = saved.list;
            });
        });
    }

    function renderConsumeHistFooterHtml(st, m, draft) {
        const listEditing = !!m.consumeLogListEditing;
        const navBtns = TVC_App?.histNavButtonsHtml
            ? TVC_App.histNavButtonsHtml('TVC_App.navWorkHistoryEntry(-1)', 'TVC_App.navWorkHistoryEntry(1)')
            : '';
        const isHqUser = isReqListHqUser(st);
        const histActionLabel = isHqUser ? 'Approve' : 'Confirm';
        const consumeAppr = consumeLogApprovalState(draft, st.department, { listMode: true, listEditing });
        const histActionOk = !listEditing && (isHqUser
            ? consumeAppr.canApproveNow
            : consumeAppr.canConfirmNow);
        const histActionBtn = `<button type="button" class="btn" onclick="TVC_SpareMenu.consumeHistConfirmOrApprove()"${histActionOk ? '' : ' disabled'}>${histActionLabel}</button>`;
        const printBtns = `${histActionBtn}<button type="button" class="btn" onclick="TVC_SpareMenu.consumeLogPrintReport()">Print</button>
                <button type="button" class="btn" onclick="TVC_SpareMenu.consumeLogPrintPreview()">Preview</button>`;
        const closeBtn = `<button type="button" class="btn" onclick="TVC_SpareMenu.closeConsumeModal()">Close</button>`;
        const canModifyLog = canModifyConsumeHistory(st, draft);
        const modifyTitle = consumeHistModifyDisabledTitle(st, draft);
        const centerBtns = listEditing
            ? `<button type="button" id="consumeLogSaveBtn" class="btn btn-green" onclick="TVC_SpareMenu.saveConsume()">Save</button>
                    <button type="button" id="consumeLogCancelBtn" class="btn" onclick="TVC_SpareMenu.consumeLogCancelEdit()">Cancel</button>`
            : `<button type="button" class="btn" onclick="TVC_SpareMenu.consumeLogEnterListEdit()"${canModifyLog ? '' : ' disabled'}${modifyTitle ? ` title="${escAttr(modifyTitle)}"` : ''}>Modify</button>`;
        return `<div class="modal-actions wr-actions wr-actions-split spare-consume-draft-actions">
                <div class="wr-modal-actions-left">${navBtns}</div>
                <div class="wr-modal-actions-center">${centerBtns}</div>
                <div class="wr-modal-actions-right">${printBtns}${closeBtn}</div>
               </div>`;
    }

    function syncConsumeHistFooterFromSession(st = getState()) {
        const m = modState(st);
        const draft = getConsumeSession();
        const footer = document.querySelector('#spareConsumeBody .spare-consume-draft-actions');
        if (!footer || !draft) return;
        footer.outerHTML = renderConsumeHistFooterHtml(st, m, draft);
    }

    async function patchConsumeHistNavFromSession(st, opts = {}) {
        const draft = getConsumeSession();
        if (!draft) return;
        const scrollSaved = opts.preserveScroll ? captureConsumeHistScroll() : null;
        if (canPatchConsumeMetaInPlace(draft, st)) {
            applyConsumeMetaFromSession(draft, st);
        } else {
            syncConsumeMetaPanelFromSession(draft, st);
        }
        await refreshConsumeListWindowFromSession(st);
        syncConsumeHistFooterFromSession(st);
        syncConsumeReportWindowTitle();
        applyConsumeLogScrollLock(document.getElementById('spareConsumeBody'));
        if (scrollSaved) restoreConsumeHistScroll(scrollSaved);
        requestAnimationFrame(() => {
            syncConsumeHeadLayout();
            syncConsumeListModalSizing();
        });
    }

    async function loadConsumeLogIntoListWindow(logId, opts = {}) {
        closeAllConsumeMetaPicks();
        const log = await TVC_Inventory.getConsumeLog(logId);
        if (!log) {
            await TVC_Dialog.alert('Consumption log not found.');
            return false;
        }
        _consumeDraft = consumeDraftFromLog(log);
        syncConsumeLineMap();
        let st = getState();
        await hydrateConsumeDraftFromLinkedReport(_consumeDraft, log, st);
        st = getState();
        const m = modState(st);
        applyConsumeLogSelection(m, log.id);
        m.consumeLogListEditing = false;
        m.consumePostSaveView = !!opts.postSaveView;
        if (!opts.keepFromHistory && !opts.postSaveView) m.consumeFromHistory = false;
        m.consumeShowSelectedOnly = true;
        m.consumeLastSavedLogId = log.id;
        modState(st).modalSpareGroupKey = null;
        st.treeSearch = '';
        m.partNo = '';
        m.description = '';
        st.spareSearch = '';
        const softHistNav = !!(opts.softHistNav
            || (opts.keepFromHistory && opts.skipRender && canSoftPatchConsumeHistNav(st)));
        if (softHistNav) {
            await patchConsumeHistNavFromSession(st, { preserveScroll: opts.preserveScroll !== false });
            return true;
        }
        const preserveHist = opts.preserveHistPopover !== false
            && _consumeLogHistOpen
            && isConsumedLogWindow(m);
        if (preserveHist) {
            const histScroll = document.getElementById('consumeLogHistListScroll');
            const histScrollTop = histScroll?.scrollTop ?? 0;
            if (canPatchConsumeMetaInPlace(_consumeDraft, st)) {
                applyConsumeMetaFromSession(_consumeDraft, st);
            } else {
                syncConsumeMetaPanelFromSession(_consumeDraft, st);
            }
            updateConsumeHeadStats();
            syncConsumeLogListWindowHeadButtons();
            await refreshConsumeListWindowFromSession(st);
            syncConsumeLogHistRowHighlight(st);
            await syncConsumeLogHistPopoverToolbar();
            applyConsumeLogScrollLock(document.getElementById('spareConsumeBody'));
            if (histScroll) histScroll.scrollTop = histScrollTop;
            requestAnimationFrame(() => {
                syncConsumeHeadLayout();
                positionConsumeLogHistPopover();
            });
            return true;
        }
        if (opts.skipRender) return true;
        await renderConsumeModal();
        return true;
    }

    async function startConsumeLogListSession(opts = {}) {
        const { st } = await vesselScope();
        const user = spareInventoryUser(st);
        if (!user) await TVC_Dialog.alert('Sign in required.');
        _consumeDraft = newConsumeDraft(st, user);
        syncConsumeLineMap();
        const m = modState(st);
        m.consumeOpen = true;
        m.consumeLogListMode = true;
        m.consumeLogListEditing = false;
        m.consumePostSaveView = false;
        m.consumeFromHistory = false;
        m.consumeEditMode = false;
        m.consumePreview = false;
        m.consumeLastSavedLogId = null;
        m.consumeFocusedId = null;
        m.consumeShowSelectedOnly = true;
        m.consumeTreeOpen = false;
        m.partNo = '';
        m.description = '';
        st.spareSearch = '';
        st.treeSearch = '';
        modState(st).modalSpareGroupKey = null;
        _consumeGroupPickSearch = '';
        _consumeJobPickSearch = '';
        closeAllConsumeMetaPicks();
        if (opts.openSelectList) setConsumeLogHistOpen(true, { reset: true });
        else setConsumeLogHistOpen(false);
        await renderConsumeModal();
        showSpicsModal('spareConsumeModal');
        syncConsumeListModalSizing();
    }

    /** Consumption List 창에서 로그 열기 (조회 또는 편집) */
    async function openConsumeLogInListWindow(logId, { editing = false } = {}) {
        const st = getState();
        if (window.TVC_App?.switchTab && st.currentTab !== 'spare' && !stayOnSpareHistoryTab(st)) {
            TVC_App.switchTab('spare');
        }
        const m = modState(st);
        if (!isConsumedLogWindow(m) || !m.consumeOpen) {
            await startConsumeLogListSession({ openSelectList: false });
        }
        await loadConsumeLogIntoListWindow(logId);
        m.consumeLogListEditing = !!editing;
        m.consumePostSaveView = false;
        m.consumeFromHistory = false;
        m.consumeEditMode = false;
        m.consumePreview = false;
        await renderConsumeModal();
        return true;
    }

    function isConsumeHistoryView() {
        const m = modState(getState());
        return !!m.consumeFromHistory && !!m.consumeOpen;
    }

    function currentConsumeHistLogId() {
        if (!isConsumeHistoryView()) return null;
        const m = modState(getState());
        return _consumeDraft?.log_id || m.selectedConsumeLogId || m.consumeLastSavedLogId || null;
    }

    async function openConsumeFromPmsHistory(logId, opts = {}) {
        if (!logId) return false;
        const modal = document.getElementById('spareConsumeModal');
        const softNav = !!(opts.skipModalToggle && modal && !modal.classList.contains('hidden')
            && document.querySelector('#spareConsumeBody .spare-consume-draft-wrap'));
        const preserveScroll = !!(opts.preserveScroll || opts.swapOpts?.preserveScroll);
        const st = getState();
        const m = modState(st);
        m.consumeOpen = true;
        m.consumeLogListMode = true;
        m.consumeFromHistory = true;
        m.consumePostSaveView = false;
        m.consumePreview = false;
        m.consumeEditMode = false;
        m.consumeLogListEditing = false;
        setConsumeLogHistOpen(false);
        const loaded = await loadConsumeLogIntoListWindow(logId, {
            preserveHistPopover: false,
            keepFromHistory: true,
            skipRender: true,
            softHistNav: softNav,
            preserveScroll: softNav && preserveScroll,
        });
        if (!loaded) return false;
        m.consumeFromHistory = true;
        m.consumeLogListEditing = !!opts.edit;
        m.consumePostSaveView = false;
        if (softNav) {
            modal?.classList.remove('hidden');
            syncConsumeListModalSizing();
            return true;
        }
        await renderConsumeModal();
        if (opts.skipModalToggle) {
            modal?.classList.remove('hidden');
        } else if (opts.swapHide && typeof TVC_App?.swapHistoryModals === 'function') {
            TVC_App.swapHistoryModals('spareConsumeModal', opts.swapHide, opts.swapOpts || {});
        } else {
            showSpicsModal('spareConsumeModal');
        }
        syncConsumeListModalSizing();
        return true;
    }

    async function consumeLogEnterListEdit() {
        const st = getState();
        const m = modState(st);
        if (!isConsumedLogWindow(m)) return;
        if (!canCreateConsume(st)) {
            await TVC_Dialog.alert('You do not have permission to modify consumption logs.');
            return;
        }
        if (!consumeLogListHasDisplayedLog(m)) {
            await TVC_Dialog.alert('Select a consumption log from the list first.');
        }
        const displayed = getConsumeSession();
        if (m.consumeFromHistory && !canModifyConsumeHistory(st, displayed)) {
            await TVC_Dialog.alert(consumeHistModifyDisabledTitle(st, displayed) || 'Cannot modify this consumption log.');
            return;
        }
        if (m.consumeLogListEditing) return;
        m.consumeLogListEditing = true;
        m.consumePostSaveView = false;
        await renderConsumeModal();
    }

    async function consumeLogCancelEdit() {
        const st = getState();
        const m = modState(st);
        if (!isConsumedLogWindow(m) || !m.consumeLogListEditing) return;
        closeAllConsumeMetaPicks();
        const logId = _consumeDraft?.log_id || null;
        m.consumeLogListEditing = false;
        m.consumePostSaveView = false;
        m.consumeEditMode = false;
        setConsumeLogHistOpen(false);
        if (m.consumeFromHistory && logId) {
            await loadConsumeLogIntoListWindow(logId, { preserveHistPopover: false, keepFromHistory: true });
            m.consumeFromHistory = true;
            await renderConsumeModal();
            return;
        }
        if (logId) {
            await loadConsumeLogIntoListWindow(logId, { preserveHistPopover: false });
            return;
        }
        await closeConsumeModal({ skipConfirm: true });
    }

    function buildConsumeLogRowsHtml(logs) {
        if (!logs.length) {
            return `<tr><td colspan="9" class="spare-req-list-empty">
                <span class="spare-req-list-empty-icon" aria-hidden="true">📋</span>
                <p class="spare-req-list-empty-title">No consumed logs yet</p>
                <p class="spare-req-list-empty-sub muted">Click <strong>New</strong> to create a consumption record, or adjust Period / Search.</p>
            </td></tr>`;
        }
        const m = modState(getState());
        return logs.map(log => {
            const lid = escAttr(log.id);
            const checked = consumeLogIsRowChecked(m, log.id);
            const sel = m.selectedConsumeLogId === log.id;
            const jobItems = consumeLogJobItems(log);
            const page1 = resolveConsumeLogPage1Meta(log);
            const fileNo = page1.file_no;
            const jobText = jobItems.map(i => i.job_code).filter(Boolean).join(', ') || String(log.job_code || '').trim();
            const sort1Text = jobItems.length > 1
                ? jobItems.map(i => i.sort1).filter(Boolean).join(' · ')
                : String(jobItems[0]?.sort1 || log.sort1 || '').trim();
            const sort2Text = jobItems.length > 1
                ? jobItems.map(i => i.sort2).filter(Boolean).join(' · ')
                : String(jobItems[0]?.sort2 || log.sort2 || '').trim();
            const reported = log.made_on || log.consumed_date || '';
            return `<tr class="spare-consume-log-row${sel ? ' sr-req-sel' : ''}" data-consume-log-id="${lid}"
                onclick="TVC_SpareMenu.consumeLogSelectRow('${lid}')"
                ondblclick="event.preventDefault(); TVC_SpareMenu.consumeLogOpenRow('${lid}')"
                style="cursor:pointer" title="Double-click to open">
                <td class="spare-consume-log-chk" onclick="event.stopPropagation()">
                    <input type="checkbox" class="spare-row-chk"${checked ? ' checked' : ''} aria-label="Select consumption log"
                        onclick="event.stopPropagation()"
                        onchange="TVC_SpareMenu.consumeLogToggleRow('${lid}', this.checked)">
                </td>
                ${consumeLogTypeCell(log)}
                <td class="spare-consume-log-file"${cellTitleAttr(fileNo)}>${esc(fileNo || '—')}</td>
                <td class="spare-consume-log-job"${cellTitleAttr(jobText)}>${jobText ? `<strong>${esc(jobText)}</strong>` : '—'}</td>
                <td class="spare-consume-log-sort"${cellTitleAttr(sort1Text)}>${esc(sort1Text || '—')}</td>
                <td class="spare-consume-log-sort"${cellTitleAttr(sort2Text)}>${esc(sort2Text || '—')}</td>
                <td class="spare-consume-log-reported"${cellTitleAttr(reported)}>${consumeLogDateCell(reported)}</td>
                <td class="spare-consume-log-status">${consumeLogStatusCell(log)}</td>
                <td class="spare-consume-log-total">${consumeLogTotalData(log)}</td>
            </tr>`;
        }).join('');
    }

    function consumeLogToolbarBtn(label, onclick, disabled = false, cls = '') {
        return spareListToolbarBtn(label, onclick, disabled, cls);
    }

    async function renderConsumeLogModal() {
        const body = document.getElementById('spareConsumeLogBody');
        if (!body) return;
        const { st, vesselId } = await vesselScope();
        const m = modState(st);
        const allLogs = await TVC_Inventory.listConsumeLogs(vesselId);
        const logs = filterConsumeLogs(allLogs, st);
        const rows = buildConsumeLogRowsHtml(logs);
        const isHq = isReqListHqUser(st);
        const isAuthor = isSpareAuthorAccount(spareInventoryUser(st));
        const showConfirm = !isHq && !isAuthor;
        const canConfirm = consumeLogAnyCheckedCanConfirm(m, allLogs, st);
        const canApprove = isHq && consumeLogAnyCheckedCanApprove(m, allLogs, st);
        const canDelete = consumeLogCanDeleteSelection(m, st);
        const approveBtn = isHq
            ? consumeLogToolbarBtn('Approve', 'TVC_SpareMenu.consumeLogReportApprove()', !canApprove, 'btn-green')
            : '';

        body.innerHTML = `
            <div class="spare-req-list-wrap spare-consume-log-wrap">
              <div class="spare-req-list-head spare-consume-log-toolbar">
                <h3 class="spare-req-work-title">Consumption List
                  <span class="muted spare-req-list-count">${logs.length}${logs.length !== allLogs.length ? ` / ${allLogs.length}` : ''} item(s)</span>
                </h3>
                <span class="spare-req-work-head-spacer"></span>
                ${showConfirm ? consumeLogToolbarBtn('Confirm', 'TVC_SpareMenu.consumeLogReportConfirm()', !canConfirm, 'btn-green') : ''}
                ${approveBtn}
                ${consumeLogToolbarBtn('Delete', 'TVC_SpareMenu.consumeLogDelete()', !canDelete, 'btn-red')}
                <span class="orig-toolbar-sep" aria-hidden="true"></span>
                ${consumeLogToolbarBtn('Print', 'TVC_SpareMenu.consumeLogPrint()')}
                ${consumeLogToolbarBtn('Preview', 'TVC_SpareMenu.consumeLogDocPreview()')}
                ${consumeLogToolbarBtn('Close', 'TVC_SpareMenu.closeConsumeLogModal()')}
                <button type="button" class="modal-x" onclick="TVC_SpareMenu.closeConsumeLogModal()" title="Close">×</button>
              </div>
              ${renderConsumeLogFiltersHtml(m)}
              <div class="spare-req-list-panel-wrap">
                <div class="panel spare-req-list-panel spare-consume-log-panel">
                  <div class="spare-req-list-head-wrap" id="spareConsumeLogHead">
                    <table class="spare-data-table spare-req-list-table spare-consume-log-table spare-req-list-head-table spare-consume-log-head-table">${CONSUME_LOG_COLGROUP}${consumeLogTableHeadHtml()}</table>
                  </div>
                  <div class="spare-req-list-scroll" id="spareConsumeLogScroll">
                    <table class="spare-data-table spare-req-list-table spare-consume-log-table spare-req-list-body-table spare-consume-log-body-table">${CONSUME_LOG_COLGROUP}<tbody>${rows}</tbody></table>
                  </div>
                </div>
              </div>
            </div>`;
        updateConsumeLogHeadCheckAll(logs);
        syncConsumeLogFilterUi(st);
        syncSpareDateInputs(body);
        bindConsumeLogHistKeyboard();
        TVC_App.bindSearchClearInput?.('consumeLogSearch');
        TVC_App.updateSearchClearBtn?.('consumeLogSearch');
        requestAnimationFrame(syncConsumeLogHeadPad);
    }

    function openConsumeLogModal(opts = {}) {
        const m = modState(getState());
        clearConsumeLogUiState(m);
        if (opts.selectId) applyConsumeLogSelection(m, opts.selectId);
        renderConsumeLogModal().then(() => {
            showSpicsModal('spareConsumeLogModal');
            bindConsumeLogHistKeyboard();
        });
    }

    function closeConsumeLogModal() {
        clearConsumeLogUiState(modState(getState()));
        if (typeof TVC_ListFilters !== 'undefined') TVC_ListFilters.closePopover();
        closeSpicsModal('spareConsumeLogModal');
    }

    function viewConsumedLog() {
        openConsumedLogWindow();
    }

    async function openConsumedLogWindow() {
        clearConsumeLogUiState(modState(getState()));
        await startConsumeLogListSession({ openSelectList: true });
    }

    async function consumeLogSelectRow(id) {
        const m = modState(getState());
        // 행 클릭은 하이라이트(선택)만 — 체크는 ㅁ를 직접 눌러야 함
        m.selectedConsumeLogId = id;
        if (isConsumedLogWindow(m)) {
            await loadConsumeLogIntoListWindow(id, { preserveHistPopover: true });
        } else {
            const log = await TVC_Inventory.getConsumeLog(id);
            consumeSetFileNoFromLog(log);
            await refreshConsumeLogListUi();
        }
        const scroll = document.getElementById('consumeLogHistListScroll')
            || document.getElementById('spareConsumeLogScroll');
        if (scroll && document.activeElement?.closest?.('.spare-consume-log-filters') == null
            && document.activeElement?.tagName !== 'INPUT'
            && document.activeElement?.tagName !== 'TEXTAREA') {
            scroll.setAttribute('tabindex', '-1');
            try { scroll.focus({ preventScroll: true }); } catch (_) { /* ignore */ }
        }
        requestAnimationFrame(consumeLogHistScrollSelectedIntoView);
    }

    async function consumeLogOpenRow(id) {
        await consumeLogSelectRow(id);
        if (_consumeLogHistOpen) setConsumeLogHistOpen(false);
    }

    async function consumeLogToggleRow(id, checked) {
        const m = modState(getState());
        const map = ensureConsumeLogChecked(m);
        if (checked) {
            map[id] = true;
            m.selectedConsumeLogId = id;
        } else {
            delete map[id];
            if (m.selectedConsumeLogId === id) m.selectedConsumeLogId = null;
        }
        await refreshConsumeLogListUi();
    }

    async function consumeLogToggleAll(checked) {
        const m = modState(getState());
        const { vesselId } = await vesselScope();
        const allLogs = await TVC_Inventory.listConsumeLogs(vesselId);
        const logs = filterConsumeLogs(allLogs, getState());
        if (checked) {
            const map = ensureConsumeLogChecked(m);
            logs.forEach(l => { map[l.id] = true; });
            if (!m.selectedConsumeLogId && logs.length) m.selectedConsumeLogId = logs[0].id;
        } else {
            m.consumeLogCheckedIds = {};
            m.selectedConsumeLogId = null;
        }
        await refreshConsumeLogListUi();
    }

    async function consumeLogReportConfirm() {
        const st = getState();
        const m = modState(st);
        const { vesselId } = await vesselScope();
        const allLogs = await TVC_Inventory.listConsumeLogs(vesselId);
        const checkedIds = Object.keys(m.consumeLogCheckedIds || {}).filter(k => m.consumeLogCheckedIds[k]);
        const idsToConfirm = checkedIds.length
            ? consumeLogCheckedConfirmableIds(m, allLogs, st)
            : [];
        if (!idsToConfirm.length) {
            if (checkedIds.length) {
                await TVC_Dialog.alert('None of the selected logs can be confirmed. Only Reported logs can be confirmed, and you need Chief Engineer, Chief Officer, Captain, or HQ Superintendent permission.');
            } else {
                await TVC_Dialog.alert('Select one or more Reported logs to confirm.');
            }
            return;
        }
        const loadedId = _consumeDraft?.log_id || m.selectedConsumeLogId;
        let confirmed = 0;
        let needReload = false;
        for (const id of idsToConfirm) {
            const log = await TVC_Inventory.getConsumeLog(id);
            if (!log || !consumeLogCanConfirm(st, log)) continue;
            const user = spareInventoryUser(st);
            log.confirmed_by = TVC_RBAC.getDepartmentConfirmLabel(log.department || st.department) || TVC_RBAC.getRankLabel(user);
            log.confirmed_at = new Date().toISOString();
            log.list_status = SPARE_LIST_STATUS.CONFIRMED;
            await TVC_Inventory.saveConsumeLog(log);
            confirmed++;
            if (loadedId === id) needReload = true;
        }
        if (needReload && isConsumedLogWindow(m)) {
            await loadConsumeLogIntoListWindow(loadedId, { preserveHistPopover: true });
        }
        await refreshConsumeLogListUi();
        const skipped = checkedIds.length - confirmed;
        if (skipped > 0) {
            await TVC_Dialog.alert(`Confirmed ${confirmed} log(s). Skipped ${skipped} (not Reported or no permission).`);
        } else {
            await TVC_Dialog.alert(`Confirmed ${confirmed} log(s).`);
        }
    }

    async function consumeLogReportApprove() {
        const st = getState();
        if (!isReqListHqUser(st)) {
            await TVC_Dialog.alert('This action is available in HQ Mode only.');
        }
        const m = modState(st);
        const { vesselId } = await vesselScope();
        const allLogs = await TVC_Inventory.listConsumeLogs(vesselId);
        const checkedIds = Object.keys(m.consumeLogCheckedIds || {}).filter(k => m.consumeLogCheckedIds[k]);
        const idsToApprove = checkedIds.length
            ? consumeLogCheckedApprovableIds(m, allLogs, st)
            : [];
        if (!idsToApprove.length) {
            if (checkedIds.length) {
                await TVC_Dialog.alert('None of the selected logs can be approved. Confirmed logs, or HQ-authored Reported logs, can be approved with HQ Superintendent permission.');
            } else {
                await TVC_Dialog.alert('Select one or more approvable Consumption logs to approve.');
            }
            return;
        }
        const loadedId = _consumeDraft?.log_id || m.selectedConsumeLogId;
        let approved = 0;
        let needReload = false;
        const now = new Date().toISOString();
        const user = spareInventoryUser(st);
        for (const id of idsToApprove) {
            const log = await TVC_Inventory.getConsumeLog(id);
            if (!log || !consumeLogCanApprove(st, log)) continue;
            if (!log.confirmed_at && !log.confirmed_by && TVC_RBAC.canHqDirectApprove(user, log)) {
                log.confirmed_by = requisitionConfirmByLabel(st, log);
                log.confirmed_at = now;
            }
            log.approved_by = 'Company';
            log.approved_at = now;
            log.list_status = SPARE_LIST_STATUS.APPROVED;
            await TVC_Inventory.saveConsumeLog(log);
            approved++;
            if (loadedId === id) needReload = true;
        }
        if (needReload && isConsumedLogWindow(m)) {
            await loadConsumeLogIntoListWindow(loadedId, { preserveHistPopover: true });
        }
        await refreshConsumeLogListUi();
        const skipped = checkedIds.length - approved;
        if (skipped > 0) {
            await TVC_Dialog.alert(`Approved ${approved} log(s). Skipped ${skipped} (not Confirmed or no permission).`);
        } else {
            await TVC_Dialog.alert(`Approved ${approved} log(s).`);
        }
    }

    async function consumeHistConfirmOrApprove() {
        const st = getState();
        const m = modState(st);
        if (!m.consumeFromHistory || m.consumeLogListEditing) return;
        const draft = getConsumeSession();
        const logId = draft?.log_id || m.selectedConsumeLogId;
        const user = spareInventoryUser(st);
        if (!logId || !user) return;
        const log = await TVC_Inventory.getConsumeLog(logId);
        if (!log) {
            await TVC_Dialog.alert('Consumption log not found.');
            return;
        }
        const now = new Date().toISOString();
        if (isReqListHqUser(st)) {
            if (log.approved_by || log.approved_at) {
                try {
                    log.approved_by = '';
                    log.approved_at = '';
                    log.list_status = (log.confirmed_by || log.confirmed_at)
                        ? SPARE_LIST_STATUS.CONFIRMED
                        : SPARE_LIST_STATUS.REPORTED;
                    await TVC_Inventory.saveConsumeLog(log);
                    await reloadConsumeLogKeepView(logId);
                    await TVC_Dialog.alert('Approval removed.');
                } catch (e) {
                    await TVC_Dialog.alert(e.message || e.code || 'Unapprove failed');
                }
                return;
            }
            if (!consumeLogCanApprove(st, log)) {
                await TVC_Dialog.alert('This log cannot be approved.');
                return;
            }
            try {
                if (!log.confirmed_at && !log.confirmed_by) {
                    log.confirmed_by = requisitionConfirmByLabel(st, log);
                    log.confirmed_at = now;
                }
                log.approved_by = 'Company';
                log.approved_at = now;
                log.list_status = SPARE_LIST_STATUS.APPROVED;
                await TVC_Inventory.saveConsumeLog(log);
                await reloadConsumeLogKeepView(logId);
                await TVC_Dialog.alert('Approved by HQ.');
            } catch (e) {
                await TVC_Dialog.alert(e.message || e.code || 'Approve failed');
            }
            return;
        }
        if (log.confirmed_by || log.confirmed_at) {
            if (log.approved_by || log.approved_at) {
                await TVC_Dialog.alert('Approved items cannot be unconfirmed.');
                return;
            }
            try {
                log.confirmed_by = '';
                log.confirmed_at = '';
                log.list_status = SPARE_LIST_STATUS.REPORTED;
                await TVC_Inventory.saveConsumeLog(log);
                await reloadConsumeLogKeepView(logId);
                await TVC_Dialog.alert('Confirmation removed. Status returned to Reported.');
            } catch (e) {
                await TVC_Dialog.alert(e.message || e.code || 'Unconfirm failed');
            }
            return;
        }
        if (!consumeLogCanConfirm(st, log)) {
            await TVC_Dialog.alert('Only Reported logs can be confirmed, and you need Chief Engineer, Chief Officer, Captain, or HQ Superintendent permission.');
            return;
        }
        try {
            log.confirmed_by = TVC_RBAC.getDepartmentConfirmLabel(log.department || st.department) || TVC_RBAC.getRankLabel(user);
            log.confirmed_at = now;
            log.list_status = SPARE_LIST_STATUS.CONFIRMED;
            await TVC_Inventory.saveConsumeLog(log);
            await reloadConsumeLogKeepView(logId);
            await TVC_Dialog.alert('Confirmed.');
        } catch (e) {
            await TVC_Dialog.alert(e.message || e.code || 'Confirm failed');
        }
    }

    async function confirmConsumeLogById(logId) {
        const st = getState();
        const log = await TVC_Inventory.getConsumeLog(logId);
        if (!log || !consumeLogCanConfirm(st, log)) return false;
        const user = spareInventoryUser(st);
        log.confirmed_by = TVC_RBAC.getDepartmentConfirmLabel(log.department || st.department) || TVC_RBAC.getRankLabel(user);
        log.confirmed_at = new Date().toISOString();
        log.list_status = SPARE_LIST_STATUS.CONFIRMED;
        await TVC_Inventory.saveConsumeLog(log);
        return true;
    }

    async function approveConsumeLogById(logId) {
        const st = getState();
        const log = await TVC_Inventory.getConsumeLog(logId);
        if (!log || !consumeLogCanApprove(st, log)) return false;
        const user = spareInventoryUser(st);
        const now = new Date().toISOString();
        if (!log.confirmed_at && !log.confirmed_by) {
            log.confirmed_by = requisitionConfirmByLabel(st, log);
            log.confirmed_at = now;
        }
        log.approved_by = 'Company';
        log.approved_at = now;
        log.list_status = SPARE_LIST_STATUS.APPROVED;
        await TVC_Inventory.saveConsumeLog(log);
        return true;
    }

