    async function reqListReportConfirm() {
        const st = getState();
        const m = modState(st);
        const { vesselId } = await vesselScope();
        const allReqs = await TVC_Inventory.listRequisitions(vesselId);
        const checkedIds = Object.keys(m.reqListCheckedIds || {}).filter(k => m.reqListCheckedIds[k]);
        const idsToConfirm = checkedIds.length
            ? reqListCheckedConfirmableIds(m, allReqs, st)
            : [];
        if (!idsToConfirm.length) {
            if (checkedIds.length) {
                await TVC_Dialog.alert('None of the selected requisitions can be confirmed. Only Reported requisitions can be confirmed, and you need Chief Engineer, Chief Officer, Captain, or HQ Superintendent permission.');
            }
            await TVC_Dialog.alert('Select one or more Reported requisitions to confirm.');
        }
        const loadedId = _reqSheet.reqId || _reqWorkDraft?.id;
        let confirmed = 0;
        let needReload = false;
        for (const id of idsToConfirm) {
            const req = await TVC_Inventory.getRequisition(id);
            if (!req || !reqListCanConfirm(st, req)) continue;
            req.confirmed_by = requisitionConfirmByLabel(st, req);
            req.confirmed_at = new Date().toISOString();
            req.list_status = SPARE_LIST_STATUS.CONFIRMED;
            await TVC_Inventory.saveRequisition(req);
            confirmed++;
            if (loadedId === id) needReload = true;
        }
        if (needReload && isRequisitionListWindow(m)) {
            await loadRequisitionIntoListWindow(loadedId);
        }
        await refreshReqListUi();
        await syncReportedWaitAndRefreshList();
        const skipped = checkedIds.length - confirmed;
        if (skipped > 0) {
            await TVC_Dialog.alert(`Confirmed ${confirmed} requisition(s). Skipped ${skipped} (not Reported or no permission).`);
        } else {
            await TVC_Dialog.alert(`Confirmed ${confirmed} requisition(s).`);
        }
    }

    async function reqListReportApprove() {
        const st = getState();
        const m = modState(st);
        const { vesselId } = await vesselScope();
        const allReqs = await TVC_Inventory.listRequisitions(vesselId);
        const checkedIds = Object.keys(m.reqListCheckedIds || {}).filter(k => m.reqListCheckedIds[k]);
        const idsToApprove = checkedIds.length
            ? reqListCheckedApprovableIds(m, allReqs, st)
            : [];
        if (!idsToApprove.length) {
            if (checkedIds.length) {
                await TVC_Dialog.alert('None of the selected requisitions can be approved. Submitted or Evaluating requisitions, or HQ-authored Reported requisitions, can be approved with HQ Superintendent permission.');
            }
            await TVC_Dialog.alert('Select one or more approvable requisitions to approve.');
        }
        const loadedId = _reqSheet.reqId || _reqWorkDraft?.id;
        let approved = 0;
        let needReload = false;
        const now = new Date().toISOString();
        const user = spareInventoryUser(st);
        for (const id of idsToApprove) {
            const req = await TVC_Inventory.getRequisition(id);
            if (!req || !reqListCanApprove(st, req)) continue;
            if (!req.confirmed_at && !req.confirmed_by && TVC_RBAC.canHqDirectApprove(user, req)) {
                req.confirmed_by = requisitionConfirmByLabel(st, req);
                req.confirmed_at = now;
            }
            req.approved_by = hqSuperintendentApprovalLabel(st);
            req.approved_at = now;
            req.list_status = SPARE_LIST_STATUS.APPROVED;
            await TVC_Inventory.saveRequisition(req);
            approved++;
            if (loadedId === id) needReload = true;
        }
        if (needReload && isRequisitionListWindow(m)) {
            await loadRequisitionIntoListWindow(loadedId);
        }
        await refreshReqListUi();
        await syncReportedWaitAndRefreshList();
        const skipped = checkedIds.length - approved;
        if (skipped > 0) {
            await TVC_Dialog.alert(`Approved ${approved} requisition(s). Skipped ${skipped} (not Submitted/Evaluating or no permission).`);
        } else {
            await TVC_Dialog.alert(`Approved ${approved} requisition(s).`);
        }
    }

    async function reqListExportToMaster() {
        const st = getState();
        const m = modState(st);
        const xferKind = _reqListXferExportKind;
        const { isHq, vesselId } = await vesselScope();
        const meta = reqListXferExportMeta(xferKind);
        if (xferKind === 'received') {
            if (!canCreateDeliver(st)) {
                await TVC_Dialog.alert('You do not have permission to export received data.');
                return;
            }
        } else if (!canCreateRequisition(st)) {
            await TVC_Dialog.alert('You do not have permission to export requisitions.');
            return;
        }
        const allReqs = await TVC_Inventory.listRequisitions(vesselId);
        const ids = reqListCheckedExportableIds(m, allReqs);
        const statusLabel = meta.statusLabel;
        if (!ids.length) {
            const anyChecked = Object.keys(m.reqListCheckedIds || {}).some(k => m.reqListCheckedIds[k]);
            if (anyChecked) await TVC_Dialog.alert(`Only ${statusLabel} requisitions can be exported.`);
            else await TVC_Dialog.alert('Select one or more requisitions to export.');
            return;
        }
        const skipped = Object.keys(m.reqListCheckedIds || {}).filter(k => m.reqListCheckedIds[k] && !ids.includes(k));
        const confirmTarget = meta.confirmTarget;
        if (skipped.length) {
            const skipNos = skipped.map(id => allReqs.find(r => r.id === id)?.req_no || id).join(', ');
            if (!await TVC_Dialog.confirm({ message: `${skipped.length} non-${statusLabel} item(s) will be skipped (${skipNos}).\n\nExport ${ids.length} ${confirmTarget}?` })) return;
        } else if (!await TVC_Dialog.confirm({ message: `Export ${ids.length} ${confirmTarget}?` })) {
            return;
        }
        let ok = 0;
        let exportFilename = '';
        if (xferKind === 'quotation') {
            for (const id of ids) {
                try {
                    const result = await exportQuotationReq(id);
                    exportFilename = result?.filename || exportFilename;
                    ok++;
                } catch (e) {
                    await TVC_Dialog.alert(`Export failed: ${e.message || e.code || id}`);
                }
            }
        } else {
            if (typeof TVC_SpareSync === 'undefined') await TVC_Dialog.alert('SPARE ZIP export is not available.');
            const idsToExport = [...ids];
            let reqs = [];
            try {
                reqs = await prepareReqsForHqZipExport(idsToExport);
            } catch (e) {
                await TVC_Dialog.alert(`Export failed: ${e.message || e.code || e}`);
                return;
            }
            if (xferKind === 'reply-evaluation') {
                const notReady = reqs.filter(r => !reqWorkHqEvaluationReady(r));
                if (notReady.length) {
                    const nos = notReady.map(r => r.req_no || r.id).join(', ');
                    await TVC_Dialog.alert(`Complete evaluation for all items first: ${nos}`);
                    return;
                }
            }
            if (xferKind === 'purchase-order') {
                const notReady = reqs.filter(r => !reqListCanPurchaseOrderExport(r));
                if (notReady.length) {
                    const nos = notReady.map(r => r.req_no || r.id).join(', ');
                    await TVC_Dialog.alert(`Only ${HQ_REQ_LIST_STATUS.EVALUATING} and Approved requisitions can be exported: ${nos}`);
                    return;
                }
            }
            try {
                const excelSuffix = xferKind === 'reply-evaluation' ? 'EVAL_REPLY'
                    : xferKind === 'purchase-order' ? 'ORDER' : null;
                const result = await exportRequisitionsZipWithExcel(st, reqs, {
                    category: meta.category,
                    vendorOnly: (xferKind === 'requisition' || xferKind === 'received') ? !isHq : undefined,
                    excelSuffix,
                });
                exportFilename = result.filename;
                for (const req of reqs) {
                    if (xferKind === 'requisition') {
                        await applyRequisitionExportStatus(req);
                    } else if (xferKind === 'received') {
                        const vf = ensureReqWorkVesselFlowState(req);
                        vf.receivedExported = true;
                        vf.flowStage = 'received-export';
                        await TVC_Inventory.saveRequisition(req);
                    } else if (xferKind === 'reply-evaluation') {
                        const q = ensureReqWorkQuoteState(req);
                        q.replyExported = true;
                        q.flowStage = 'reply-evaluation';
                        reqHqBumpMaxFlowStage(req, 'purchase-order');
                        await TVC_Inventory.saveRequisition(req);
                    } else if (xferKind === 'purchase-order') {
                        const q = ensureReqWorkQuoteState(req);
                        q.flowStage = 'ordered';
                        q.orderExported = true;
                        reqHqBumpMaxFlowStage(req, 'ordered');
                        await TVC_Inventory.saveRequisition(req);
                    }
                }
                ok = reqs.length;
                await refreshReqListModalIfOpen();
                render();
            } catch (e) {
                await TVC_Dialog.alert(`Export failed: ${e.message || e.code || e}`);
            }
        }
        if (ok) {
            if (xferKind) {
                await logSpareDataXfer({
                    direction: 'EXPORT',
                    category: meta.category,
                    summary: exportFilename ? `${ok} item(s) → ${exportFilename}` : meta.successMsg(ok),
                    count: ok,
                    file_name: exportFilename,
                });
                const returnTo = _reqListXferExportReturn;
                const reloadId = isReqWorkXferExportReturn(returnTo) ? _reqWorkDraft?.id : null;
                _reqListXferExportKind = null;
                _reqListXferExportReturn = null;
                setReqXferExportStack(false);
                closeSpicsModal('spareReqListModal');
                clearReqListUiState(modState(getState()));
                if (isReqWorkXferExportReturn(returnTo) && reloadId) {
                    showSpicsModal('spareReqWorkModal');
                    await loadRequisitionIntoListWindow(reloadId, { preserveHistPopover: true });
                    const m = modState(getState());
                    if (isReqListHqUser(getState())) {
                        if (xferKind === 'purchase-order') await applyHqOrderedViewState();
                        else if (xferKind === 'quotation') {
                            m.reqWorkHqStickySelectVendorReqId = null;
                            applyReqWorkHqStageOnLoad(_reqWorkDraft, m);
                        }
                    }
                    syncReqWorkFlowBtns();
                }
            }
            await TVC_Dialog.alert(exportFilename
                ? `Exported ${ok} item(s).\n${exportFilename}`
                : meta.successMsg(ok));
        }
    }

    async function applyRequisitionExportStatus(req) {
        if (!req?.id) return;
        const listSt = spareListStatus(req);
        if (listSt !== SPARE_LIST_STATUS.DRAFT) {
            await TVC_Inventory.setStatus(req.id, TVC_Inventory.REQ_STATUS.SUBMITTED);
        } else if (req.status === TVC_Inventory.REQ_STATUS.DRAFT) {
            await TVC_Inventory.setStatus(req.id, TVC_Inventory.REQ_STATUS.EXPORTED);
        }
    }

