    function showImportLoading(msg) {
        let el = document.getElementById('spareImportOverlay');
        if (!el) {
            el = document.createElement('div');
            el.id = 'spareImportOverlay';
            el.className = 'spare-import-overlay';
            document.body.appendChild(el);
        }
        el.innerHTML = `<div class="spare-import-loading"><div class="spare-spinner"></div><div>${esc(msg)}</div><small>1,300+ items — Please wait</small></div>`;
        el.style.display = 'flex';
    }

    function hideImportLoading() {
        const el = document.getElementById('spareImportOverlay');
        if (el) el.style.display = 'none';
    }

    async function finishImport(st, res) {
        setSpareInventoryGroupKey(st, null);
        modState(st).showLowOnly = false;
        modState(st).partNo = '';
        modState(st).description = '';
        st.spareSearch = '';
        const partCount = res.stats?.spares || res.spares?.length || res.parts?.length || 0;
        const equipCount = res.equipment || res.equipmentTree?.length || res.parsed?.equipment?.length || 0;
        st._spareImportMsg = `ENGINE ${partCount} parts · Equipment ${equipCount} nodes`;
        await refresh();
        await render();
        return res;
    }

    /**
     * loadSpareInventory — CSV/XLS 업로드 → DB 적재 → SPARE 리스트 자동 갱신
     * @param {string|File|null} [source] null이면 data/spare inventory.xls - ENGINE.csv
     */
    async function loadSpareInventory(source, opts = {}) {
        const { st } = await vesselScope();
        const silent = !!opts.silent;
        if (opts.requireAuth !== false && window.TVC_RBAC) {
            TVC_RBAC.assert(st.user, TVC_RBAC.Action.MODIFY_INVENTORY);
        }
        if (!silent) showImportLoading('Loading ENGINE spare inventory…');
        const importOpts = {
            department: 'ENGINE',
            merge: opts.merge !== false,
            onProgress: opts.onProgress || ((n, total) => showImportLoading(`Saving… ${n} / ${total}`)),
        };
        try {
            const res = await TVC_DB.loadSpareInventory(source ?? null, importOpts);
            await finishImport(st, res);
            if (!silent) {
                await TVC_Dialog.alert(
                    `ENGINE inventory loaded (loadSpareInventory)\n` +
                    `· ${res.stats?.spares || 0} parts\n` +
                    `· Equipment ${res.equipment} nodes (parent groups such as MAIN ENGINE)\n` +
                    `· New ${res.spareCreated} · Updated ${res.spareUpdated}`
                );
            }
            return res;
        } finally {
            if (!silent) hideImportLoading();
        }
    }

    /** SPARE 탭 진입 시 부품 500건 미만이면 번들 CSV 자동 적재 (1회) */
    async function ensureInventoryLoaded() {
        const st = getState();
        if (st._spareAutoLoadDone || (st.spares || []).length >= 500) return false;
        if (TVC_Env.isFileProtocol()) return false;
        st._spareAutoLoadDone = true;
        try {
            const res = await TVC_DB.loadSpareInventory(null, { department: 'ENGINE', merge: true });
            if (res.loaded) {
                st._spareImportMsg = `ENGINE ${res.stats?.spares || 0} parts auto-loaded`;
                await refresh();
                return true;
            }
        } catch (e) {
            console.info('[SPARE] loadSpareInventory auto-load skipped:', e.message || e.code || e);
            st._spareAutoLoadDone = false;
        }
        return false;
    }

    /** 권장: 번들 XLS → 없으면 loadSpareInventory(CSV) · file:// 는 label 클릭 */
    async function loadBundledXls() {
        if (TVC_Env.isFileProtocol()) {
            await TVC_Dialog.alert(
                'Automatic import is not available when opened as a local file.\n\n' +
                'Select spare-inventory.xls manually, or use npm run serve / the installed app.'
            );
            return;
        }
        const { st } = await vesselScope();
        showImportLoading('ENGINE inventory loading…');
        const importOpts = {
            department: 'ENGINE',
            sheetName: 'ENGINE',
            merge: true,
            onProgress: (n, total) => showImportLoading(`Saving… ${n} / ${total}`),
        };
        try {
            if (window.TVC_RBAC) TVC_RBAC.assert(st.user, TVC_RBAC.Action.MODIFY_INVENTORY);
            let res;
            try {
                res = await TVC_DB.InventoryDB.importXlsFromUrl('data/spare-inventory.xls', importOpts);
            } catch (xlsErr) {
                const xlsMsg = xlsErr.message || xlsErr.code || '';
                if (xlsErr.code === 'NOT_FOUND' || /404|fetch|Failed to fetch/i.test(xlsMsg)) {
                    showImportLoading('XLS 없음 — ENGINE CSV (loadSpareInventory)…');
                    res = await TVC_DB.loadSpareInventory(null, importOpts);
                } else {
                    throw xlsErr;
                }
            }
            await finishImport(st, res);
            await TVC_Dialog.alert(
                `ENGINE inventory import complete\n` +
                `· ${res.stats?.spares || res.spares?.length || 0} parts\n` +
                `· Equipment ${res.equipment} · New ${res.spareCreated} · Updated ${res.spareUpdated}`
            );
        } catch (e) {
            hideImportLoading();
            const msg = e.message || e.code || String(e);
            if (/fetch|Failed to fetch|404|NOT_FOUND/i.test(msg)) {
                if (await TVC_Dialog.confirm({ message: 
                    'Cannot load the inventory file.\n\n' +
                    '▶ Run npm run serve and open http://localhost:3000, then retry\n' +
                    '▶ Or OK → select spare inventory.xls manually\n\n' +
                    'Open the file picker?'
                 })) {
                    triggerInventoryImport();
                }
            } else {
                await TVC_Dialog.alert('Import failed: ' + msg);
            }
        } finally {
            hideImportLoading();
        }
    }

    function triggerInventoryImport() { document.getElementById('srInventoryImportFile')?.click(); }
    function triggerCsvUpload() { document.getElementById('srCsvUploadFile')?.click(); }
    function triggerImport(id) { _importReqId = id; document.getElementById('srImportFile')?.click(); }
    async function openReq(id) {
        const modal = document.getElementById('spareReqListModal');
        const m = modState(getState());
        if (modal && !modal.classList.contains('hidden')) {
            clearReqListUiState(m);
            applyReqListSelection(m, id);
            await renderReqListModal();
        } else await openReqListModal({ selectId: id });
    }

    /** CSV 업로드 → loadSpareInventory → 리스트 즉시 렌더 */
    async function onCsvUpload(file) {
        if (!file) return;
        try {
            await loadSpareInventory(file, { merge: true });
        } catch (e) {
            await TVC_Dialog.alert('CSV upload failed: ' + (e.message || e.code));
        } finally {
            const fi = document.getElementById('srCsvUploadFile');
            if (fi) fi.value = '';
        }
    }

    async function onInventoryImportFile(file) {
        if (!file) return;
        const { st } = await vesselScope();
        showImportLoading('Reading ' + file.name + '…');
        try {
            if (window.TVC_RBAC) TVC_RBAC.assert(st.user, TVC_RBAC.Action.MODIFY_INVENTORY);
            const sheet = file.name.toLowerCase().includes('deck') ? 'DECK' : 'ENGINE';
            const name = (file.name || '').toLowerCase();
            let res;
            if (name.endsWith('.csv')) {
                res = await TVC_DB.loadSpareInventory(file, {
                    department: sheet, merge: true,
                    onProgress: (n, total) => showImportLoading(`Saving… ${n} / ${total}`),
                });
            } else {
                res = await TVC_DB.InventoryDB.importXlsFile(file, {
                    department: sheet,
                    sheetName: sheet,
                    merge: true,
                    onProgress: (n, total) => showImportLoading(`Saving… ${n} / ${total}`),
                });
            }
            await finishImport(st, res);
            await TVC_Dialog.alert(
                `ENGINE inventory import complete\n` +
                `· ${res.stats?.spares || res.spares?.length || 0} parts\n` +
                `· Equipment ${res.equipment} · New ${res.spareCreated} · Updated ${res.spareUpdated}`
            );
        } catch (e) {
            await TVC_Dialog.alert('Import failed: ' + (e.message || e.code));
        } finally {
            hideImportLoading();
            document.getElementById('srInventoryImportFile').value = '';
        }
    }

    async function refreshReqListModalIfOpen() {
        const modal = document.getElementById('spareReqListModal');
        if (modal && !modal.classList.contains('hidden')) await renderReqListModal();
    }

    async function onImportFile(file) {
        if (!file || !_importReqId) return;
        const { isHq } = await vesselScope();
        try {
            const rows = await TVC_Excel.parseRequisitionFile(file);
            const res = isHq
                ? await TVC_Inventory.applyHqAdjustment(_importReqId, rows)
                : await TVC_Inventory.applyVendorQuote(_importReqId, rows);
            const req = await TVC_Inventory.getRequisition(_importReqId);
            const dbRes = await TVC_Inventory.applyExcelImport(rows, req?.req_no);
            await TVC_Dialog.alert(`Applied: ${res.updated}/${res.total} · DB ${dbRes.updated}/${dbRes.total}`);
            await refresh();
            await refreshReqListModalIfOpen();
            render();
        } catch (e) { await TVC_Dialog.alert('Import failed: ' + (e.message || e.code)); }
        finally { document.getElementById('srImportFile').value = ''; _importReqId = null; }
    }

    async function resolveExportRequisition(id) {
        captureReqWorkMeta();
        captureReqWorkLineQtys();
        if (_reqWorkDraft?.id && String(_reqWorkDraft.id) === String(id)) {
            return _reqWorkDraft;
        }
        const req = await TVC_Inventory.getRequisition(id);
        if (!req) throw new Error('REQ_NOT_FOUND');
        return req;
    }

    function reqWorkFlowExcelFilename(reqNo, suffix) {
        const safeNo = String(reqNo || 'REQUISITION').replace(/[\\/:*?"<>|]/g, '_').trim();
        const tag = String(suffix || 'EXPORT').replace(/[\\/:*?"<>|]/g, '_').trim();
        return `${safeNo}_${tag}.xlsx`;
    }

    async function buildReqWorkFlowExcelFiles(st, req, vesselName, suffix, opts = {}) {
        if (!TVC_Excel?.buildSparePartsRequisitionBuffer) return [];
        const pages = buildReqPreviewExportPages(st, req, opts);
        if (!pages.length) return [];
        const buffer = await TVC_Excel.buildSparePartsRequisitionBuffer({
            req,
            vesselName,
            typeLabel: reqListTypeLabel(req),
            fmtDate: fmtSpareDate,
            pages,
            vendorInfo: opts.vendorInfo || reqWorkExportVendorInfo(req),
        });
        return [{
            filename: reqWorkFlowExcelFilename(req.req_no, suffix),
            buffer: buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer),
        }];
    }

    async function prepareReqsForHqZipExport(ids) {
        const reqs = [];
        for (const id of ids) {
            const req = await resolveExportRequisition(id);
            if (_reqWorkDraft?.id && String(_reqWorkDraft.id) === String(id)) {
                await persistReqWorkHqDraft();
            }
            reqs.push(req);
        }
        return reqs;
    }

    async function exportRequisitionsZipWithExcel(st, reqs, opts = {}) {
        if (typeof TVC_SpareSync === 'undefined') throw new Error('SPARE ZIP export is not available.');
        const { isHq, vesselId } = await vesselScope();
        const list = (reqs || []).filter(Boolean);
        if (!list.length) throw new Error('No requisitions to export.');
        const vesselName = await vesselLabel(vesselId, list[0]?.department || st.user?.department);
        const excelSuffix = opts.excelSuffix;
        const excelFiles = [];
        if (excelSuffix && TVC_Excel?.buildSparePartsRequisitionBuffer) {
            const excelStage = excelSuffix === 'EVAL_REPLY' ? 'reply-evaluation'
                : excelSuffix === 'ORDER' ? 'purchase-order'
                    : 'requisition';
            for (const req of list) {
                excelFiles.push(...await buildReqWorkFlowExcelFiles(st, req, vesselName, excelSuffix, {
                    flowStage: excelStage,
                    vendorInfo: reqWorkExportVendorInfo(req),
                }));
            }
        }
        return TVC_SpareSync.exportRequisitionsZip(st.user, list, {
            category: opts.category,
            vendorOnly: opts.vendorOnly,
            isHq,
            excelFiles,
        });
    }

    function hqSuperintendentApprovalLabel(st) {
        const user = spareInventoryUser(st);
        return TVC_RBAC?.getRankLabel?.(user) || 'Superintendent';
    }

    function applyHqQuoteExportApproval(req, st) {
        if (!req) return;
        const now = new Date().toISOString();
        req.approved_by = hqSuperintendentApprovalLabel(st);
        req.approved_at = req.approved_at || now;
        req.list_status = SPARE_LIST_STATUS.APPROVED;
    }

    async function exportQuotationReq(id) {
        const { st, isHq, vesselId } = await vesselScope();
        const req = await resolveExportRequisition(id);
        const labels = reqWorkQuoteFlowLabels();
        if (!reqWorkHqQuoteSetupReady(req)) {
            throw new Error(`${labels.selectVendor} not complete for this requisition.`);
        }
        if (typeof TVC_SpareSync === 'undefined') throw new Error('SPARE ZIP export is not available.');
        if (!TVC_Excel?.buildQuoteSparePartsRequisitionBuffer) throw new Error('Quotation Excel export is not available.');
        ensureReqWorkQuoteState(req);
        const targets = reqWorkQuoteExportTargets(req);
        if (!targets.length) throw new Error('No vendor quote files for this requisition.');
        const vesselName = await vesselLabel(vesselId, req.department || st.user?.department);
        const excelFiles = [];
        for (const target of targets) {
            const pages = buildReqPreviewExportPages(st, { ...req, lines: target.lines }, {
                flowStage: 'request-quote',
                vendorSlot: target.slot,
            });
            if (!pages.length) throw new Error(`No Excel pages for vendor ${target.vendorName || 'vendor'}.`);
            const buffer = await TVC_Excel.buildQuoteSparePartsRequisitionBuffer({
                req,
                vesselName,
                vendorName: target.vendorName,
                currency: target.currency,
                typeLabel: reqListTypeLabel(req),
                fmtDate: fmtSpareDate,
                pages,
                quoteMode: 'vendor',
            });
            excelFiles.push({
                filename: target.filename,
                buffer: buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer),
            });
        }
        const result = await TVC_SpareSync.exportQuotationZip(st.user, req, targets, { isHq, excelFiles });
        const q = ensureReqWorkQuoteState(req);
        q.flowStage = 'quoted';
        q.quoteExported = true;
        reqHqBumpMaxFlowStage(req, 'quoted');
        applyHqQuoteExportApproval(req, st);
        await TVC_Inventory.saveRequisition(req);
        if (_reqWorkDraft?.id && String(_reqWorkDraft.id) === String(id)) {
            _reqWorkDraft.approved_by = req.approved_by;
            _reqWorkDraft.approved_at = req.approved_at;
            _reqWorkDraft.list_status = req.list_status;
            const dq = ensureReqWorkQuoteState(_reqWorkDraft);
            dq.flowStage = 'quoted';
            dq.quoteExported = true;
            reqHqBumpMaxFlowStage(_reqWorkDraft, 'quoted');
            const m = modState(getState());
            m.reqWorkHqStickySelectVendorReqId = null;
            applyReqWorkHqStageOnLoad(_reqWorkDraft, m);
        }
        await refreshReqListModalIfOpen();
        render();
        return result;
    }

    async function exportReplyEvaluationReq(id) {
        const { st, isHq } = await vesselScope();
        const req = await resolveExportRequisition(id);
        if (!reqWorkHqEvaluationReady(req)) throw new Error('Evaluation not complete for this requisition.');
        if (typeof TVC_SpareSync === 'undefined') throw new Error('SPARE ZIP export is not available.');
        if (!TVC_Excel?.buildSparePartsRequisitionBuffer) throw new Error('Reply Evaluation Excel export is not available.');
        if (_reqWorkDraft?.id && String(_reqWorkDraft.id) === String(id)) {
            await persistReqWorkHqDraft();
        }
        await exportRequisitionsZipWithExcel(st, [req], {
            category: SPARE_XFER_EXPORT.REPLY_EVALUATION,
            excelSuffix: 'EVAL_REPLY',
        });
        const q = ensureReqWorkQuoteState(req);
        q.replyExported = true;
        q.flowStage = 'reply-evaluation';
        reqHqBumpMaxFlowStage(req, 'purchase-order');
        await TVC_Inventory.saveRequisition(req);
        await refreshReqListModalIfOpen();
        render();
    }

    async function exportPurchaseOrderReq(id) {
        const { st, isHq } = await vesselScope();
        const req = await resolveExportRequisition(id);
        if (!reqListCanPurchaseOrderExport(req)) {
            throw new Error(`Only ${HQ_REQ_LIST_STATUS.EVALUATING} and Approved requisitions can be exported as Purchase Order.`);
        }
        if (typeof TVC_SpareSync === 'undefined') throw new Error('SPARE ZIP export is not available.');
        if (!TVC_Excel?.buildSparePartsRequisitionBuffer) throw new Error('Purchase Order Excel export is not available.');
        if (_reqWorkDraft?.id && String(_reqWorkDraft.id) === String(id)) {
            await persistReqWorkHqDraft();
        }
        await exportRequisitionsZipWithExcel(st, [req], {
            category: SPARE_XFER_EXPORT.PURCHASE_ORDER,
            excelSuffix: 'ORDER',
        });
        const q = ensureReqWorkQuoteState(req);
        q.flowStage = 'ordered';
        q.orderExported = true;
        reqHqBumpMaxFlowStage(req, 'ordered');
        await TVC_Inventory.saveRequisition(req);
        await refreshReqListModalIfOpen();
        render();
    }

    async function exportReceivedReq(id) {
        const { st, isHq } = await vesselScope();
        const req = await TVC_Inventory.getRequisition(id);
        if (!req) throw new Error('REQ_NOT_FOUND');
        if (!reqListCanReceivedExport(req)) throw new Error('Only Received requisitions can be exported.');
        if (typeof TVC_SpareSync === 'undefined') throw new Error('SPARE ZIP export is not available.');
        await TVC_SpareSync.exportRequisitionZip(st.user, req, {
            category: SPARE_XFER_EXPORT.RECEIVED,
            vendorOnly: !isHq,
            isHq,
        });
        if (!isHq) {
            const vf = ensureReqWorkVesselFlowState(req);
            vf.receivedExported = true;
            vf.flowStage = 'received-export';
            await TVC_Inventory.saveRequisition(req);
        }
        await refreshReqListModalIfOpen();
        render();
    }

    async function exportReq(id) {
        const { st, isHq } = await vesselScope();
        try {
            const req = await TVC_Inventory.getRequisition(id);
            if (!req) throw new Error('REQ_NOT_FOUND');
            if (!reqListCanMasterExport(req)) throw new Error('Only Confirmed requisitions can be exported.');
            if (typeof TVC_SpareSync === 'undefined') throw new Error('SPARE ZIP export is not available.');
            await TVC_SpareSync.exportRequisitionZip(st.user, req, {
                category: SPARE_XFER_EXPORT.REQUISITION,
                vendorOnly: !isHq,
                isHq,
            });
            await applyRequisitionExportStatus(req);
            await refreshReqListModalIfOpen();
            render();
        } catch (e) { await TVC_Dialog.alert(e.message || e.code); }
    }

    // ── SPARE Data Export / Import (unified wizard) ─────────────────────
    const SPARE_XFER_EXPORT = {
        REQUISITION: 'REQUISITION',
        QUOTATION: 'QUOTATION',
        REPLY_EVALUATION: 'REPLY_EVALUATION',
        PURCHASE_ORDER: 'PURCHASE_ORDER',
        RECEIVED: 'RECEIVED',
        INVENTORY: 'INVENTORY',
    };
    const SPARE_XFER_MONTHLY_REPORT_LABEL = 'Monthly Report';

    function resetSpareXfer() {
        _spareXfer = {
            step: 'mode',
            importKind: 'general',
            hqImportType: null, // requisition | quotation | received | inventory
            masterImportType: null, // requisition | evaluation | received | inventory
            vesselImportType: null, // evaluation | inventory
        };
    }

    const HQ_IMPORT_TYPES = [
        { key: 'requisition', label: 'Requisition' },
        { key: 'quotation', label: 'Quotation' },
        { key: 'received', label: 'Received' },
        { key: 'inventory', label: SPARE_XFER_MONTHLY_REPORT_LABEL },
    ];

    const MASTER_IMPORT_TYPES = [
        { key: 'requisition', label: 'Requisition' },
        { key: 'evaluation', label: 'Order' },
        { key: 'received', label: 'Received' },
        { key: 'inventory', label: SPARE_XFER_MONTHLY_REPORT_LABEL },
    ];

    const VESSEL_IMPORT_TYPES = [
        { key: 'evaluation', label: 'Order' },
        { key: 'inventory', label: SPARE_XFER_MONTHLY_REPORT_LABEL },
    ];

    async function logSpareDataXfer(entry) {
        const st = getState();
        const user = st.user;
        const dir = String(entry.direction || '').toUpperCase();
        try {
            await TVC_DB.put('sync_history', {
                at: new Date().toISOString(),
                date: new Date().toLocaleString(),
                scope: 'SPARE',
                type: dir === 'IMPORT' ? 'IMPORT' : 'EXPORT',
                direction: entry.direction || '',
                category: entry.category || '',
                file_name: entry.file_name || '',
                filename: entry.file_name || '',
                summary: entry.summary || '',
                count: entry.count ?? null,
                operator_name: user?.display_name || user?.username || '',
                peer: entry.peer || spareHistPeerLabel({ direction: entry.direction, peer: entry.peer }, user),
                space: window.TVC_RBAC?.isHqAccount?.(user) ? 'HQ' : 'SHIP',
                vessel_id: entry.vessel_id || st.selectedVesselId || user?.vessel_id || null,
                department: entry.department || st.department || user?.department || null,
            });
        } catch (e) { console.warn('[SPARE_XFER] log failed', e); }
    }

    async function listSpareDataXferHistory(limit = 100) {
        const st = getState();
        const user = st.user;
        let rows = await TVC_DB.getAll('sync_history').catch(() => []);
        rows = rows.filter(r => r.scope === 'SPARE');
        if (window.TVC_RBAC?.isHqAccount?.(user) && st.selectedVesselId) {
            rows = rows.filter(r => !r.vessel_id || r.vessel_id === st.selectedVesselId);
        }
        return rows
            .sort((a, b) => (b.at || '').localeCompare(a.at || ''))
            .slice(0, limit);
    }

    function spareXferCategoryLabel(cat) {
        const map = {
            REQUISITION: 'Requisition',
            QUOTATION: 'Quotation',
            REPLY_EVALUATION: 'Reply Evaluation',
            PURCHASE_ORDER: 'Purchase Order',
            RECEIVED: 'Received',
            INVENTORY: SPARE_XFER_MONTHLY_REPORT_LABEL,
            ASSESSMENT: 'Assessment',
        };
        return map[cat] || cat || '—';
    }

    function spareHistCategoryKey(row, { hq = false } = {}) {
        const c = String(row?.category || '').toUpperCase();
        if (c === 'RECEIVED') return 'received';
        if (c === 'INVENTORY') return 'inventory';
        if (c === 'REPLY_EVALUATION' || c === 'ASSESSMENT') return 'evaluation';
        if (hq) {
            if (c === 'QUOTATION') return 'quotation';
            if (c === 'PURCHASE_ORDER') return 'order';
        }
        // Vessel: Quotation / Order 이력은 Requisition 탭에 포함
        return 'requisition';
    }

    function spareHistCategoryLabel(key) {
        return {
            requisition: 'Requisition',
            quotation: 'Quotation',
            evaluation: 'Evaluation',
            order: 'Order',
            received: 'Received',
            inventory: SPARE_XFER_MONTHLY_REPORT_LABEL,
        }[key] || 'Requisition';
    }

    function spareHistTabsForUser(user) {
        if (window.TVC_RBAC?.isHqAccount?.(user)) {
            return ['requisition', 'quotation', 'evaluation', 'order', 'received', 'inventory'];
        }
        return ['requisition', 'evaluation', 'received', 'inventory'];
    }

    function spareHistNormalizeCategory(key, user) {
        const tabs = spareHistTabsForUser(user);
        return tabs.includes(key) ? key : tabs[0];
    }

    function spareHistEventDate(row) {
        if (row?.at) return String(row.at).slice(0, 10);
        const raw = String(row?.date || '');
        const m = raw.match(/(\d{4})[./-](\d{1,2})[./-](\d{1,2})/);
        if (m) return `${m[1]}-${String(m[2]).padStart(2, '0')}-${String(m[3]).padStart(2, '0')}`;
        return raw.slice(0, 10) || '—';
    }

    function spareHistAccountHint(user) {
        if (window.TVC_RBAC?.isHqAccount?.(user)) {
            return 'HQ Mode — shows SPARE Export / Import history for the vessel (Master).';
        }
        if (typeof TVC_Space !== 'undefined' && TVC_Space.isCaptainHub?.(user)) {
            return 'Hub (Captain) — shows SPARE Export / Import history with stations and Company (HQ).';
        }
        return 'Confirmer — primarily exports/imports SPARE data with Master. Company (HQ) packages are also recorded if Master PC is unavailable.';
    }

    /** Vessel SPARE: Master 기본 · HQ 직송은 Company · HQ Mode: Vessel */
    function spareHistPeerLabel(row, user) {
        if (row?.peer) return row.peer;
        if (typeof TVC_App !== 'undefined' && typeof TVC_App.menuHistPeerLabel === 'function') {
            return TVC_App.menuHistPeerLabel(row, user);
        }
        if (window.TVC_RBAC?.isHqAccount?.(user)) {
            const vid = row?.vessel_id;
            if (vid && vid !== '—') {
                const fleet = typeof TVC_Fleet !== 'undefined' ? TVC_Fleet.resolveById?.(vid) : null;
                return fleet?.name || vid;
            }
            return 'Vessel';
        }
        const d = String(row?.direction || '');
        if (/TO_HQ|HQ_TO|COMPANY|ASSESSMENT/i.test(d) && !/STATION|MASTER/i.test(d)) return 'Company';
        return 'Master';
    }

    function spareHistIsExport(row) {
        const t = String(row?.type || '').toUpperCase();
        if (t === 'EXPORT') return true;
        if (t === 'IMPORT') return false;
        return String(row?.direction || '').toUpperCase() === 'EXPORT';
    }

    function isSpareMasterHub(user) {
        return typeof TVC_Space !== 'undefined' && TVC_Space.isCaptainHub?.(user);
    }

    function renderSpareXferModal() {
        const body = document.getElementById('spareSyncBody');
        if (!body) return;
        const st = getState();
        const isHq = !!(window.TVC_RBAC?.isHqAccount?.(st.user));
        const isMaster = !isHq && isSpareMasterHub(st.user);
        const step = _spareXfer.step || 'mode';
        let content = '';
        if (step === 'mode') {
            content = `
                <p class="spare-sync-hint">Choose whether to send data out or bring data in.</p>
                <div class="spare-sync-actions">
                    <button type="button" class="btn btn-green spare-sync-btn" onclick="TVC_SpareMenu.spareXferPickMode('export')">Export</button>
                    <button type="button" class="btn spare-sync-btn" onclick="TVC_SpareMenu.spareXferPickMode('import')">Import</button>
                </div>`;
        } else if (step === 'export-type') {
            const hqExportBtns = `
                    <button type="button" class="btn spare-sync-btn" onclick="TVC_SpareMenu.spareXferOpenQuotationExportList()">Quotation</button>
                    <button type="button" class="btn spare-sync-btn" onclick="TVC_SpareMenu.spareXferOpenPurchaseOrderExportList()">Order</button>
                    <button type="button" class="btn spare-sync-btn" onclick="TVC_SpareMenu.spareXferExportInventory()">${esc(SPARE_XFER_MONTHLY_REPORT_LABEL)}</button>`;
            const vesselExportBtns = `
                    <button type="button" class="btn spare-sync-btn" onclick="TVC_SpareMenu.spareXferOpenReqExportList()">Requisition</button>
                    <button type="button" class="btn spare-sync-btn" onclick="TVC_SpareMenu.spareXferOpenReceivedExportList()">Received</button>
                    <button type="button" class="btn spare-sync-btn" onclick="TVC_SpareMenu.spareXferExportInventory()">${esc(SPARE_XFER_MONTHLY_REPORT_LABEL)}</button>`;
            content = `
                <p class="spare-sync-hint">${isHq ? 'Select the data type to export.' : isMaster ? 'Select the data type to export after import (relay to HQ / Station).' : 'Select the data type to export to Master PC.'}</p>
                <p class="spare-sync-note muted">Exports are saved as <strong>.zip</strong> packages (tvc_spare_sync.json inside), same as PMS.</p>
                <div class="spare-sync-actions">
                    ${isHq ? hqExportBtns : vesselExportBtns}
                </div>`;
        } else if (step === 'import') {
            if (isHq) {
                const hqType = _spareXfer.hqImportType || '';
                const typeBtns = HQ_IMPORT_TYPES.map(t => `
                    <button type="button" class="btn spare-sync-btn spare-sync-check-btn${hqType === t.key ? ' is-checked' : ''}"
                        aria-pressed="${hqType === t.key ? 'true' : 'false'}"
                        onclick="TVC_SpareMenu.spareXferSelectHqImportType('${t.key}')">${esc(t.label)}${hqType === t.key ? ' ✓' : ''}</button>`).join('');
                content = `
                <p class="spare-sync-hint">Select import type, then open the file.</p>
                <p class="spare-sync-note muted">Import: <strong>.zip</strong> (preferred) or legacy <strong>.xlsx</strong> · ${esc(SPARE_XFER_MONTHLY_REPORT_LABEL)} also <strong>.xls / .csv</strong></p>
                <div class="spare-sync-actions">
                    ${typeBtns}
                    <button type="button" class="btn btn-green spare-sync-btn"
                        onclick="TVC_SpareMenu.spareXferTriggerImport('hq')"
                        ${hqType ? '' : ' disabled title="Select import type first"'}>Open file…</button>
                </div>`;
            } else if (isMaster) {
                const masterType = _spareXfer.masterImportType || '';
                const typeBtns = MASTER_IMPORT_TYPES.map(t => `
                    <button type="button" class="btn spare-sync-btn spare-sync-check-btn${masterType === t.key ? ' is-checked' : ''}"
                        aria-pressed="${masterType === t.key ? 'true' : 'false'}"
                        onclick="TVC_SpareMenu.spareXferSelectMasterImportType('${t.key}')">${esc(t.label)}${masterType === t.key ? ' ✓' : ''}</button>`).join('');
                content = `
                <p class="spare-sync-hint">Select import type, then open the file.</p>
                <p class="spare-sync-note muted">Import: <strong>.zip</strong> (preferred) or legacy Order <strong>.xlsx / .json</strong> · ${esc(SPARE_XFER_MONTHLY_REPORT_LABEL)} <strong>.xls / .xlsx / .csv</strong></p>
                <div class="spare-sync-actions">
                    ${typeBtns}
                    <button type="button" class="btn btn-green spare-sync-btn"
                        onclick="TVC_SpareMenu.spareXferTriggerImport('master')"
                        ${masterType ? '' : ' disabled title="Select import type first"'}>Open file…</button>
                </div>`;
            } else {
                const vesselType = _spareXfer.vesselImportType || '';
                const typeBtns = VESSEL_IMPORT_TYPES.map(t => `
                    <button type="button" class="btn spare-sync-btn spare-sync-check-btn${vesselType === t.key ? ' is-checked' : ''}"
                        aria-pressed="${vesselType === t.key ? 'true' : 'false'}"
                        onclick="TVC_SpareMenu.spareXferSelectVesselImportType('${t.key}')">${esc(t.label)}${vesselType === t.key ? ' ✓' : ''}</button>`).join('');
                content = `
                <p class="spare-sync-hint">Select import type, then open the file.</p>
                <p class="spare-sync-note muted">Import: <strong>.zip</strong> (preferred) or legacy Order <strong>.xlsx / .json</strong> · ${esc(SPARE_XFER_MONTHLY_REPORT_LABEL)} <strong>.xls / .xlsx / .csv</strong></p>
                <div class="spare-sync-actions">
                    ${typeBtns}
                    <button type="button" class="btn btn-green spare-sync-btn"
                        onclick="TVC_SpareMenu.spareXferTriggerImport('vessel')"
                        ${vesselType ? '' : ' disabled title="Select import type first"'}>Open file…</button>
                </div>`;
            }
        }
        const backBtn = step !== 'mode'
            ? `<button type="button" class="btn btn-sm spare-sync-back" onclick="TVC_SpareMenu.spareXferBack()">← Back</button>`
            : '';
        const stepLabel = step === 'mode' ? '1. Export or Import'
            : step === 'export-type' ? '2. Export — select type'
                : '2. Import — select file';
        body.innerHTML = `
            <button type="button" class="modal-x" onclick="TVC_SpareMenu.closeSpareSyncMenu()">×</button>
            <h3 class="spare-sync-title">Data Export &amp; Import</h3>
            <p class="spare-sync-step-label muted">${esc(stepLabel)}</p>
            ${content}
            <div class="modal-actions spare-sync-footer">${backBtn}
                <button type="button" class="btn" onclick="TVC_SpareMenu.closeSpareSyncMenu()">Close</button>
            </div>`;
    }

    function openSpareSyncMenu() {
        bindFileInputs();
        resetSpareXfer();
        renderSpareXferModal();
        showSpicsModal('spareSyncModal');
    }

    function closeSpareSyncMenu() {
        closeSpicsModal('spareSyncModal');
        resetSpareXfer();
    }

    function spareXferPickMode(mode) {
        _spareXfer.mode = mode;
        _spareXfer.step = mode === 'export' ? 'export-type' : 'import';
        if (mode === 'import') {
            _spareXfer.hqImportType = null;
            _spareXfer.masterImportType = null;
            _spareXfer.vesselImportType = null;
        }
        renderSpareXferModal();
    }

    function spareXferBack() {
        if (_spareXfer.step === 'export-type' || _spareXfer.step === 'import') {
            _spareXfer.step = 'mode';
            _spareXfer.hqImportType = null;
            _spareXfer.masterImportType = null;
            _spareXfer.vesselImportType = null;
        }
        renderSpareXferModal();
    }

    function spareXferSelectVesselImportType(key) {
        const k = String(key || '');
        if (!VESSEL_IMPORT_TYPES.some(t => t.key === k)) return;
        _spareXfer.vesselImportType = _spareXfer.vesselImportType === k ? null : k;
        renderSpareXferModal();
    }

    function spareXferSelectMasterImportType(key) {
        const k = String(key || '');
        if (!MASTER_IMPORT_TYPES.some(t => t.key === k)) return;
        _spareXfer.masterImportType = _spareXfer.masterImportType === k ? null : k;
        renderSpareXferModal();
    }

    function spareXferSelectHqImportType(key) {
        const k = String(key || '');
        if (!HQ_IMPORT_TYPES.some(t => t.key === k)) return;
        _spareXfer.hqImportType = _spareXfer.hqImportType === k ? null : k;
        renderSpareXferModal();
    }

    function isSpareEvaluationImportFile(file) {
        const name = (file?.name || '').toLowerCase();
        if (!name) return false;
        if (name.endsWith('.json')) return true;
        if (name.endsWith('.xlsx') && /eval|evaluation|assessment|_order/i.test(name)) return true;
        return false;
    }

    async function spareXferTriggerImport(kind = 'general') {
        const st = getState();
        const isHq = !!(window.TVC_RBAC?.isHqAccount?.(st.user));
        const isMaster = !isHq && isSpareMasterHub(st.user);
        // Station Import: Evaluation / Inventory 선택 후 Open file
        if (!isHq && !isMaster && _spareXfer.step === 'import') {
            if (!_spareXfer.vesselImportType) {
                await TVC_Dialog.alert('Select an import type first.');
                return;
            }
            kind = _spareXfer.vesselImportType;
        }
        // Master Hub Import: Requisition / Evaluation / Received / Inventory
        if (isMaster && _spareXfer.step === 'import') {
            if (!_spareXfer.masterImportType) {
                await TVC_Dialog.alert('Select an import type first.');
                return;
            }
            kind = _spareXfer.masterImportType;
        }
        // HQ Import: 유형 선택 후 Open file
        if (isHq && _spareXfer.step === 'import') {
            if (!_spareXfer.hqImportType) {
                await TVC_Dialog.alert('Select an import type first.');
                return;
            }
            kind = _spareXfer.hqImportType;
        }
        const mode = kind || 'general';
        _spareXfer.importKind = mode;
        const fi = document.getElementById('spareXferImportFile');
        if (!fi) {
            await TVC_Dialog.alert('File picker is unavailable. Reload the app and try again.');
            return;
        }
        if (mode === 'evaluation') {
            fi.setAttribute('accept', '.zip,.json,.xlsx,application/zip,application/json,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
        } else if (mode === 'inventory') {
            fi.setAttribute('accept', '.zip,.xls,.xlsx,.csv,application/zip,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv');
        } else if (mode === 'requisition' || mode === 'quotation' || mode === 'received') {
            fi.setAttribute('accept', '.zip,.xlsx,application/zip,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
        } else {
            fi.setAttribute('accept', '.zip,.json,.xlsx,.xls,.csv,application/zip,application/json,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv');
        }
        fi.value = '';
        fi.click();
    }

    async function spareXferOpenReqExportList() {
        const st = getState();
        if (!canCreateRequisition(st)) await TVC_Dialog.alert('You do not have permission to export requisitions.');
        const m = modState(st);
        m.reqListPhaseTab = REQ_LIST_PHASE.ALL;
        _reqListXferExportKind = 'requisition';
        closeSpareSyncMenu();
        await openReqListModal({ xferExport: 'requisition' });
    }

    async function openReqXferExportList(kind, opts = {}) {
        const m = modState(getState());
        _reqListXferExportKind = kind;
        _reqListXferExportReturn = opts.returnTo || 'sync';
        m.reqListPhaseTab = REQ_LIST_PHASE.ALL;
        if (opts.selectId) applyReqListSelection(m, opts.selectId);
        await openReqListModal({ xferExport: kind, selectId: opts.selectId, checkId: opts.checkId });
    }

    async function spareXferOpenQuotationExportList() {
        const st = getState();
        if (!canCreateRequisition(st)) await TVC_Dialog.alert('You do not have permission to export quotations.');
        closeSpareSyncMenu();
        await openReqXferExportList('quotation', { returnTo: 'sync' });
    }

    async function spareXferOpenReplyEvalExportList() {
        const st = getState();
        if (!canCreateRequisition(st)) await TVC_Dialog.alert('You do not have permission to export evaluation replies.');
        closeSpareSyncMenu();
        await openReqXferExportList('reply-evaluation', { returnTo: 'sync' });
    }

    async function spareXferOpenPurchaseOrderExportList() {
        const st = getState();
        if (!canCreateRequisition(st)) await TVC_Dialog.alert('You do not have permission to export purchase orders.');
        closeSpareSyncMenu();
        await openReqXferExportList('purchase-order', { returnTo: 'sync' });
    }

    async function spareXferOpenReceivedExportList() {
        const st = getState();
        if (!canCreateDeliver(st)) await TVC_Dialog.alert('You do not have permission to export received data.');
        closeSpareSyncMenu();
        await openReqXferExportList('received', { returnTo: 'sync' });
    }

    function spareImportCategory(kind) {
        const map = {
            requisition: SPARE_XFER_EXPORT.REQUISITION,
            quotation: SPARE_XFER_EXPORT.QUOTATION,
            received: SPARE_XFER_EXPORT.RECEIVED,
            evaluation: SPARE_XFER_EXPORT.REPLY_EVALUATION,
            inventory: SPARE_XFER_EXPORT.INVENTORY,
        };
        return map[kind] || '';
    }

    function spareVesselOrderImportCategories() {
        return [SPARE_XFER_EXPORT.REPLY_EVALUATION, SPARE_XFER_EXPORT.PURCHASE_ORDER];
    }

    function isVesselOrderImportContext(importKind, category) {
        if (isReqListHqUser(getState())) return false;
        return importKind === 'evaluation'
            || spareVesselOrderImportCategories().includes(category);
    }

    async function applyVesselOrderedViewState() {
        const st = getState();
        const m = modState(st);
        const req = getReqWorkSession();
        if (!req || !isRequisitionListWindow(m) || isReqListHqUser(st)) return false;
        m.reqWorkHqQuoteView = false;
        m.reqWorkHqEvalView = false;
        const vf = ensureReqWorkVesselFlowState(_reqWorkDraft);
        vf.orderImported = true;
        if (!String(_reqWorkDraft.ordered_on || '').trim()) {
            _reqWorkDraft.ordered_on = new Date().toISOString().slice(0, 10);
        }
        reqVesselBumpMaxFlowStage(_reqWorkDraft, 'received');
        await persistReqWorkVesselDraft();
        applyReqWorkVesselStageOnLoad(_reqWorkDraft, m);
        await refreshReqWorkListUi();
        syncReqWorkFlowBtns();
        return true;
    }

    async function spareXferExportRequisitions() {
        const { st, vesselId, isHq } = await vesselScope();
        const all = await TVC_Inventory.listRequisitions(vesselId);
        const exportable = all.filter(r => reqListCanMasterExport(r));
        if (!exportable.length) await TVC_Dialog.alert('No Confirmed requisitions ready to export.');
        if (typeof TVC_SpareSync === 'undefined') await TVC_Dialog.alert('SPARE ZIP export is not available.');
        if (!await TVC_Dialog.confirm({ message: `Export ${exportable.length} requisition(s) to Master PC?` })) return;
        try {
            const { filename } = await TVC_SpareSync.exportRequisitionsZip(st.user, exportable, {
                category: SPARE_XFER_EXPORT.REQUISITION,
                vendorOnly: !isHq,
                isHq,
            });
            for (const req of exportable) {
                await applyRequisitionExportStatus(req);
            }
            await logSpareDataXfer({
                direction: 'EXPORT', category: SPARE_XFER_EXPORT.REQUISITION,
                summary: `${exportable.length} requisition(s) → ${filename}`,
                count: exportable.length,
                file_name: filename,
            });
            closeSpareSyncMenu();
            await refreshReqListModalIfOpen();
            render();
            await TVC_Dialog.alert(`Exported ${exportable.length} requisition(s).\n${filename}`);
        } catch (e) { await TVC_Dialog.alert(e.message || e.code); }
    }

    async function spareXferExportReceived() {
        const st = getState();
        if (!canCreateDeliver(st)) await TVC_Dialog.alert('You do not have permission to export received data.');
        const { vesselId, isHq } = await vesselScope();
        const reqs = (await TVC_Inventory.listRequisitions(vesselId))
            .filter(r => reqListCanReceivedExport(r));
        if (!reqs.length) await TVC_Dialog.alert('No received requisitions to export.');
        if (typeof TVC_SpareSync === 'undefined') await TVC_Dialog.alert('SPARE ZIP export is not available.');
        if (!await TVC_Dialog.confirm({ message: `Export ${reqs.length} received requisition(s) to Master PC?` })) return;
        try {
            const { filename } = await TVC_SpareSync.exportRequisitionsZip(st.user, reqs, {
                category: SPARE_XFER_EXPORT.RECEIVED,
                vendorOnly: !isHq,
                isHq,
            });
            if (!isHq) {
                for (const req of reqs) {
                    const vf = req.vessel_flow || {};
                    req.vessel_flow = vf;
                    vf.receivedExported = true;
                    vf.flowStage = 'received-export';
                    await TVC_Inventory.saveRequisition(req);
                }
            }
            await logSpareDataXfer({
                direction: 'EXPORT', category: SPARE_XFER_EXPORT.RECEIVED,
                summary: `${reqs.length} received requisition(s) → ${filename}`,
                count: reqs.length,
                file_name: filename,
            });
            closeSpareSyncMenu();
            await TVC_Dialog.alert(`Exported ${reqs.length} received requisition(s).\n${filename}`);
        } catch (e) { await TVC_Dialog.alert(e.message || e.code); }
    }

    async function spareXferExportInventory() {
        if (typeof TVC_License !== 'undefined') {
            await TVC_License.refresh();
            const st = getState();
            const vesselId = window.TVC_RBAC?.isHqAccount?.(st.user)
                ? st.selectedVesselId
                : (await TVC_DB.getMeta(TVC_META_KEYS.VESSEL_ID));
            const lic = TVC_License.assertExportImport(
                vesselId,
                TVC_License.statusSync()?.companyId || TVC_License.COMPANY_ID
            );
            if (!lic.ok) {
                await TVC_Dialog.alert(lic.error || `License does not allow ${SPARE_XFER_MONTHLY_REPORT_LABEL} export.`);
                return;
            }
        }
        const { st, vesselId, isHq } = await vesselScope();
        const spares = (getState().spares || []).map(canon);
        if (!spares.length) {
            await TVC_Dialog.alert('No parts to export.');
            return;
        }
        if (typeof TVC_SpareSync === 'undefined') {
            await TVC_Dialog.alert('SPARE ZIP export is not available.');
            return;
        }
        const previewFilename = await TVC_SpareSync.resolveExportFilename(st.user, SPARE_XFER_EXPORT.INVENTORY, {
            vessel_id: vesselId,
            department: st.department,
            isHq,
        });
        if (!await TVC_Dialog.confirm({
            message: `Export ${spares.length} spare part(s) as ${SPARE_XFER_MONTHLY_REPORT_LABEL}?\n\n${previewFilename}`,
        })) return;
        try {
            const { filename } = await TVC_SpareSync.exportInventoryZip(st.user, spares, {
                vessel_id: vesselId,
                department: st.department,
                isHq,
                filename: previewFilename,
            });
            await logSpareDataXfer({
                direction: 'EXPORT', category: SPARE_XFER_EXPORT.INVENTORY,
                summary: `${spares.length} part(s) exported (ZIP)`, count: spares.length,
                file_name: filename,
            });
            closeSpareSyncMenu();
            await TVC_Dialog.alert(`Exported ${spares.length} part(s).\n${filename}`);
        } catch (e) {
            await TVC_Dialog.alert(e.message || e.code || String(e));
        }
    }

    async function spareXferImportRequisitionExcel(file, opts = {}) {
        const { vesselId, isHq } = await vesselScope();
        const importAsVendor = _reqImportMode === 'vendor-quote';
        const parsed = importAsVendor && TVC_Excel?.parseVendorQuoteFile
            ? await TVC_Excel.parseVendorQuoteFile(file)
            : null;
        const rows = parsed?.rows || await TVC_Excel.parseRequisitionFile(file);
        let req = null;
        if (_importReqId) req = await TVC_Inventory.getRequisition(_importReqId);
        if (!req) {
            const all = await TVC_Inventory.listRequisitions(vesselId);
            const reqNoFromName = (file.name || '').match(/REQ[-\w]+/i)?.[0]
                || (file.name || '').match(/([A-Z]{2,5}-\d{2}-[A-Z]-[A-Z]{2}-\d{3})/i)?.[0];
            req = reqNoFromName ? all.find(r => String(r.req_no).toUpperCase() === reqNoFromName.toUpperCase()) : null;
            if (!req) {
                const candidates = all.filter(r => spareListStatus(r) !== SPARE_LIST_STATUS.DRAFT);
                req = candidates.sort((a, b) => (b.created_at || '').localeCompare(a.created_at || ''))[0];
            }
        }
        if (!req) throw new Error('No matching requisition found. Create and complete a requisition first.');
        const vesselOrderExcel = !isHq && (_spareXfer.importKind === 'evaluation' || /_order\.xlsx$/i.test(file.name || ''));
        if (vesselOrderExcel) _reqImportMode = 'hq-adjustment';
        const importAsHq = _reqImportMode === 'hq-adjustment' || (_reqImportMode !== 'vendor-quote' && isHq);
        const res = importAsVendor
            ? await applyHqVendorQuoteImport(req.id, rows, {
                vendorName: parsed?.vendorName || vendorNameFromQuoteImportFile(file.name),
                fileName: file.name,
                vendorMeta: parsed ? {
                    vendorName: parsed.vendorName,
                    refNo: parsed.refNo,
                    quotedDate: parsed.quotedDate,
                    comments: parsed.comments,
                    field16: parsed.field16,
                    field17: parsed.field17,
                    totalAmount: parsed.totalAmount,
                    currency: parsed.currency,
                } : null,
            })
            : vesselOrderExcel && TVC_Inventory?.applyVesselOrderImport
                ? await TVC_Inventory.applyVesselOrderImport(req.id, { lines: rows })
            : importAsHq
                ? await TVC_Inventory.applyHqAdjustment(req.id, rows)
                : await TVC_Inventory.applyVendorQuote(req.id, rows);
        req = res.req || await TVC_Inventory.getRequisition(req.id);
        _reqImportMode = null;
        _importReqId = null;
        const dbRes = await TVC_Inventory.applyExcelImport(rows, req.req_no);
        await logSpareDataXfer({
            direction: 'IMPORT',
            category: opts.category || SPARE_XFER_EXPORT.REQUISITION,
            file_name: file.name,
            summary: opts.summary || `Applied to ${req.req_no}: ${res.updated}/${res.total} lines`,
            count: res.updated,
            peer: opts.peer,
        });
        closeSpareSyncMenu();
        await refresh();
        await refreshReqListModalIfOpen();
        render();
        if (isRequisitionListWindow(modState(getState())) && String(_reqWorkDraft?.id) === String(req.id)) {
            await loadRequisitionIntoListWindow(req.id, { preserveHistPopover: true });
            if (opts.category === SPARE_XFER_EXPORT.RECEIVED && isReqListHqUser(getState())) {
                await applyHqReceivedViewState();
            } else if ((importAsVendor || opts.category === SPARE_XFER_EXPORT.QUOTATION) && isReqListHqUser(getState())) {
                await applyHqEvaluationViewState();
            } else if (isReqListHqUser(getState()) && (opts.category === SPARE_XFER_EXPORT.REQUISITION || !importAsVendor)) {
                applyReqWorkHqStageOnLoad(_reqWorkDraft, modState(getState()));
                syncReqWorkFlowBtns();
            } else if (isVesselOrderImportContext(_spareXfer.importKind || 'evaluation', opts.category)) {
                await applyVesselOrderedViewState();
            } else {
                syncReqWorkFlowBtns();
            }
        }
        await TVC_Dialog.alert(`Import applied to ${req.req_no}: ${res.updated}/${res.total} lines · DB ${dbRes.updated}/${dbRes.total}`);
    }

    async function spareXferImportZip(file, importKind) {
        const { st, isHq } = await vesselScope();
        if (typeof TVC_SpareSync === 'undefined') throw new Error('SPARE ZIP import is not available.');
        const vesselOrderImport = !isHq && importKind === 'evaluation';
        let importMode = null;
        if (_reqImportMode === 'vendor-quote' || importKind === 'quotation') importMode = 'vendor-quote';
        else if (vesselOrderImport) importMode = 'vessel-order';
        else if (_reqImportMode === 'hq-adjustment') importMode = 'hq-adjustment';
        const importOpts = { importMode };
        if (vesselOrderImport) {
            importOpts.expectedCategories = spareVesselOrderImportCategories();
        } else {
            const expected = spareImportCategory(importKind);
            if (expected) importOpts.expectedCategory = expected;
        }
        const result = await TVC_SpareSync.importZip(st.user, file, importOpts);
        const category = result.category || spareImportCategory(importKind) || 'SPARE';
        const importedReqs = result.payload?.requisitions || [];
        await logSpareDataXfer({
            direction: 'IMPORT',
            category,
            file_name: file.name,
            summary: `Imported ${result.updated} record(s) from ZIP`,
            count: result.updated,
        });
        _reqImportMode = null;
        _importReqId = null;
        closeSpareSyncMenu();
        await reloadSparesCache();
        await refresh();
        await refreshReqListModalIfOpen();
        render();
        const m = modState(getState());
        if (importedReqs.length) {
            const target = importedReqs.find(r => String(r.id) === String(_reqWorkDraft?.id)) || importedReqs[0];
            if (target?.id && (isRequisitionListWindow(m) || m.reqListOpen)) {
                if (isRequisitionListWindow(m)) {
                    await loadRequisitionIntoListWindow(target.id, { preserveHistPopover: true });
                    if ((importKind === 'received' || category === SPARE_XFER_EXPORT.RECEIVED) && isReqListHqUser(getState())) {
                        await applyHqReceivedViewState();
                    } else if ((importKind === 'quotation' || category === SPARE_XFER_EXPORT.QUOTATION || importMode === 'vendor-quote') && isReqListHqUser(getState())) {
                        await applyHqEvaluationViewState();
                    } else if (isVesselOrderImportContext(importKind, category)) {
                        await applyVesselOrderedViewState();
                    } else {
                        syncReqWorkFlowBtns();
                    }
                } else if (m.reqListOpen) {
                    applyReqListSelection(m, target.id);
                }
            }
        }
        await TVC_Dialog.alert(`Import complete: ${result.updated} record(s) from ${file.name}`);
    }

    async function onSpareXferImportFile(file) {
        if (!file) return;
        const name = (file.name || '').toLowerCase();
        const importKind = _spareXfer.importKind || 'general';
        try {
            if (name.endsWith('.zip')) {
                await spareXferImportZip(file, importKind);
                return;
            }

            if (importKind === 'evaluation') {
                if (!isSpareEvaluationImportFile(file)) {
                    await TVC_Dialog.alert('Only order/evaluation files can be uploaded.\n· HQ Order .zip\n· *_ORDER.xlsx / *_EVAL_REPLY.xlsx\n· Assessment .json');
                    return;
                }
                if (name.endsWith('.json')) {
                    _hqAssessment = await TVC_InventoryService.diffHqImport(JSON.parse(await file.text()));
                    await logSpareDataXfer({
                        direction: 'IMPORT', category: 'ASSESSMENT',
                        file_name: file.name,
                        summary: `Evaluation/Assessment loaded (${_hqAssessment.summary?.total || 0} change(s))`,
                        count: _hqAssessment.summary?.total || 0,
                        peer: 'Company',
                    });
                    closeSpareSyncMenu();
                    openAssessmentModal();
                    return;
                }
                const orderExcel = /_order\.xlsx$/i.test(name);
                if (!isReqListHqUser(getState())) _reqImportMode = 'hq-adjustment';
                await spareXferImportRequisitionExcel(file, {
                    category: orderExcel ? SPARE_XFER_EXPORT.PURCHASE_ORDER : SPARE_XFER_EXPORT.REPLY_EVALUATION,
                    summary: orderExcel ? 'Order imported' : 'Reply Evaluation imported',
                    peer: 'Company',
                });
                return;
            }

            if (importKind === 'requisition') {
                if (!name.endsWith('.xlsx')) {
                    await TVC_Dialog.alert('Requisition Import accepts .xlsx files only.');
                    return;
                }
                if (window.TVC_RBAC?.isHqAccount?.(getState().user)) {
                    _reqImportMode = 'hq-adjustment';
                }
                await spareXferImportRequisitionExcel(file, {
                    category: SPARE_XFER_EXPORT.REQUISITION,
                    summary: 'Requisition imported',
                });
                return;
            }

            if (importKind === 'quotation') {
                if (!name.endsWith('.xlsx')) {
                    await TVC_Dialog.alert('Quotation Import accepts .xlsx files only.');
                }
                _reqImportMode = 'vendor-quote';
                await spareXferImportRequisitionExcel(file, {
                    category: SPARE_XFER_EXPORT.QUOTATION,
                    summary: 'Quotation imported',
                });
                return;
            }

            if (importKind === 'received') {
                if (!name.endsWith('.xlsx')) {
                    await TVC_Dialog.alert('Received Import accepts .xlsx files only.');
                }
                await spareXferImportRequisitionExcel(file, {
                    category: SPARE_XFER_EXPORT.RECEIVED,
                    summary: 'Received data imported',
                });
                return;
            }

            if (importKind === 'inventory') {
                if (!(name.endsWith('.csv') || name.endsWith('.xls') || name.endsWith('.xlsx'))) {
                    await TVC_Dialog.alert(`${SPARE_XFER_MONTHLY_REPORT_LABEL} Import accepts .xls, .xlsx, or .csv files only.`);
                }
                await onInventoryImportFile(file);
                await logSpareDataXfer({
                    direction: 'IMPORT', category: SPARE_XFER_EXPORT.INVENTORY,
                    file_name: file.name,
                    summary: `${SPARE_XFER_MONTHLY_REPORT_LABEL} file imported`,
                });
                closeSpareSyncMenu();
                return;
            }

            if (name.endsWith('.json')) {
                _hqAssessment = await TVC_InventoryService.diffHqImport(JSON.parse(await file.text()));
                await logSpareDataXfer({
                    direction: 'IMPORT', category: 'ASSESSMENT',
                    file_name: file.name,
                    summary: `Assessment loaded (${_hqAssessment.summary?.total || 0} change(s))`,
                    count: _hqAssessment.summary?.total || 0,
                });
                closeSpareSyncMenu();
                openAssessmentModal();
                return;
            }
            if (name.endsWith('.csv') || name.endsWith('.xls')) {
                await onInventoryImportFile(file);
                await logSpareDataXfer({
                    direction: 'IMPORT', category: SPARE_XFER_EXPORT.INVENTORY,
                    file_name: file.name,
                    summary: `${SPARE_XFER_MONTHLY_REPORT_LABEL} file imported`,
                });
                closeSpareSyncMenu();
                return;
            }
            if (name.endsWith('.xlsx')) {
                if (/inventory|spare/i.test(name)) {
                    await onInventoryImportFile(file);
                    await logSpareDataXfer({
                        direction: 'IMPORT', category: SPARE_XFER_EXPORT.INVENTORY,
                        file_name: file.name,
                        summary: `${SPARE_XFER_MONTHLY_REPORT_LABEL} file imported`,
                    });
                    closeSpareSyncMenu();
                } else {
                    await spareXferImportRequisitionExcel(file);
                }
                return;
            }
            await TVC_Dialog.alert(`Unsupported file type. Use .xlsx (Requisition), .json (Assessment), or .xls/.csv (${SPARE_XFER_MONTHLY_REPORT_LABEL}).`);
        } catch (e) {
            await TVC_Dialog.alert('Import failed: ' + (e.message || e.code));
        } finally {
            _reqImportMode = null;
            _importReqId = null;
            _spareXfer.importKind = 'general';
            const fi = document.getElementById('spareXferImportFile');
            if (fi) fi.value = '';
        }
    }

    // ── SPARE workflow menu (4 columns) ────────────────────────────────
    /** 작성자(Engineer / Officer) — Data Export·History·Inventory Update 숨김 */
    function isSpareAuthorAccount(user) {
        if (!user || !window.TVC_RBAC) return false;
        const role = TVC_RBAC.resolveUserRole?.(user) || user.role;
        return role === TVC_RBAC.Role.SHIP_OFFICER;
    }

    function renderSpareNecessaryCol({ canModify, user }) {
        const item = (label, onclick, enabled = true, primary = false) =>
            enabled
                ? `<button type="button" class="spare-flow-item${primary ? ' primary' : ''}" onclick="${onclick}">${esc(label)}</button>`
                : `<button type="button" class="spare-flow-item" disabled title="No permission">${esc(label)}</button>`;
        const col = (tone, title, buttons) => `
          <section class="spare-flow-col tone-${tone}">
            <header class="spare-flow-head">${esc(title)}</header>
            <div class="spare-flow-items">${buttons}</div>
          </section>`;
        const author = isSpareAuthorAccount(user);
        const buttons = [
            item('Database Backup & Restore', "TVC_App.openMasterBackupModal('spare')", true),
            ...(author ? [] : [
                item('Data Export & Import', 'TVC_SpareMenu.openSpareSyncMenu()', true),
                item('View Data History', 'TVC_SpareMenu.openHistoryModal()', true),
            ]),
        ];
        return col('necessary', 'If Necessary', buttons.join(''));
    }

    async function hqRequestQuotation() {
        const { st, vesselId } = await vesselScope();
        const all = await TVC_Inventory.listRequisitions(vesselId);
        const exportable = all.filter(r => reqListCanExport(r));
        if (!exportable.length) await TVC_Dialog.alert('No requisitions ready for quotation request.');
        if (typeof TVC_SpareSync === 'undefined') await TVC_Dialog.alert('SPARE ZIP export is not available.');
        if (!await TVC_Dialog.confirm({ message: `Export ${exportable.length} requisition(s) for vendor quotation?` })) return;
        try {
            const { filename } = await TVC_SpareSync.exportRequisitionsZip(st.user, exportable, {
                category: SPARE_XFER_EXPORT.REQUISITION,
                vendorOnly: true,
                isHq: true,
            });
            await TVC_Dialog.alert(`Exported ${exportable.length} requisition(s) for vendor quotation.\n${filename}`);
        } catch (e) { await TVC_Dialog.alert(e.message || e.code); }
    }

