    function spareHistInvRowConsumeLogStub(h) {
        if (h.source_type === 'defect_case') return { defect_case_id: h.source_id, source: 'defect' };
        if (h.source_type === 'work_report') return { work_report_id: h.source_id, source: 'work_report' };
        if (h.source_type === 'consume_log') return { id: h.source_id, source: 'consumption_list' };
        return { source: String(h.source_type || '') };
    }

    function spareHistReqLineVendor(req, line) {
        const q = req?.hq_quote;
        const sid = reqWorkSpareIdKey(line?.spare_part_id);
        if (q && sid) {
            const vendors = reqWorkQuoteVendors(req);
            for (let slot = 0; slot < vendors.length; slot++) {
                const key = reqWorkQuoteVendorKey(slot, sid);
                if (q.rowChecks?.[key]) {
                    const name = String(vendors[slot]?.vendorName || '').trim();
                    if (name) return name;
                }
            }
            for (let slot = 0; slot < vendors.length; slot++) {
                const key = reqWorkQuoteVendorKey(slot, sid);
                const price = Number(q.prices?.[key]);
                if (Number.isFinite(price)) {
                    const name = String(vendors[slot]?.vendorName || '').trim();
                    if (name) return name;
                }
            }
        }
        const info = reqWorkExportVendorInfo(req);
        return String(info?.vendorName || '').trim() || '—';
    }

    function spareHistReqLineCurrency(req, line) {
        const q = req?.hq_quote;
        const sid = reqWorkSpareIdKey(line?.spare_part_id);
        if (q && sid) {
            const vendors = reqWorkQuoteVendors(req);
            for (let slot = 0; slot < vendors.length; slot++) {
                const key = reqWorkQuoteVendorKey(slot, sid);
                if (q.rowChecks?.[key]) {
                    const cur = String(vendors[slot]?.currency || '').trim();
                    if (cur) return cur;
                }
            }
            for (let slot = 0; slot < vendors.length; slot++) {
                const key = reqWorkQuoteVendorKey(slot, sid);
                const price = Number(q.prices?.[key]);
                if (Number.isFinite(price)) {
                    const cur = String(vendors[slot]?.currency || '').trim();
                    if (cur) return cur;
                }
            }
        }
        const info = reqWorkExportVendorInfo(req);
        return String(info?.currency || '').trim() || '—';
    }

    function spareHistReqLineUnitPrice(req, line) {
        const q = req?.hq_quote;
        const sid = reqWorkSpareIdKey(line?.spare_part_id);
        if (q && sid) {
            const vendors = reqWorkQuoteVendors(req);
            for (let slot = 0; slot < vendors.length; slot++) {
                const key = reqWorkQuoteVendorKey(slot, sid);
                if (q.rowChecks?.[key]) {
                    const price = Number(q.prices?.[key]);
                    if (Number.isFinite(price)) return price;
                }
            }
            for (let slot = 0; slot < vendors.length; slot++) {
                const key = reqWorkQuoteVendorKey(slot, sid);
                const price = Number(q.prices?.[key]);
                if (Number.isFinite(price)) return price;
            }
        }
        const linePrice = Number(line?.price);
        if (Number.isFinite(linePrice)) return linePrice;
        return null;
    }

    function spareHistDateCell(val) {
        const d = fmtSpareDate(val) || String(val || '').slice(0, 10);
        return esc(d || '—');
    }

    function spareHistConsumeEventKey(date, jobCode, cos) {
        const d = String(date || '').slice(0, 10);
        const j = String(jobCode || '—').trim();
        const q = Number(cos) || 0;
        return `${d}|${j}|${q}`;
    }

    function spareHistConsumeEntryScore(entry) {
        let score = 0;
        if (entry.openLog && entry.logId && entry.log?.id) score += 8;
        if (entry.pmsGroup && entry.pmsGroup !== '—') score += 4;
        if (entry.log?.stock_applied_at) score += 3;
        const status = String(entry.status || '');
        if (status && status !== 'Draft' && !status.startsWith('Consumed:')) score += 2;
        if (status.startsWith('Consumed:')) score += 1;
        if (status === 'Draft') score -= 5;
        return score;
    }

    function dedupeSpareHistConsumeEntries(list) {
        const byKey = new Map();
        (list || []).forEach(entry => {
            const key = spareHistConsumeEventKey(entry.date, entry.jobCode, entry.cos);
            const prev = byKey.get(key);
            if (!prev || spareHistConsumeEntryScore(entry) > spareHistConsumeEntryScore(prev)) {
                byKey.set(key, entry);
            }
        });
        return Array.from(byKey.values());
    }

    async function loadSpareItemHistoryData(spareId, vesselId) {
        const sid = String(spareId);
        let consumed = [];
        const seenConsumeLog = new Set();
        const seenWorkReport = new Set();
        const seenDefectCase = new Set();

        try {
            const logs = await TVC_Inventory.listConsumeLogs(vesselId);
            logs.forEach(log => {
                seenConsumeLog.add(log.id);
                if (log.work_report_id) seenWorkReport.add(log.work_report_id);
                if (log.defect_case_id) seenDefectCase.add(log.defect_case_id);
                (log.lines || []).forEach(line => {
                    if (String(line.spare_part_id) !== sid) return;
                    const jobs = consumeLogJobItems(log);
                    consumed.push({
                        date: log.made_on || log.consumed_date || (log.created_at || '').slice(0, 10),
                        cos: Number(line.qty ?? line.qty_consumed) || 0,
                        logId: log.id,
                        log,
                        pmsGroup: safeTreeLabel(log.pms_group_no || '') || '—',
                        jobCode: log.job_code || jobs[0]?.job_code || '—',
                        status: spareListStatus(log) || log.list_status || '—',
                        openLog: true,
                    });
                });
            });
        } catch (_) { /* noop */ }

        try {
            const invRows = await TVC_InventoryService.getHistory({ spare_part_id: spareId, limit: 300 });
            invRows.forEach(h => {
                if (h.tx_type === TVC_INVENTORY_TX.DELIVERY) return;
                if (h.tx_type !== TVC_INVENTORY_TX.CONSUMPTION) return;
                if (h.source_id && seenConsumeLog.has(h.source_id)) return;
                if (h.source_type === 'work_report' && h.source_id && seenWorkReport.has(h.source_id)) return;
                if (h.source_type === 'defect_case' && h.source_id && seenDefectCase.has(h.source_id)) return;
                consumed.push({
                    date: h.date || (h.at || '').slice(0, 10),
                    cos: Math.abs(Number(h.qty_delta) || 0),
                    logId: h.source_type === 'consume_log' ? (h.source_id || '') : '',
                    log: spareHistInvRowConsumeLogStub(h),
                    pmsGroup: '—',
                    jobCode: h.ref || '—',
                    status: h.note || h.tx_type || '—',
                    openLog: !!(h.source_id && h.source_type === 'consume_log'),
                });
            });
        } catch (_) { /* noop */ }

        consumed = dedupeSpareHistConsumeEntries(consumed);

        const requisitions = [];
        try {
            const reqs = await TVC_Inventory.listRequisitions(vesselId);
            reqs.forEach(req => {
                (req.lines || []).forEach(line => {
                    if (String(line.spare_part_id) !== sid) return;
                    requisitions.push({
                        reqId: req.id,
                        req,
                        line,
                        reqNo: req.req_no || '—',
                        date: reqListReportedDate(req) || (req.created_at || '').slice(0, 10),
                        typeLabel: reqListTypeLabel(req),
                        typeCls: reqListTypeCellClass(req),
                        status: reqListStatusLabel(req),
                        qtyRequested: Number(line.qty_requested) || 0,
                        qtyReceived: Number(line.qty_received) || 0,
                        vendor: spareHistReqLineVendor(req, line),
                        currency: spareHistReqLineCurrency(req, line),
                        unitPrice: spareHistReqLineUnitPrice(req, line),
                    });
                });
            });
        } catch (_) { /* noop */ }

        const sortDesc = (a, b) => String(b.date || '').localeCompare(String(a.date || ''));
        consumed.sort(sortDesc);
        requisitions.sort(sortDesc);
        return { consumed, requisitions };
    }

    /** Spare History — local cache, requisition line snapshot, or req-work list row */
    function resolveSpareForItemHistory(st, spareId) {
        const key = reqWorkSpareIdKey(spareId);
        if (!key) return null;
        const cached = (st.spares || []).map(canon).find(s => reqWorkSameSpareId(s.id, key));
        if (cached) return cached;
        const m = modState(st);
        if (m.reqWorkOpen) {
            for (const s of filteredReqWorkSpares(st)) {
                if (reqWorkSameSpareId(s.id, key)) return canon(s);
            }
            const req = getReqWorkSession();
            for (const line of normalizeReqLines(req?.lines)) {
                const lineSpare = spareForReqLine(st, line);
                if (reqWorkSameSpareId(lineSpare.id, key) || reqLineSpareKey(line) === key) {
                    return canon(lineSpare);
                }
            }
        }
        return null;
    }

    /** Inventory / requisition history queries — prefer persisted spare_part_id on req line */
    function spareItemHistoryDataId(st, spareId) {
        const key = reqWorkSpareIdKey(spareId);
        const m = modState(st);
        if (m.reqWorkOpen) {
            const req = getReqWorkSession();
            for (const line of normalizeReqLines(req?.lines)) {
                const lineSpare = spareForReqLine(st, line);
                if (!reqWorkSameSpareId(lineSpare.id, key) && reqLineSpareKey(line) !== key) continue;
                const sid = reqWorkSpareIdKey(line.spare_part_id);
                if (sid && !sid.startsWith('line-')) return sid;
                break;
            }
        }
        const spare = resolveSpareForItemHistory(st, spareId);
        return reqWorkSpareIdKey(spare?.id || spareId);
    }

    async function spareItemHistoryVesselId(st) {
        const m = modState(st);
        const reqVid = _reqWorkDraft?.vessel_id || getReqWorkSession()?.vessel_id;
        if (m.reqWorkOpen && reqVid) return reqVid;
        const { vesselId } = await vesselScope();
        return vesselId;
    }

    async function openSpareItemHistory(spareId, tab) {
        const st = getState();
        const m = modState(st);
        const reqVid = _reqWorkDraft?.vessel_id || getReqWorkSession()?.vessel_id;
        if (m.reqWorkOpen && reqVid) {
            await reloadSparesCache({ vesselId: reqVid });
        }
        let spare = resolveSpareForItemHistory(st, spareId);
        if (!spare && reqVid) {
            await reloadSparesCache({ vesselId: reqVid, force: true });
            spare = resolveSpareForItemHistory(getState(), spareId);
        }
        if (!spare) {
            await TVC_Dialog.alert('Spare part not found.');
            return;
        }
        const resolvedId = reqWorkSpareIdKey(spare.id);
        setFocusedSpareId(st, resolvedId);
        syncSpareItemHistoryBtns();
        if (_shSpareId !== resolvedId) {
            _shTab = 'note';
            _shEditing = false;
        }
        _shSpareId = resolvedId;
        if (tab === 'received') tab = 'consumed';
        if (tab) _shTab = tab;
        await renderSpareItemHistoryModal(true);
        showSpicsModal('spareItemHistoryModal');
        syncSpareItemHistoryModalStack();
    }

    function setSpareItemHistoryTab(tab) {
        if (tab === 'received') tab = 'consumed';
        if (tab !== 'note') _shEditing = false;
        _shTab = tab;
        rerenderSpareItemHistoryModal();
    }

    function closeSpareItemHistoryModal() {
        _shEditing = false;
        _shHistoryData = null;
        _shHistoryCacheKey = '';
        closeSpicsModal('spareItemHistoryModal');
        syncSpareItemHistoryModalStack();
    }

    async function enterSpareItemNoteEdit() {
        const st = getState();
        if (!canModifySpare(st)) {
            await TVC_Dialog.alert(spareItemNoteEditDeniedMessage());
            return;
        }
        _shEditing = true;
        rerenderSpareItemHistoryModal();
        requestAnimationFrame(() => document.getElementById('shNoteInput')?.focus());
    }

    function cancelSpareItemNoteEdit() {
        _shEditing = false;
        rerenderSpareItemHistoryModal();
    }

    async function saveSpareItemNote() {
        const st = getState();
        if (!_shSpareId) return;
        if (!canModifySpare(st)) {
            await TVC_Dialog.alert(spareItemNoteEditDeniedMessage());
            return;
        }
        const text = String(document.getElementById('shNoteInput')?.value ?? '').trim();
        if (typeof TVC_SpareMeta !== 'undefined') {
            TVC_SpareMeta.setNote(_shSpareId, text);
        }
        _shEditing = false;
        rerenderSpareItemHistoryModal();
        await TVC_Dialog.success('Note saved.');
    }

    async function uploadSpareItemNoteAttachment() {
        const st = getState();
        if (!canModifySpare(st) || _shTab !== 'note' || !_shSpareId) return;
        const input = document.getElementById('shNoteAttachInput');
        if (!input?.files?.length || typeof TVC_SpareMeta === 'undefined') return;
        for (const f of input.files) await TVC_SpareMeta.addAttachment(_shSpareId, f);
        input.value = '';
        rerenderSpareItemHistoryModal();
    }

    function removeSpareItemNoteAttachment(attachmentId) {
        const st = getState();
        if (!canModifySpare(st) || _shTab !== 'note' || !_shSpareId) return;
        if (typeof TVC_SpareMeta === 'undefined') return;
        TVC_SpareMeta.removeAttachment(_shSpareId, attachmentId);
        rerenderSpareItemHistoryModal();
    }

