    async function renderSpareHistoryModal() {
        const body = document.getElementById('spareHistoryBody');
        if (!body) return;
        const st = getState();
        const user = st.user;
        const isHq = !!(window.TVC_RBAC?.isHqAccount?.(user));
        const all = await listSpareDataXferHistory(120);
        const tabKeys = spareHistTabsForUser(user);
        const cat = spareHistNormalizeCategory(_spareHistCategory, user);
        _spareHistCategory = cat;
        const rows = all.filter(r => spareHistCategoryKey(r, { hq: isHq }) === cat);
        const tabs = tabKeys.map(key => `
            <button type="button" class="menu-hist-cat${cat === key ? ' active' : ''}"
                onclick="TVC_SpareMenu.setSpareHistCategory('${key}')">${esc(spareHistCategoryLabel(key))}</button>`).join('');
        const tbody = rows.map(r => {
            const dt = spareHistEventDate(r);
            const isExport = spareHistIsExport(r);
            const peer = spareHistPeerLabel(r, user);
            const fn = (typeof TVC_Filename !== 'undefined' && TVC_Filename.histResolve)
                ? TVC_Filename.histResolve(r)
                : String(r.filename || r.file_name || '').trim();
            const fileCell = fn
                ? `<span class="menu-hist-file-text" title="${escAttr(fn)}">${esc(fn)}</span>`
                : '<span class="muted">—</span>';
            return `<tr>
                <td class="menu-hist-exp">${isExport ? esc(dt) : ''}</td>
                <td class="menu-hist-imp">${isExport ? '' : esc(dt)}</td>
                <td class="menu-hist-dir">${esc(peer)}</td>
                <td class="menu-hist-file">${fileCell}</td>
            </tr>`;
        }).join('') || `<tr><td colspan="4" class="muted" style="text-align:center">No ${esc(spareHistCategoryLabel(cat))} history yet.</td></tr>`;

        body.innerHTML = `
            <button type="button" class="modal-x" onclick="TVC_SpareMenu.closeHistoryModal()">×</button>
            <h3 class="spare-sync-title">Data Export &amp; Import History</h3>
            <p class="spare-hist-sub muted">${esc(spareHistAccountHint(user))}</p>
            <div class="menu-hist-cats${isHq ? ' menu-hist-cats-hq' : ''}" role="tablist">${tabs}</div>
            <div class="spics-tx-lines-wrap menu-hist-table-wrap">
                <table class="spics-tx-table spics-hist-table menu-hist-table">
                    <colgroup>
                        <col class="menu-hist-col-exp">
                        <col class="menu-hist-col-imp">
                        <col class="menu-hist-col-dir">
                        <col class="menu-hist-col-file">
                    </colgroup>
                    <thead><tr>
                        <th>Export</th>
                        <th>Import</th>
                        <th>Direction</th>
                        <th class="menu-hist-file-h">File Name</th>
                    </tr></thead>
                    <tbody>${tbody}</tbody>
                </table>
            </div>
            <div class="modal-actions">
                <button type="button" class="btn" onclick="TVC_SpareMenu.closeHistoryModal()">Close</button>
            </div>`;
    }

    async function vesselLabel(vesselId, dept) {
        const fleet = (window.TVC_Fleet && TVC_Fleet.getAll) ? await TVC_Fleet.getAll() : [];
        const v = fleet.find(x => x.id === vesselId);
        const d = dept ? ` (${dept.charAt(0) + dept.slice(1).toLowerCase()})` : '';
        return v ? `${v.name}${d}` : `${vesselId || 'Vessel'}${d}`;
    }

