    function buildReqLine(spare, qty) {
        const c = canon(spare);
        const q = (qty === 0 || qty === '0')
            ? 0
            : (Number(qty) || TVC_Inventory.recommendedOrderQty(c) || 1);
        return {
            spare_part_id: c.id || spare.id,
            part_no: partNo(c) || spare.part_no || '',
            universal_code: c.universalItemCode || spare.universal_code || '',
            name: c.name || spare.name || '',
            unit: spare.unit || 'EA',
            maker: spare.maker || '',
            model: spare.model || '',
            qty_on_hand: TVC_Inventory.currentStock(spare),
            standard_stock: TVC_Inventory.standardStock(c),
            qty_required: q,
            qty_requested: q,
            on_order: reportedWaitQty(c),
            price: spare.price != null ? spare.price : null,
            currency: spare.currency || 'USD',
            vendor_comment: '',
            hq_comment: '',
            equipment: equipmentFromSpare(spare) || '',
            is_critical: !!c.isCritical,
        };
    }

    function exportRequisitionData() {
        openNewRequisition();
    }
    function resolveWrJobHeader(st, job) {
        if (!job) {
            return { pmsGroupNo: '', maker: '', modelType: '', capacity: '', serialNo: '' };
        }
        const gk = `${job.department || ''}|${String(job.group || '').trim()}`;
        const { equipment } = resolveJobEquipment(st, job);
        return resolveGroupHeaderByKey(st, gk, job.group || '', undefined, equipment);
    }

    function resolveGroupHeaderByKey(st, groupKey, groupLabel, _restoreKey, equipmentName) {
        const label = groupLabel
            ? safeTreeLabel(groupLabel)
            : (groupKey ? safeTreeLabel(String(groupKey).split('|').slice(1).join('|')) : '');
        const equipment = String(equipmentName || '').trim();
        const h = resolveSpareHeaderFromGroup(st, {
            groupKey,
            groupLabel: label,
            headerStore: 'pms',
            equipment,
        });
        return {
            pmsGroupNo: label || h.pmsGroupNo || '',
            maker: h.maker || '',
            modelType: h.modelType || '',
            capacity: h.capacity || '',
            serialNo: h.serialNo || '',
        };
    }

    function equipmentListInput(id, value, extraClass = '') {
        const cls = ['spare-equipment-input', extraClass].filter(Boolean).join(' ');
        return `<input class="${cls}" id="${id}" value="${escAttr(String(value ?? ''))}">`;
    }

    function renderEquipmentListModal() {
        const st = getState();
        const m = modState(st);
        const groupLabel = equipmentListGroupLabel(st);
        const body = document.getElementById('spareEquipmentListBody');
        if (!body) return;
        if (!groupLabel) {
            const treeName = equipmentStore(st) === 'pms' ? 'PMS GROUP Tree' : 'SPARE GROUP Tree';
            body.innerHTML = `<p class="muted">Select a group in ${treeName}.</p>`;
            return;
        }
        const store = equipmentStore(st);
        const defs = equipmentDefsForGroup(st, groupLabel);
        const editing = m.equipmentListEditKey;
        const draft = m.equipmentListDraft || {};
        const cell = (text) => esc(String(text || '').trim() || '—');
        const countCol = store === 'pms' ? 'Jobs' : 'Spares';
        const title = store === 'pms' ? 'PMS Equipment List' : 'SPARE Equipment List';
        let rows = '';
        defs.forEach(d => {
            const isEdit = editing === d.name;
            const eqDisp = d.equipmentNo ? String(d.equipmentNo).padStart(2, '0') : '—';
            if (isEdit) {
                rows += `<tr class="is-editing">
                    <td class="c-eqno">${equipmentListInput('eq_list_no', draft.equipmentNo ?? d.equipmentNo ?? '', 'eq-list-no')}</td>
                    <td>${equipmentListInput('eq_list_name', draft.name ?? d.name, 'eq-list-name')}</td>
                    <td>${equipmentListInput('eq_list_maker', draft.maker ?? d.maker)}</td>
                    <td>${equipmentListInput('eq_list_model', draft.modelType ?? d.modelType)}</td>
                    <td>${equipmentListInput('eq_list_capacity', draft.capacity ?? d.capacity)}</td>
                    <td>${equipmentListInput('eq_list_serial', draft.serialNo ?? d.serialNo)}</td>
                    <td class="c-num">${d.spareCount}</td>
                    <td class="c-act">
                        <button type="button" class="btn btn-sm btn-green" onclick="TVC_SpareMenu.saveEquipmentListItem()">💾</button>
                        <button type="button" class="btn btn-sm" onclick="TVC_SpareMenu.cancelEquipmentListEdit()">Cancel</button>
                    </td>
                </tr>`;
                return;
            }
            rows += `<tr>
                <td class="c-eqno">${eqDisp}</td>
                <td>${cell(d.name)}</td>
                <td>${cell(d.maker)}</td>
                <td>${cell(d.modelType)}</td>
                <td>${cell(d.capacity)}</td>
                <td>${cell(d.serialNo)}</td>
                <td class="c-num">${d.spareCount}</td>
                <td class="c-act">
                    <button type="button" class="btn btn-sm" onclick="TVC_SpareMenu.startEditEquipmentListItem('${escAttr(d.name)}')" title="Edit">✏️</button>
                    <button type="button" class="btn btn-sm btn-red" onclick="TVC_SpareMenu.deleteEquipmentListItem('${escAttr(d.name)}')" title="Delete">🗑</button>
                </td>
            </tr>`;
        });
        if (editing === '__new__') {
            const nextNo = draft.equipmentNo || nextEquipmentNoForGroup(st, groupLabel);
            rows += `<tr class="is-editing is-new">
                <td class="c-eqno">${equipmentListInput('eq_list_no', nextNo, 'eq-list-no')}</td>
                <td>${equipmentListInput('eq_list_name', draft.name || '', 'eq-list-name')}</td>
                <td>${equipmentListInput('eq_list_maker', draft.maker || '')}</td>
                <td>${equipmentListInput('eq_list_model', draft.modelType || '')}</td>
                <td>${equipmentListInput('eq_list_capacity', draft.capacity || '')}</td>
                <td>${equipmentListInput('eq_list_serial', draft.serialNo || '')}</td>
                <td class="c-num">—</td>
                <td class="c-act">
                    <button type="button" class="btn btn-sm btn-green" onclick="TVC_SpareMenu.saveEquipmentListItem()">💾</button>
                    <button type="button" class="btn btn-sm" onclick="TVC_SpareMenu.cancelEquipmentListEdit()">Cancel</button>
                </td>
            </tr>`;
        }
        if (!rows) {
            rows = '<tr><td colspan="8" class="empty-row muted">No Equipment registered. Click Add Equipment below.</td></tr>';
        }
        body.innerHTML = `
            <h3 class="spare-sync-title">${title}</h3>
            <p class="spare-equipment-list-sub">${esc(safeTreeLabel(groupLabel))} · ${store === 'pms' ? 'PMS GROUP' : 'SPARE GROUP'}</p>
            <p class="spare-sync-hint muted">EQ No. is the middle segment of Code (GG-<b>EE</b>-III). PMS and SPARE keep separate Equipment lists per group. Leave Maker~Serial blank to use group default.</p>
            <div class="spare-equipment-list-wrap">
                <table class="data-table spare-equipment-list-table">
                    <thead><tr>
                        <th>EQ No.</th><th>Equipment</th><th>Maker</th><th>Model / Type</th><th>Capacity</th><th>Serial No.</th><th>${countCol}</th><th></th>
                    </tr></thead>
                    <tbody>${rows}</tbody>
                </table>
            </div>
            <div class="modal-actions spare-equipment-list-actions">
                <button type="button" class="btn btn-sm" onclick="TVC_SpareMenu.startAddEquipmentListItem()"${editing ? ' disabled' : ''}>➕ Add Equipment</button>
                <button type="button" class="btn" onclick="TVC_SpareMenu.closeEquipmentListModal()">Close</button>
            </div>`;
    }

    async function openEquipmentListModal() {
        const st = getState();
        if (!canEditGroupHeader(st)) {
            await TVC_Dialog.alert('Chief Engineer, Chief Officer, Captain, or HQ Superintendent permission required.');
            return;
        }
        const groupKey = equipmentListGroupKey(st);
        const groupLabel = groupKey ? groupKeyLabel(st, groupKey) : '';
        if (!groupLabel) {
            const treeName = st.currentTab === 'actual' ? 'PMS GROUP Tree' : 'SPARE GROUP Tree';
            await TVC_Dialog.alert(`Select a group in ${treeName}, or select a spare item in the list first.`);
            return;
        }
        const m = modState(st);
        m.equipmentListOpen = true;
        m.equipmentListGroupKey = groupKey;
        m.equipmentListEditKey = null;
        m.equipmentListDraft = null;
        await reloadSpareGroupsCache();
        renderEquipmentListModal();
        document.getElementById('spareEquipmentListModal')?.classList.remove('hidden');
    }

    function closeEquipmentListModal() {
        const st = getState();
        const m = modState(st);
        m.equipmentListOpen = false;
        m.equipmentListGroupKey = null;
        m.equipmentListEditKey = null;
        m.equipmentListDraft = null;
        document.getElementById('spareEquipmentListModal')?.classList.add('hidden');
    }

    function startAddEquipmentListItem() {
        const st = getState();
        const m = modState(st);
        m.equipmentListEditKey = '__new__';
        m.equipmentListDraft = { equipmentNo: nextEquipmentNoForGroup(st, equipmentListGroupLabel(st)), name: '', maker: '', modelType: '', capacity: '', serialNo: '', oldName: '' };
        renderEquipmentListModal();
        setTimeout(() => document.getElementById('eq_list_name')?.focus(), 0);
    }

    function startEditEquipmentListItem(name) {
        const st = getState();
        const groupLabel = equipmentListGroupLabel(st);
        const d = equipmentDefsForGroup(st, groupLabel).find(x => x.name === name);
        if (!d) return;
        const m = modState(st);
        m.equipmentListEditKey = name;
        m.equipmentListDraft = {
            oldName: name,
            equipmentNo: d.equipmentNo,
            name: d.name,
            maker: d.maker,
            modelType: d.modelType,
            capacity: d.capacity,
            serialNo: d.serialNo,
        };
        renderEquipmentListModal();
    }

    function cancelEquipmentListEdit() {
        const st = getState();
        const m = modState(st);
        m.equipmentListEditKey = null;
        m.equipmentListDraft = null;
        renderEquipmentListModal();
    }

    async function saveEquipmentListItem() {
        const st = getState();
        const m = modState(st);
        if (!canEditGroupHeader(st)) {
            await TVC_Dialog.alert('Chief Engineer, Chief Officer, Captain, or HQ Superintendent permission required.');
            return;
        }
        const groupLabel = equipmentListGroupLabel(st);
        if (!groupLabel) return;
        const g = (id) => { const el = document.getElementById(id); return el ? el.value.trim() : ''; };
        const oldName = String(m.equipmentListDraft?.oldName || m.equipmentListEditKey || '').trim();
        const name = g('eq_list_name');
        const maker = g('eq_list_maker');
        const modelType = g('eq_list_model');
        const capacity = g('eq_list_capacity');
        const serialNo = g('eq_list_serial');
        let equipmentNo = parseInt(g('eq_list_no'), 10);
        if (!Number.isFinite(equipmentNo) || equipmentNo < 1) {
            equipmentNo = m.equipmentListEditKey === '__new__'
                ? nextEquipmentNoForGroup(st, groupLabel)
                : equipmentNoForName(st, groupLabel, oldName);
        }
        equipmentNo = Math.min(99, Math.max(1, equipmentNo));
        if (!name) {
            await TVC_Dialog.alert('Enter Equipment name.');
            return;
        }
        const names = equipmentNamesForGroup(st, groupLabel);
        if (name !== oldName && names.some(n => n.toLowerCase() === name.toLowerCase())) {
            await TVC_Dialog.alert(`Equipment “${name}” already exists in this group.`);
            return;
        }
        const others = equipmentDefsForGroup(st, groupLabel).filter(d => {
            if (m.equipmentListEditKey === '__new__') return true;
            return d.name !== oldName;
        });
        const taken = others.find(d => d.equipmentNo === equipmentNo);
        if (taken) {
            await TVC_Dialog.alert(`EQ No. ${String(equipmentNo).padStart(2, '0')} is already used by “${taken.name}”.`);
            return;
        }
        const dept = st.department || groupSelectedNode(st)?.department || '';
        const store = equipmentStore(st);
        const storeName = store === 'pms' ? 'maintenance_groups' : 'spare_groups';
        try {
            if (oldName && oldName !== name && oldName !== '__new__') {
                if (store === 'spare') {
                    const spares = sparesForEquipment(st, groupLabel, oldName);
                    if (spares.length) {
                        const rows = spares.map(s => TVC_SpareSchema.toRow({
                            ...canon(s),
                            equipment: name,
                            equipmentNo,
                        }));
                        if (typeof TVC_DB?.bulkPut === 'function') await TVC_DB.bulkPut('spare_parts', rows);
                        else {
                            const u = spareInventoryUser(st);
                            for (const r of rows) await TVC_Inventory.saveSpare(u, r);
                        }
                    }
                } else {
                    const jobs = jobsForEquipment(st, groupLabel, oldName);
                    if (jobs.length) {
                        const nextJobs = jobs.map(j => ({
                            ...j,
                            equipment: name,
                            equipment_no: equipmentNo,
                            updated_at: new Date().toISOString(),
                            sync_status: 'LOCAL',
                        }));
                        if (typeof TVC_DB?.bulkPut === 'function') await TVC_DB.bulkPut('maintenance_jobs', nextJobs);
                        st.jobs = (st.jobs || []).map(j => {
                            const hit = nextJobs.find(n => n.id === j.id);
                            return hit || j;
                        });
                    }
                }
                const oldDef = findEquipmentGroupDef(st, groupLabel, oldName, store);
                if (oldDef?.id) {
                    await TVC_DB.del(storeName, oldDef.id);
                    if (store === 'pms') st.groups = (st.groups || []).filter(gr => gr.id !== oldDef.id);
                    else st.spareGroups = (st.spareGroups || []).filter(gr => gr.id !== oldDef.id);
                }
            }
            const hasHeader = !!(maker || modelType || capacity || serialNo);
            await saveJobEquipmentHeader(spareInventoryUser(st), {
                department: dept,
                group: groupLabel,
                item_sort1: name,
                equipment_no: equipmentNo,
                maker,
                modelType,
                capacity,
                serialNo,
                header_edited: true,
            }, store);
            m.equipmentListEditKey = null;
            m.equipmentListDraft = null;
            await reloadSpareGroupsCache();
            renderEquipmentListModal();
            afterSpareListChange(st);
            await TVC_Dialog.alert(oldName && oldName !== name ? `Equipment renamed to “${name}”.` : `Equipment “${name}” saved.`);
        } catch (e) {
            await TVC_Dialog.alert(e.message || e.code || 'Save failed');
        }
    }

    async function deleteEquipmentListItem(name) {
        const st = getState();
        if (!canEditGroupHeader(st)) {
            await TVC_Dialog.alert('Chief Engineer, Chief Officer, Captain, or HQ Superintendent permission required.');
            return;
        }
        const groupLabel = equipmentListGroupLabel(st);
        const item = String(name || '').trim();
        if (!groupLabel || !item) return;
        const store = equipmentStore(st);
        const storeName = store === 'pms' ? 'maintenance_groups' : 'spare_groups';
        const spares = store === 'spare' ? sparesForEquipment(st, groupLabel, item) : [];
        const jobs = store === 'pms' ? jobsForEquipment(st, groupLabel, item) : [];
        const linked = store === 'pms' ? jobs.length : spares.length;
        const kind = store === 'pms' ? 'job(s)' : 'spare item(s)';
        const msg = linked
            ? `Delete ${store === 'pms' ? 'PMS' : 'SPARE'} Equipment “${item}”?\n\n${linked} ${kind} will lose this Equipment tag (group default header will apply).`
            : `Delete ${store === 'pms' ? 'PMS' : 'SPARE'} Equipment “${item}”?`;
        if (!await TVC_Dialog.confirm({ message: msg })) return;
        try {
            const def = findEquipmentGroupDef(st, groupLabel, item, store);
            if (def?.id) {
                await TVC_DB.del(storeName, def.id);
                if (store === 'pms') st.groups = (st.groups || []).filter(gr => gr.id !== def.id);
                else st.spareGroups = (st.spareGroups || []).filter(gr => gr.id !== def.id);
            }
            if (spares.length) {
                const rows = spares.map(s => TVC_SpareSchema.toRow({ ...canon(s), equipment: '', equipmentNo: 0 }));
                if (typeof TVC_DB?.bulkPut === 'function') await TVC_DB.bulkPut('spare_parts', rows);
                else {
                    const u = spareInventoryUser(st);
                    for (const r of rows) await TVC_Inventory.saveSpare(u, r);
                }
            }
            if (jobs.length) {
                const nextJobs = jobs.map(j => ({
                    ...j,
                    equipment: '',
                    equipment_no: 0,
                    updated_at: new Date().toISOString(),
                    sync_status: 'LOCAL',
                }));
                if (typeof TVC_DB?.bulkPut === 'function') await TVC_DB.bulkPut('maintenance_jobs', nextJobs);
                st.jobs = (st.jobs || []).map(j => {
                    const hit = nextJobs.find(n => n.id === j.id);
                    return hit || j;
                });
            }
            const m = modState(st);
            if (m.equipmentListEditKey === item) {
                m.equipmentListEditKey = null;
                m.equipmentListDraft = null;
            }
            renderEquipmentListModal();
            afterSpareListChange(st);
        } catch (e) {
            await TVC_Dialog.alert(e.message || e.code || 'Delete failed');
        }
    }

    async function saveJobEquipmentHeader(user, { department, group, item_sort1, equipment_no, maker, modelType, capacity, serialNo, header_edited, is_critical_equipment }, store) {
        if (!window.TVC_DB) return;
        const use = store || equipmentStore(getState());
        const storeName = use === 'pms' ? 'maintenance_groups' : 'spare_groups';
        const idPrefix = use === 'pms' ? 'grp-' : 'sgrp-';
        const dept = department || user?.department || '';
        const label = String(group || '').trim();
        if (!label) return;
        const item = String(item_sort1 || '').trim();
        const eqNo = parseInt(String(equipment_no ?? '').replace(/\D/g, ''), 10);
        const { vesselId } = await vesselScope().catch(() => ({ vesselId: null }));
        const defs = await TVC_DB.getAll(storeName).catch(() => []);
        const existing = (defs || []).find(gr => gr.department === dept
            && normalizeGroupLabel(gr.label) === normalizeGroupLabel(label)
            && String(gr.item_sort1 || '').trim() === item
            && (!vesselId || !gr.vessel_id || gr.vessel_id === vesselId));
        const defBase = existing || {
            id: idPrefix + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
            department: dept,
            label,
            sort_order: Number.isFinite(eqNo) && eqNo > 0 ? eqNo : 0,
            vessel_id: vesselId || null,
            created_at: new Date().toISOString(),
        };
        const row = {
            ...defBase,
            label,
            vessel_id: defBase.vessel_id || vesselId || null,
            item_sort1: item || null,
            equipment_no: Number.isFinite(eqNo) && eqNo > 0 ? eqNo : (equipmentNoFromRow(defBase) || null),
            machinery_name: defBase.machinery_name || '',
            model_type: modelType || '',
            maker: maker || '',
            capacity: capacity || '',
            serial_no: serialNo || '',
            header_edited: item ? true : (header_edited !== undefined ? !!header_edited : !!defBase.header_edited),
            updated_at: new Date().toISOString(),
            sync_status: 'LOCAL',
        };
        if (is_critical_equipment !== undefined) {
            row.is_critical_equipment = is_critical_equipment;
        }
        await TVC_DB.put(storeName, row);
        upsertEquipmentRowInState(getState(), row, use);
    }

    async function savePmsInlineHeaderCritical(user, { department, group, equipment, equipment_no, criticalRaw }) {
        if (!window.TVC_DB) return;
        const st = getState();
        const label = String(group || '').trim();
        if (!label) return;
        const dept = department || user?.department || st.department || '';
        const critVal = parseCriticalEquipmentValue(criticalRaw);
        const item = String(equipment || '').trim();
        if (item) {
            const eqNo = parseInt(String(equipment_no ?? '').replace(/\D/g, ''), 10);
            await saveJobEquipmentHeader(user, {
                department: dept,
                group: label,
                item_sort1: item,
                equipment_no: Number.isFinite(eqNo) && eqNo > 0 ? eqNo : equipmentNoForName(st, label, item, 'pms'),
                is_critical_equipment: critVal,
                header_edited: true,
            }, 'pms');
            return;
        }
        const groupKey = dept ? `${dept}|${label}` : label;
        await upsertGroupCriticalEquipment(st, critVal, groupKey);
    }

